// 自动生成：npm run quran:all（scripts/fetch-quran-all.mjs）。请勿手改经文。
export default {"19":["Kaaf, haa, yaa, ayn, sod.","Bu, Robbingning bandasi Zakariyoga rahmati zikridir. (Yaʼni, ey Muhammad (s. a. v.), ushbu qissa «Robbingning bandasi Zakariyoga rahmati zikridir».)","Uning Robbiga maxfiy nido qilgan chogʻini esla.","U: «Ey Robbim, mening suyaklarim moʻrtlashdi, boshga oq tutashdi, ey Robbim, senga duo qilish-la badbaxt boʻlmaganman.","Va, albatta, men ortimdagi qarindoshlardan qoʻrqdim. Ayolim tugʻmas edi. Bas, menga Oʻz dargohingdan bir valiy–ortdan qolguvchi ato et.","U menga va Yaʼqub oilasiga merosxoʻr boʻlsin. Ey Robbim, uni Oʻzing rozi boʻladigan qil», dedi.","Ey Zakariyo, Biz senga ismi Yahyo boʻlgan bir oʻgʻilning xushxabarini beramiz. Bundan oldin unga otdosh qilgan emasmiz. (Koʻrinib turibdiki, Alloh taolo Zakariyo alayhissalomga buyuk rahmat nazari bilan boqdi. Farzand beribgina qolmay, unga Oʻzi Yahyo, deb ism ham qoʻydi. Bularning bari dunyoga kelayotgan farzandining kelajagi juda qutlugʻligidan darak berar edi.)","U: «Ey Robbim, ayolim tugʻmas boʻlsa, oʻzim qarib-chirib qolgan boʻlsam, qanday qilib mening oʻgʻlim boʻlsin?!» dedi.","U: «Ana shunday! Robbing aytdiki, bu men uchun oson. Batahqiq, bundan oldin seni yaratdim. Holbuki, sen hech narsa emas eding», dedi.","U: «Robbim, menga bir belgi ato qil», dedi. U zot: «Sening belging salomat holingda, odamlarga uch kecha gapirmasligingdir», dedi.","Bas, u oʻz qavmi huzuriga mehrobdan chiqdi va ularga, ertayu kech tasbih aytinglar, deb ishora qildi. (Sogʻlom holda tildan qolgan Zakariyo alayhissalom mehrobda ibodat, tasbih va Tavrot tilovati bilan mashgʻul boʻldilar. Mehrobdan chiqib qavmlariga, ertayu kech Allohga tasbih aytinglar, deb ishora qildilar. Bu bilan qavmlarini birga ibodat qilishga, berilgan ulugʻ neʼmat shukronasini ado etishga chorladilar. Shu nuqtada Zakariyoga alayhissalom tegishli tarix xotima topadi. Yahyo alayhissalomning tavalludlari, hayotlariga taalluqli boshqa tarixlar bayon etilmay, bir yoʻla ul zotga kitob nozil etilish qissasi zikr etiladi.)","«Ey Yahyo, kitobni quvvat-la ol!» (dedik) va unga goʻdakligidayoq hukmni berdik. (Alloh taolo Yahyo alayhissalomga, ilohiy Tavrotni quvvat bilan ol, demoqda. Oyatdagi: «Unga goʻdakligidayoq hukmni berdik», degan jumlani ulamolarimiz ilmu hikmat mazmunida taʼvil qilganlar.)","Va Oʻz tomonimizdan mehribonlik va poklik (berdik). Hamda u taqvodor edi.","U ota-onasiga mehribon boʻlib, jabr-sitam qilguvchi va isyonchi emasdi.","Unga tugʻilgan kunida ham, oʻladigan kunida ham, qayta tiriladigan kunida ham salomlar boʻlsin.","Kitobda Maryamni esla. U oʻz ahlidan sharqiy makonga ajrab chiqqanda.","Va ular bilan oʻzi orasida toʻsiq olganda, Biz unga Oʻz ruhimizni yubordik. Bas, u unga bus-butun odam boʻlib koʻrindi. (Yaʼni, ey Muhammad, bu kitobda (Qurʼonda) Maryamni esla. Baytul Maqdisda yashayotgan, bokira, taqvodor qiz Maryam, shaharning sharqiy tomoniga yolgʻiz chiqdi. Nimaga chiqqanini Alloh biladi. Qavmidan hech kim Maryamni koʻrmaydigan boʻldi. U xoli va yolgʻiz qoldi. Jabroil alayhissalom Maryamga toʻla-toʻkis odam siymosida namoyon boʻldi. Alloh uni yaratgan asl holatida koʻrinmadi. Chunki bus-butun holida koʻrinsa, Maryam butkul dahshatga tushishi mumkin edi.)","U: «Men sendan Alloh panoh berishini soʻrayman. Agar taqvodor boʻlsang...» dedi.","U: «Men Robbingning elchisiman, xolos, senga bir pok oʻgʻilni hadya etish uchun keldim», dedi.","U: « Menda qayoqdan oʻgʻil boʻlsin, menga bashar tegmagan boʻlsa, men buzuq ham boʻlmasam?!» dedi.","U: «Ana shunday, Robbing aytdiki, bu Men uchun osondir va uni odamlarga belgi qilish uchun hamda Bizdan rahmat boʻlish uchun, bu, hukmi chiqib boʻlgan ishdir», dedi.","Bas, unga homilador boʻldi. Soʻngra u bilan uzoq makonga chetlandi. (Yaʼni, Jabroil alayhissalom Maryamning yoqasidan puflaganidan keyin Iysoga alayhissalom homilador boʻldi.)","Bas, toʻlgʻoq uni xurmo tanasiga olib bordi. U: «Koshki bundan oldin oʻlsam edi va butunlay unutilib ketsam edi», dedi.","Uning ostidan: «Mahzun boʻlma, batahqiq, Robbing ostingdan oqar ariq qildi.","Xurmo tanasini silkit, senga yangi meva tushiradi», deb nido qildi. (Tafsirchi ulamolarimiz ushbu oyati karimani ikki xil talqin qiladilar. Baʼzilar «Uning ostidan» iborasini xurmoning ostidan maʼnosida, «nido qildi» iborasini, farishta nido qildi mazmunida sharhlaganlar. Ayrim ulamolar esa, «Uning ostidan»ni «Maryamning ostidan» va «nido qildi»ni, Iyso nido qildi, deb talqin etganlar.)","Ye, ich va koʻzing quvonsin. Bas, biror odamni koʻrar boʻlsang: «Men Rohmanga roʻza nazr qildim. Bugun inson zotiga zinhor gapirmasman», degin.","Bas, uni koʻtarib qavmiga olib keldi. Ular: «Ey Maryam, sen ajoyib narsa keltirding-ku!","Ey Horun singlisi, otang yomon odammas va onang ham buzuq boʻlmagan edi-ku!» dedilar. (Bibi Maryam Iyso alayhissalomni koʻtarib qavmi huzuriga bordi. Qavm bu holni koʻrib hayratga tushdi. Darhol Maryamni tergab, dashnom bera boshladi.)","Bas, u unga ishorat qildi. Ular: «Beshikdagi goʻdak ila qanday gaplashamiz?!» dedilar. (Beshikdagi bola hech qachon gapirmaydi. Ammo Alloh har narsaga qodir. U xohlagan ish boʻladi. Beshikdagi goʻdak Iyso alayhissalom tilga kirdilar.)","U: «Albatta, men Allohning bandasiman. U menga kitob berdi va meni Paygʻambar qildi.","Meni qayerda boʻlsam ham, muborak qildi. Modomiki hayot ekanman, namoz va zakotni ado etmoqni tavsiya qildi.","Meni onamga mehribon qildi va jabr-sitam qilguvchi, badbaxt qilmadi.","Menga tugʻilgan kunimda ham, oʻladigan kunimda ham va qayta tiriladigan kunimda ham salom bordir«, dedi.","Mana shu shubha qilishayotgan Iyso ibn Maryam toʻgʻrisidagi haq soʻzdir. (Baʼzilar uni «xudo» dedilar, baʼzilar onalari Bibi Maryamni zinokorlikda aybladilar. Bu quruq va asossiz soʻzlarga emas, Allohning haq kalomiga ishonish kerak.)","Bola tutmoq Allohga hech toʻgʻri kelmas. U bundan pokdir. U bir ishni istasa, unga «Boʻl!» deydir. Bas, boʻladir.","«Va, albatta, Alloh mening Robbimdir va sizning Robbingizdir. Bas, Unga ibodat qiling. Mana shu toʻgʻri yoʻldir».","Soʻngra firqalar oʻzaro ixtilofga tushdilar. Kufr keltirganlarga buyuk kundagi koʻrinishdan voy boʻlsin. (Nasorolar hozirgacha Iyso alayhissalom xususida ixtilofdalar. Baʼzilari, Iyso Allohning oʻgʻli desa, baʼzilari Iyso ota, oʻgʻil va muqaddas ruhdan iborat uchlikning biri deydi; baʼzilari esa, Iyso ota xudo, ona xudo va bola xudodan biri–bola oʻgʻil xudo, deydilar. Ularning orasida Iyso alayhissalom Allohning bandasi, Rasuli, ruhi va kalimasi deydiganlar ham bor. Ammo hanuzgacha mazkur ixtiloflar davom etib kelmoqda.","Bizga keladigan kuni qanday ham yaxshi eshitadilar, qanday ham yaxshi koʻradilar. Lekin zolimlar bugungi kunda ochiq zalolatdadirlar.","Ularni hasrat kunidan, ish bitmish paytidan ogoh qil. Ular gʻaflatdadirlar, ular iymon keltirmaslar.","Albatta, Biz yerga va uning ustidagi kimsalarga merosxoʻr boʻlamiz va Bizgagina qayturlar.","Kitobda Ibrohimni esla. Albatta, u siddiq va Nabiy boʻlgan edi.","Qachonki u otasiga: «Ey otam, nima uchun eshitmaydigan, koʻrmaydigan va senga biron foyda bera olmaydigan narsaga ibodat qilasan?","Ey otam, albatta, senga kelmagan ilm menga keldi. Bas, menga ergash, seni toʻgʻri yoʻlga boshlayman.","Ey otam, shaytonga ibodat qilma. Albatta, shayton Rohmanga osiy boʻlgandir.","Ey otam, albatta, men seni Rohman tomonidan azob tutishidan va shaytonga doʻst boʻlib qolishingdan qoʻrqaman», degan edi.","U: «Ey Ibrohim, sen mening xudolarimdan yuz oʻgiruvchimisan?! Qasamki, agar toʻxtamasang, seni, albatta, toshboʻron qilaman! Mendan uzoq ket!» dedi.","U: «Omon boʻl. Endi Robbimdan seni magʻfirat qilishini soʻrayman. Albatta, u menga juda ham lutfi marhamatlidir.","Men sizlardan ham, Allohdan oʻzga iltijo qilayotgan narsangizdan ham chetlanaman va Robbimga iltijo qilaman. Shoyadki, Robbimga iltijo qilish ila badbaxt boʻlmasam», dedi.","Bas, ulardan va ular Allohdan oʻzga ibodat qilayotgan narsadan chetlanganida, Biz unga Isʼhoq va Yaʼqubni hadya etdik va barchalarini Paygʻambar qildik. (Ibrohim alayhissalom Allohni, Uning dinini deb oʻz vatanlari, qavm-qarindoshlarini tark etib, hijrat qilgan edilar. Alloh taolo u zotni yolgʻiz qoʻymadi. Qarib qolgan boʻlsalar ham, Isʼhoq va Yaʼqubni berdi. Ibrohim alayhissalom nasabini bardavom ayladi. Eng muhimi, ularning hammasini Paygʻambar qildi.)","Va ularga Oʻz rahmatimizdan hadya etdik hamda ularga rostgoʻy va oliy til berdik.","Kitobda Musoni esla. Albatta, u tanlab olingan Nabiy va Rasul edi. (Ey Muhammad, ilohiy Kitob–Qurʼonda Muso alayhissalom qissasini esla. U Alloh taolo tomonidan tanlab olingan banda: ham Nabiy va ham Rasul edi. Biz Alloh tomonidan bandalarga yetkazish uchun koʻrsatmalar olgan shaxsni Paygʻambar deb odatlanib qolganmiz. Aslida esa, Paygʻambarlik mohiyat jihatidan ikki turlidir. Bir turlariga «Nabiy», boshqalariga «Rasul» deyiladi. Nabiylar Allohdan vahiy kelgan, biroq kitob berilmagan, shuningdek, daʼvatlari keng ommaga emas, oʻzlari uchungina kifoya qilgan zotlardir. Rasul Alloh tomonidan vahiy berilgan, daʼvatlari keng ommaga moʻljallangan zot hisoblanadilar. Muso alayhissalom ushbu ikki sifatni oʻzlarida mujassam qilgan Paygʻambarlardan biridir.)","Biz unga Turning oʻng tomonidan nido qildik va munojot uchun Oʻzimizga yaqinlashtirdik.","Va unga Oʻz rahmatimizdan ogʻasi Horunni Paygʻambar qilib hadya etdik. (Ogʻalari Horunning Paygʻambar boʻlishini Musoning alayhissalom oʻzlari Alloh taologa duo qilib soʻragan edilar.)","Va kitobda Ismoilni esla. Albatta, u vaʼdasiga sodiq hamda Rasul va Nabiy boʻlgan edi.","U ahlini namozga va zakotga buyurar edi va Robbi nazdida rozi boʻlgan edi.","Va kitobda Idrisni esla. Albatta, u siddiq va Nabiy boʻlgan edi.","Va uni oliy maqomga koʻtardik. (Uning qadrini yuksak, zikrini oliy qildik. Dunyoda shunday oliymaqom zotlar oʻtgan.)","Ana oʻshalar, Alloh neʼmat bergan zotlar, Paygʻambarlardan, Odam zurriyotidan, Nuh bilan birga (kemada) koʻtarganlarimizdan, Ibrohim va Isroilning zurriyotidan, Oʻzimiz hidoyat qilgan va tanlab olganlardan boʻlgan zotlar, ularga Rohmanning oyati tilovat qilinsa, yigʻlab sajdaga yiqilardilar.","Bas, ularning ortidan bir oʻrinbosarlar qoldiki, ular namozni zoye qilib, shahvatlarga ergashdilar. Bas, tezda ular yomonlikka yoʻliqdilar. (Rohmanning oyati tilovat qilinganda yigʻlab, sajdaga otiladigan hassos zotlar ortidan, nobakor, fosiq va betavfiq oʻrinbosarlar keldi. Bu betavfiq kimsalar namozni zoye qildilar, shahvatga ergashadilar. Shahvatga ergashgan zalolatga yuz buradi. Zalolatga ketganga esa, halokat yetadi.)","Magar kim tavba qilsa va iymon keltirib, amali solih qilsa, bas, ana oʻshalar jannatga kirurlar va hech zulm qilinmaslar. (Kim tavba qilsa, noshoyista amalidan afsus-nadomat chekib, toʻgʻri yoʻlga qaytsa, soʻngra iymon keltirib, moʻmin boʻlsa va yaxshi amallarni ado etsa, yomonlikka uchramaydi.)","Rohman Oʻz bandalariga gʻaybdan vaʼda qilgan adn jannatlaridir. Albatta, Uning vaʼdasi kelgusidir.","Ular unda behuda soʻz eshitmaslar, illo, salom eshiturlar. Ularga u yerda ertayu kech rizqlari kelib turur.","U jannat, bandalarimizdan taqvodor boʻlganlariga meros qilib beradigan jannatimizdir.","Biz faqat Robbingning amri bilangina tushamiz. Bizning oldimizdagi narsalar va ortimizdagi narsalar hamda ularning orasidagi narsalar ham Unikidir. Robbing unutguvchi boʻlmagan. (Yaʼni, ey Muhammad, bizda oʻzimizcha tushaverish ixtiyori yoʻq. Qachonki amr qilsagina, huzuringga tushamiz. Aks holda, amrni kutib turaveramiz. Jamiki narsa Allohning izmida. Bizning oldimizdagi va ortimizdagi hamda har ikkisining orasidagi narsalar Unikidir.)","U osmonlaru yerning va ular orasidagi narsalarning Robbidir. Bas, Unga ibodat qil va Uning ibodatida sabrli boʻl. Unga tengdoshni bilurmisan? (Inson sabr-matonat ila Allohga ibodat qilib, butun hayotini uning koʻrsatmasiga mos etib yashagandagina maqsadga noil boʻladi.)","Inson: «Agar oʻlsam, yana qayta tirik holda chiqarilamanmi?!» deydi.","Oʻsha inson Biz uni bundan oldin hech narsa boʻlmay turganida yaratganimizni eslamaydimi?!","Robbingga qasamki, Biz ularni va shaytonlarni, albatta, mahsharga toʻplaymiz, soʻngra ularni jahannam atrofiga tiz choʻkkan hollarida hozir qilamiz.","Soʻngra har bir guruhdan Rohmanga ashaddiy osiy boʻlganini sugʻurib olamiz. (Anchayin chorlab yoxud taklif qilib emas, shiddat bilan sugʻurib olinadi. Demak, kofirlar shaytonlari bilan jahannam atrofiga oʻtqazib qoʻyilib, qilgan gunohlariga qarab birin-ketin doʻzaxga tashlanadilar. Qolganlari navbat kutib, kuzatib turadilar.)","Keyin, albatta, Biz u(jahannam)ga kirishga kimlar loyiqroq ekanini yaxshi bilguvchimiz.","Sizdan unga yaqinlashuvchi boʻlmagan hech kim yoʻq. Bu Robbing huzuridagi keskin hukmdir. (Alloh taolo Anbiyo surasida moʻminlar haqida: «Ana oʻshalar u (jahannam)dan uzoqlashtirilganlar, uning ovozini ham eshitmaydilar» degan, shuning uchun ham bu oyatga «Sizdan unga yaqinlashuvchi boʻlmagan hech kim yoʻq», deb maʼno bersak asliga muvofiq boʻladi. Binobarin, moʻminlar jahannamga, xususan, sirotdan oʻtayotganlarida yaqinlashadilar, biroq tushmay oʻtib ketadilar. Kofirlar esa, yaqinlashib, jahannam atrofida tiz choʻkib oʻtiradilar va gunohlariga mos ravishda ketma-ket doʻzaxga tashlanadilar.)","Soʻngra taqvo qilganlarga najot beramiz va zolimlarni unda tiz choʻkkan hollarida qoldiramiz.","Qachonki ularga Bizning ravshan oyatlarimiz tilovat qilinsa, kufr keltirganlar iymon keltirganlarga: «Ikki guruhning qaysi biri maqom va majlis jihatidan yaxshiroqdir?» derlar.","Holbuki, Biz ulardan oldin mol va koʻrinish jihatidan yaxshiroq boʻlgan qanchadan-qancha asrlarni halok qilganmiz.","Sen: «Kim zalolatda boʻlsa, Rohman unga muhlat berib qoʻysin. Toki oʻzlariga vaʼda qilingan narsani — azobni yoki qiyomatni koʻrganlarida, albatta, kimning martabasi yomonroq va askari kuchsizroq ekanini bilurlar», degin.","Va Alloh hidoyatga yurganlarning hidoyatini ziyoda qiladir. Boqiy qoluvchi, solih amallar, Robbing nazdida, savob jihatidan yaxshiroqdir va oqibat jihatidan yaxshiroqdir.","Oyatlarimizga kufr keltirgan va: «Albatta, (oxiratda) menga molu dunyo hamda bola-chaqa berilajak», deganni koʻrdingmi?!","U gʻoyibni bilarmikan yoki Rohmanning huzuridan ahdu paymon oldimikan?! (Gʻoyibda unga oxiratda albatta molu dunyo hamda bola-chaqa berilishi muqarrar ekanligi haqida alomat bormikan?)","Yoʻq! Nima deganini, albatta, yozib qoʻyamiz va unga azobni uzundan-uzoq qilamiz.","U aytayotgan narsaga merosxoʻr boʻlurmiz va u bizga yolgʻiz holida kelur. (Kofir molu mulk, bola-chaqa va boshqa dunyoviy narsalaridan judo boʻlgan yolgʻiz holida bizga–huzurimizga keladi. Oʻsha payt u bilan qanday muomala qilishni oʻzimiz bilamiz.)","Ular oʻzlariga kuch-qudrat, izzat boʻlishi uchun Allohdan oʻzgalarni xudo qilib oladilar.","Yoʻq! u(xudo)lar ularning ibodatlarini inkor eturlar va ularga zid boʻlurlar. (Qiyomat kuni soxta xudolar mushriklarning ularga qilgan ibodatini, bandaligini inkor etadilar. Biz ularga, bizga ibodat qiling deganimiz yoʻq, deb Alloh huzurida oʻzlarini oqlaydilar.)","Biz shaytonlarni kofirlarga ularni doimiy qoʻzgʻab turishga yuborganimizni koʻrmadingmi?","Ularning ziddiga shoshilma! Biz ularning sanogʻini sanamoqdamiz.","Taqvodorlarni Rohman huzuriga mehmon hayʼati etib toʻplagan kunimizda.","Jinoyatchilarni jahannamga chanqoq hollarida haydaymiz.","Ular shafoatga molik boʻlmaslar. Magar kim Rohman huzurida ahdu paymon olgan boʻlsa (molik boʻlur). (Shafoatga molik boʻlganlar faqat Allohning Oʻzidan bu haqda ahdu paymon olganlardir, xolos.)","Ular: «Rohman bola tutdi», dedilar.","Batahqiq, juda ogʻir narsa keltirdingiz.","Undan osmonlar parchalanib, yer yorilib, togʻlar qulab yiqilay, deydir.","Rohmanning bolasi bor, deganlariga.","Rohmanga bola tutish loyiq emasdir. (Uning bola tutishga hojati yoʻq. U farzand talabida emas. Bu uning shaʼniga toʻgʻri kelmaydi. Rohman yakkadir. Vohid va Biru Bordir.)","Osmonlaru yerdagi barcha kimsalar Rohmanga banda boʻlgan hollarida kelurlar.","Batahqiq, U zot ularni ihota qilgan va sanab qoʻygandir.","Ularning barchalari U zotning huzuriga qiyomat kuni yolgʻiz hollarida kelguvchidirlar.","Albatta, iymon keltirgan va yaxshi amallarni qilganlarga Rohman muhabbat paydo qilur.","Bas, albatta, taqvodorlarga xushxabar berishing va u bilan sarkash qavmlarni ogohlantirishing uchun u(Qurʼon)ni tilingga oson qildik.","Ulardan oldin qanchadan-qancha asr(ahli)ni halok qildik. Ulardan birortasini his etasanmi yoki sharpasini eshitasanmi?!"],"20":["Toho.","Senga Qurʼonni badbaxt boʻlishing uchun nozil qilganimiz yoʻq.","Magar qoʻrqqan kimsalarga eslatma boʻlishi uchun.","U yerni va yuksak osmonlarni yaratgan zotdan nozil boʻlgandir.","U–Rohman Arshni egalladi. (Rohman sifatining sohibi Alloh Arshni egalladi. Arshni egallashining esa, oʻxshashi yoʻq, misli yoʻq, shakli ham yoʻq. Uning egallashi oʻziga xos.)","Osmonlardagi narsalaru yerdagi narsalar, ularning orasidagi narsalaru yer ostidagi narsalar Unikidir.","Sen agar soʻzda ovozingni yuksaltirsang ham. Bas, albatta, u sirni ham, maxfiyni ham bilguvchidir.","Alloh–undan boshqa ibodatga sazovor iloh yoʻq zotdir. Goʻzal ismlar Unikidir.","Senga Musoning xabari keldimi?","U olovni koʻrgan chogʻida oʻz ahliga: »Turib turinglar, men olovni koʻrdim, shoyad sizga undan choʻgʻ keltirsam yoki olov boshida yoʻl koʻrsatuvchini topsam«, dedi. (Oyati karimada Muso alayhissalom Madyandan Misrga kelayotganlarida roʻy bergan hodisa bayon etilmoqda.)","Bas, u(olov)ga kelganida, nido qilindi: «Ey Muso.","Albatta, Men Oʻzim sening Robbingdirman. Kavushlaringni yech. Chunki sen muqaddas Tuvo vodiysidasan».","Men seni ixtiyor qilib oldim. Vahiy qilinadigan narsaga quloq os.","Albatta, Men, Oʻzim, Allohdirman. Mendan oʻzga iloh yoʻq. Bas, Menga ibodat qil va meni zikr etish uchun namozni toʻkis ado et.","Albatta, (qiyomat) soati kelguvchidir. Har bir jon saʼyi-harakatiga yarasha jazo olishi uchun uni maxfiy tuturman.","Hargiz seni unga iymon keltirmaydiganlar va havoyi nafsiga ergashganlar undan toʻsmasinlar. U holda halok boʻlasan».","«Ey Muso, qoʻlingdagi nima?»","U: «Bu asoimdir, unga suyanaman, u bilan qoʻylarimga (barg) qoqib beraman va unda mening boshqa ishlarim bor», dedi.","U zot: «Ey Muso, uni tashla», dedi.","Bas, uni tashladi. Birdan u(aso) ilon boʻlib yura boshladi.","U zot: «Uni ol, qoʻrqma. Biz uni avvalgi holiga keltiramiz.","Qoʻlingni qoʻltigʻingga tiq, yomonliksiz oppoq boʻlib chiqadi. Bu boshqa bir moʻjizadir. (Qoʻl oppoq boʻldi, ammo bu oqlikda yomonlik yoʻqdir. Yaxshilik bor. Juda chiroyli boʻlib koʻrinadi. Bunday boʻlishi sening Paygʻambar ekanligingni tasdiqlovchi asodan keyingi yana bir moʻjizadir.)","Biz senga buyuk moʻjizalarimizni koʻrsatish uchun(shunday qildik).","Sen Firʼavnga bor, albatta u tugʻyonga ketdi», dedi.","U: «Ey Robbim, mening qalbimni keng qil.","Mening ishimni oson qil.","Tilimdagi tugunni yechgin.","Soʻzimni anglasinlar.","Menga oʻz ahlimdan bir vazir qilib ber.","Ogʻam Horunni.","U bilan belimni quvvatla.","Uni ishimga sherik ayla.","Senga koʻp tasbih aytishimiz uchun.","Va Seni koʻp zikr qilishimiz uchun.","Albatta, Sen Oʻzing bizni koʻrib turuvchi eding», dedi.","U zot: «Ey Muso, senga soʻraganing berildi», dedi. (Bir ogʻiz gap bilan hal qilib qoʻydi. Nimani soʻragan boʻlsalar, berdi.)","«Batahqiq, Biz senga boshqa marta ham neʼmat bergan edik. (Yaʼni, hozir bergan neʼmatlarimizdan boshqa ham neʼmat bergan edik.)","Oʻshanda onangga ilhom qilinadigan narsani ilhom qilgan edik.","«Uni tobutga sol, uni esa, daryoga tashla. Daryo uni sohilga otsin. Uni Mening dushmanim va uning dushmani oladir», dedik. Va senga Oʻzimdan muhabbat soldim. Buni Mening koʻz oldimda yetishtirilishing uchun (qildim). (Musoning onasi Alloh bergan ilhom bilan uni sandiqqa solib, suvga oqizib yuboradi. Musoning Oʻz koʻzi ostida voyaga yetishi uchun dushman Firʼavnning uyiga uni joylashtirgan, qalbiga uning muhabbatini solgan Zot onaning farzand firoqida qiynalishiga ham barham berdi. Murgʻak Muso ayollarning bittasini ham emmay qoʻydi. Musoning opasini Firʼavn saroyiga yuborib, shu bolani emizadigan ayol bor, deb aytishni buyuradi.)","Oʻshanda opang yurib borib: «U (Muso)ni kafillikka oladiganlarga dalolat qilaymi? « degan edi. Bas, Biz seni koʻzi quvonishi va xafa boʻlmasligi uchun onangga qaytardik. Va bir jonni oʻldirding. Bas, Biz seni gʻamdan qutqardik va turli sinovlar ila sinadik. Soʻngra Madyan ahli ila yillarga qolding va taqdirga binoan kelding, ey Muso!","Men seni Oʻzim uchun tanladim. (Yaʼni, Paygʻambar qilib oldim. Keyin esa, Paygʻambarlik vazifasiga oid topshiriqlar berildi:)","Sen va ogʻang moʻjizalarimni olib boringlar va Meni zikr etishda sustkashlik qilmanglar.","Firʼavnga boringlar! Chunki, u tugʻyonga ketdi.","Bas, unga yumshoq soʻz aytinglar. Shoyad eslasa yoki qoʻrqsa». (Yumshoq soʻz tasir qilishi mumkin. Yumshoq soʻz kofirni va tugʻyonga ketgan shaxsni ham muloyim qilib qoʻyishi mumkin. Shoyad Firʼavn ham oʻziga kelib, insof qilsa.)","Ikkovlari: «Ey Robbimiz, biz uning tezda bizga yomonlik qilishidan yoki haddan oshishidan qoʻrqamiz», dedilar.","U zot: «Qoʻrqmanglar! Albatta, Men sizlar bilanman, eshitaman va koʻraman», dedi.","Bas, uning oldiga boringlar va unga: «Albatta, biz Robbingning Paygʻambarlarimiz, Bani Isroilni biz bilan qoʻyib yubor. Ularni azoblama. Batahqiq, biz senga Robbingdan moʻjiza keltirdik. Hidoyatga ergashgan kimsaga salom boʻlur.","Albatta, bizga vahiy qilindiki, yolgʻonga chiqarganlarga va yuz oʻgirib ketganlarga shubhasiz azob boʻlur», denglar.","U: «Ey Muso, ikkovingizning Robbingiz kim?» dedi.","U: «Bizning Robbimiz har narsaga oʻz yaratilishini bergan hamda uni hidoyatga solgan zotdir», dedi.","U: «Oʻtgan asrlarning holi nedir?» dedi.","U: «Ularning ilmi Robbim huzurida, kitobdadir. Robbim adashmas va unutmas. (Yaʼni, oʻtgan asrlar haqidagi barcha ilm Robbim huzuridagi kitobda yozilgandir. Qancha asrlar oʻtib, qancha odamlar yashab, nima ishlar qilgan boʻlsalar, hamma-hammasi Robbim huzurida turibdi, kitobda yozilgan. Shunga qarab jazolaydi yoki mukofotlaydi.)","U sizga yerni beshik qilgan, sizga unda yoʻllar ochgan va osmondan suv tushirgan zotdir», dedi. Bas, oʻsha (suv) ila turli nabototlar juftlarini chiqardik.","Yenglar va chorvalaringizni boqinglar. Albatta, bunda aql egalari uchun ibratlar bordir.","Sizlarni undan yaratdik, unga qaytaramiz va yana bir bor undan chiqarib olamiz. (Yaʼni, Biz sizlarni yerdan yaratdik, oʻlganingizdan soʻng yana unga qaytaramiz. Qiyomat kuni esa, sizlarni qayta tiriltirib, yerdan chiqarib olamiz. Ey Firʼavn, sen ham odamsan, sening ham boshingga shu kun tushadi.)","Batahqiq, Biz unga oyat-moʻjizalarimizning hammasini koʻrsatdik. Bas, u yolgʻonga chiqardi va bosh tortdi.","U: «Ey Muso, bizni yerimizdan chiqarish uchun sehring ila keldingmi?!","Bas, albatta, biz ham unga oʻxshash sehr keltiramiz, biz bilan oʻzing orangda vaʼda vaqti tayin qil, unga biz ham, sen ham xilof qilmaydigan boʻlaylik, oʻrta joy boʻlsin«, dedi.","U: «Vaʼda vaqtingiz ziynat kuni. Odamlarning choshgohda toʻplanishi», dedi. (Misrliklarning «ziynat kuni» katta bayrami boʻlib, unda barcha xaloyiq ziynatli kiyimlar kiyib chiqar edilar. Muso alayhissalom hamma guvoh boʻlsin deb ziynat kunini tanladilar.)","Bas, Firʼavn qaytib ketdi, soʻngra hiylasini yigʻib keldi. (Oyati karima, uchta holatni tasvir etmoqda. Firʼavn Muso alayhissalom bilan boʻlgan uchrashuvdan qaytib ketdi. Keyin hiylasini yigʻdi–hamma kuchli sehrgarlarini toʻpladi. Soʻngra yana qaytib keldi. Tortishuv, musobaqaga tayyorgarlik nihoyasiga yetdi.)","Ularga Muso: «Holingizga voy! Allohga nisbatan yolgʻon uydirmang, bas, sizni azob ila butunlay halok qilur. Batahqiq, kim yolgʻon uydirsa, noumid boʻlur», dedi.","Bas, ular ishlari haqida oʻzaro asta shivirlashib, munozara qila boshladilar.","Ular: «Albatta, bu ikkovi sehrgardirlar. Sizni sehrlari bilan yerlaringizdan chiqarishni va sizning afzal yoʻlingizni yoʻqotishni xohlaydilar.","Bas, makr-hiylangizni jamlab, bir saf boʻlib keling. Batahqiq, bugungi kunda kim ustun kelsa, oʻsha gʻolib boʻladir», dedilar.","Ular: «Ey Muso, sen tashlaysanmi yoki biz avval tashlovchi boʻlaylikmi?» dedilar.","U: «Yoʻq. Sizlar tashlang», dedi. Birdan ularning arqonlari va asolari unga sehrlaridan xuddi harakatlanayotgandek boʻlib koʻrindi.","Bas, Muso ichida xavf his etdi.","Biz: «Qoʻrqma, albatta, sen ustunsan.","Qoʻlingdagi narsani tashlagin, ularning qilgan hunarini yutib yuboraur. Ularning qilgan hunari sehrgarning hiylasi, xolos. Sehrgar qayerda boʻlsa ham, zafar topmas», dedik. (Firʼavnlar va ularning gumashtalari-sehrgarlari doimo hiyla-nayranglar ila xalqning koʻzini boʻyab kelganlar. Ularning botili haq koʻrinmagan paytda oʻtadi, xolos. Haq kelganida, botil yoʻq boʻladi. Sen Robbingdan haq keltirding, endi ularning botili yoʻqoladi. Alloh taoloning amri ila Muso alayhissalom qoʻllaridagi asoni yerga tashladilar. U sehrgarlarning hunarini yutib yubordi.)","Bas, sehrgarlar: «Horun va Musoning Robbiga iymon keltirdik», deb sajdaga tashlandilar.","U: «Sizga izn bermasimdan oldin unga iymon keltirdingizmi?! Albatta, u sizga sehr oʻrgatgan kattangizdir! Bas, albatta, qoʻl-oyoqlaringizni qarama-qarshisidan kesurman va, albatta, sizlarni xurmo tanasiga osurman, albatta, qaysi birimizning azobimiz shiddatliroq va boqiyroq ekanini bilursiz», dedi. (Firʼavn oʻz qarichi bilan oʻlchar edi. U tahdid, azob-uqubat, qiynash, chopish-kesish, oʻldirish bilan odamlarni izmimda ushlab turaman, deb xayol qilardi. Ammo insonning qalbiga haqiqiy iymon kirganida, uning bu choralari zarracha ham taʼsir qilmay qolishini anglamasdi. Uning sobiq sehrgarlari qalbiga ana shunday iymon jo boʻlgan edi. Endi ular Firʼavnning hech qanday doʻq-poʻpisalaridan qoʻrqmasdilar.)","Ular: «Biz seni zinhor oʻzimizga kelgan ochiq-oydin (moʻjiza)lardan va bizni yaratgan zotdan ustun qoʻymaymiz. Bas, nima hukm qilsang, qilaver. Sen faqat hayoti dunyoda hukm chiqarasan, xolos.","Albatta, biz Robbimiz xatolarimizni va sen bizni majbur qilgan sehrni magʻfirat qilishi uchun iymon keltirdik. Alloh yaxshi va boqiydir», dedilar.","Shubhasiz, kim Robbiga jinoyatchi boʻlgan holida kelsa, albatta, unga jahannam bordir. U yerda u oʻlib oʻlmas, yashab yashamas.","Kim Unga moʻmin oʻlaroq, yaxshi amallar qilgan holida kelsa, bas, ana oʻshalarga oliy darajalar.","Ostidan anhorlar oqib turgan adn jannatlar bordir. Unda abadiy qolurlar. Ana shu pok boʻlganning mukofotidir.","Batahqiq, Biz Musoga: «Sen bandalarim ila kechasi yoʻlga tush, ularga dengizdan quruq yoʻl och, yetib olishlaridan xavf qilma va qoʻrqma», deb vahiy qildik. (Muso alayhissalom Alloh taoloning amrini amalga oshirdi. Bani Isroil bilan kechasi yoʻlga chiqdilar. Dengizga bordilar, asolari bilan urib, yoʻl ochdilar. Allohning amri ila dengiz ikkiga yorilib, quruq yer–yoʻl ochildi. Bani Isroil eson-omon oʻtib oldi.)","Bas, Firʼavn askarlari ila ularning ortidan taʼqib etdi. Dengiz ularni oʻraganicha oʻrab oldi.","Firʼavn oʻz qavmini adashtirdi, toʻgʻri yoʻlga boshlamadi. ( Xudoga emas, firʼavnlarga ergashganlar doimo shunday oqibat topadilar. Alloh taolo Firʼavn va askarlarini gʻarq etib, Bani Isroilni zulm, jabr-sitamdan ozod qildi.)","Ey Bani Isroil, batahqiq, Biz sizni dushmaningizdan qutqardik va siz bilan Turning oʻng tomonini vaʼdalashdik hamda sizlarga mann va bedana tushirdik. (Alloh taolo ushbu oyati karimada Bani Isroilga uch turlik neʼmatini eslatmoqda.)","Biz sizga rizq qilib bergan pok narsalardan yenglar, unda haddingizdan oshmang, yana boshingizga gʻazabim tushib qolmasin. Kimning boshiga gʻazabim tushsa, bas, batahqiq, halok boʻlibdir.","Albatta, Men tavba qilgan, iymon keltirib, yaxshi amal qilgan, soʻngra toʻgʻri yurganlarni koʻplab magʻfirat qilguvchiman.","Ey Muso, seni qavmingdan nima ilgarilatdi?","U: «Ular, ana, izimdalar. Rozi boʻlishing uchun Men senga shoshdim, ey Robbim», dedi.","U zot: «Batahqiq, Biz qavmingni sendan keyin fitnaga duchor qildik. Somiriy ularni adashtirdi», dedi. (Bani Isroilga hurlik ogʻir keldi, uni koʻtara olmadi. Jumladan, eng nozik va ahamiyatli masala–iymon-eʼtiqod masalasida ham. Muso alayhissalom ilk bor tark etishlari bilanoq zalolatga ketdilar. Somiriyga ergashib, buzoqning haykalini xudo qilib oldilar.)","Bas, Muso qavmiga gʻazablangan, afsuslangan holda qaytdi. U: «Ey qavmim, Robbingiz sizga yaxshi vaʼda qilmaganmidi?! Sizlarga zamon uzoq koʻrindimi yoki boshingizga Robbingizdan gʻazab tushishini xohladingizmi?! Menga bergan vaʼdaga xilof qilibsiz?!» dedi.","Ular: «Biz senga bergan vaʼdaga oʻz ixtiyorimiz ila xilof qilmadik. Lekin bizga (u) qavmning ziynatidan ogʻirliklar yuklangan edi. Bas, ularni tashladik, Somiriy ana shunday ilqo qildi», dedilar. (Taqinchoqlarni olovli chuqurga tashlashgan ekan, Somiriy ularni eritib, buzoq shakliga solib, mana shu sizlarning xudoingiz, unga ibodat qilinglar, desa, ibodat qilib ketaverishibdi. Ularning fikricha, bu ixtiyorlaridan tashqari ish emish!)","Bas, u (Somiriy) ularga boʻkiradigan buzoq shaklini chiqarib berdi. Ular: «Mana shu sizning ilohingiz va Musoning ham ilohi, faqat u unutdi», dedilar. (Somiriy ularga tilla taqinchoqlardan ovoz chiqaradigan buzoq haykali yasab, shu haykal sizning ilohingiz, Paygʻambarimiz Muso bizga buni aytmadi, degan xayolga bormang. Musoning ilohi ham shu buzoq. Ammo, Muso buni unutib qoʻyib, toqqa izlab chiqib ketdi, dedi. Ular bu gapni takrorladilar.)","Uning oʻzlariga biron soʻz qaytara olmayotganini, na zarar va na foydaga molik boʻla olmayotganini koʻrmayaptilarmi?!","Batahqiq, ilgari Horun ularga: «Ey qavmim, bu bilan fitnaga duchor qilindingiz, xolos. Shubhasiz, Robbingiz Rohmandir. Bas, menga ergashing. Mening amrimga itoat qiling», degan edi.","Ular: «To Muso bizga qaytgunicha, unga ibodat qilishda bardavom boʻlamiz», dedilar.","U: «Ey Horun, ularning zalolatga ketganlarini koʻrganingda seni nima man qildi?!","Menga ergashishingdan?! Mening amrimga osiy boʻldingmi?!» dedi.","U: «Ey onamning oʻgʻli, soch-soqolimdan tutma. Men sening: «Bani Isroilni tafriqaga solibsan, gapimga kirmabsan, deyishingdan qoʻrqdim», dedi.","U: «Bu nima qilganing, ey Somiriy?!» dedi.","U: «Ular koʻrmagan narsani koʻrdim. Bas, Rasulning izidan bir siqim oldim, soʻngra uni tashladim. Havoi nafsim menga shunday qilishni xush koʻrsatdi», dedi. (Somiriyning Bani Isroil koʻrmaganini koʻrgani–Jabroilning alayhissalom hayot otiga minib kelishlari. «Rasul»dan murod Jabroil alayhissalom. Izidan olingan bir siqim esa, Jabroil alayhissalom minib kelgan otning tuyogʻi tagidan olingan tuproq. U tuproqni sochgan joyi esa, Bani Isroilning zeb-ziynatlari toʻplab qoʻyilgan joy. Somiriy ana shu ishlarni qilganida ziynatlar buzoqqa aylanib, undan ovoz chiqadigan boʻlibdi. Men hech narsa qilganim yoʻq, yomon niyatim ham yoʻq edi, koʻnglimga tushgan ishni qilsam, oʻzlaridan oʻzlari ergashib ketishaverdi, demoqchi boʻldi.)","U: «Bas, joʻna! Ket! Endi senga bu hayotda «tegish yoʻq» deyishing bor, xolos. Albatta, senga xilof qilmaydigan vaʼdamiz bor. Oʻzing ibodatida bardavom boʻlgan ilohingga nazar solib qoʻy. Biz uni, albatta, kuydirurmiz, soʻngra dengizga sochib yuborurmiz. ( Bani Isroilda, «tegish yoʻq» nomli quvgʻin jazosi bor edi. Oʻsha jazoga mahkum boʻlgan shaxs bilan hech kim aloqa qilmas, hatto gaplashmas ham edi. U yolgʻizlik azobida oʻlib ketar edi.)","Albatta, sizning ilohingiz Allohdir, xolos. Undan oʻzga ibodatga sazovor zot yoʻqdir. U barcha narsani oʻz ilmi bilan qamrab olgandir.","Shunday qilib, senga oʻtgan narsalar xabarini qissa qilib berurmiz. Batahqiq, senga oʻz tarafimizdan zikrni berdik. (Yaʼni, Muso qissasini aytib berganimizdek, boshqalarning xabarini ham qissa qilib beramiz.)","Kim undan yuz oʻgirsa, albatta, u qiyomat kuni (gunoh) yukini koʻtarur.","Unda abadiy qolurlar. Qiyomat kunida ularning yuki qanday ham yomon boʻldi.","U kun surga puflanadigan kundir. Oʻsha kunda jinoyatchilarni koʻzlari koʻk boʻlgan holda toʻplarmiz. (Kiyomatning kelganini bildirib, sur chalinadi. Oʻsha qiyomat kunida kofirlar-jinoyatchilarni Alloh taolo qoʻrquvdan yuzlari qorayib, koʻzlari koʻkarib ketgan ketgan hollarida mahsharga jamlaydi.)","Ular oʻzaro: «Oʻn kundan ortiq turganingiz yoʻq», deya shivirlashadi.","Biz nima deyayotganlarini yaxshi bilguvchimiz. Oʻshanda ularning eng toʻgʻri yoʻldagisi: «Bir kundan ortiq turganimiz yoʻq», deydir. (Demak, oxirat azoblarini koʻrgan kofirlar garchi bu dunyoda uzoq yillar rohat-farogʻatda kun kechirgan boʻlsalar ham, yashagan muddatlari oz koʻrinib ketadi.)","Sendan togʻlar haqida soʻrarlar. Bas: «Robbim ularni mutlaqo sovurib yuborajak.","Soʻng ularni tep-tekis holga keltirur.","U yerda chuqur ham, doʻng ham koʻrmassan.","U kunda chorlovchiga ergashurlar. Undan burilish yoʻq. Ovozlar Rohman (haybati)dan jim qolmish. Pichirlashdan boshqa narsa eshitmassan. (Hammayoq tep-tekis. Hamma jim holda boʻyin egib, mahsharga chorlovchiga ergashishdan boshqa narsani bilmaydi.)","U kunda Rohman unga izn bergan va soʻzidan rozi boʻlganlardan boshqaning shafoati foyda bermas.","U ularni oldilaridagi narsalarni ham, orqalaridagi narsalarni ham bilur. Ular esa, uni ilm ila ihota qila olmaslar. (Alloh taolo bandalarning kelajagini ham oʻtmishini ham biladi. Ilmning barchasi Allohnikidir. Odamlar esa hech narsa bilmaslar.)","Butun yuzlar tirik va doim turuvchi zotga bosh egmish. Batahqiq, kim zulm koʻtargan boʻlsa, noumid boʻlmish.","Kim moʻmin holida yaxshi amallardan qilgan boʻlsa, zulmdan ham, nuqsondan ham qoʻrqmas», deb ayt.","Shunday qilib, Biz uni arabiy Qurʼon etib nozil etdik. Shoyadki taqvo qilsalar yoki ularda eslash paydo qilsa, deb unda qoʻrqinchli vaʼdalarni bayon qildik. (Ushbu arabiy Qurʼonda koʻplab qoʻrqinchli vaʼdalarni ham bayon etdik. Bundan maqsadimiz, shoyad odamlar taqvo qilsalar, kufr va yomonliklardan saqlansalar, qoʻrqinchlik vaʼdalardan eslatma olsalar.)","Haq Podshoh–Alloh oliy boʻldi. Senga vahiyi bitguncha Qurʼon (tilovati)ga oshiqma va: «Robbim, ilmimni ziyoda qilgin», degin. (Paygʻambarimiz (s. a. v.) unutib qoʻyishdan xavflanib, vahiy tushgan paytida Qurʼoni Karim oyatlarini Jabroilga alayhissalom qoʻshilib, oʻqib turar edilar. Bu esa, qiyinchilik tugʻdirardi. Yaʼni, ey Muhammad, Jabroil vahiyni senga oxirigacha oʻqib bermagunicha, Qurʼonni tilovat qilib, oyatlarni oʻqishga shoshilma. Oldin Jabroil toʻliq oʻqib bersin, keyin sen oʻqiysan.)","Batahqiq, ilgari Biz Odam bilan ahdlashgan edik. Lekin u unutdi. Unda azmu qaror topmadik. (Biz qadimda Odam bilan buyruqqa boʻysunish–daraxtdan yemaslik haqida ahdlashgan edik. Ammo Odam ahdni unutdi va daraxtdan yeb qoʻydi. U shaytonning igʻvosiga sabr qila olmadi. Azmu qarorida turmadi.)","Biz farishtalarga: «Odamga sajda qiling», deganimizda, ular sajda qildilar. Magar Iblis bosh tortdi.","Bas, Biz: «Ey Odam, albatta, bu senga va juftingga dushmandir. Yana u ikkovingizni jannatdan chiqarib, badbaxt boʻlib qolmagin.","Albatta, sen u yerda och-yalangʻoch qolmassan. (Yaʼni, jannatda doimo sening qorning toʻq, usting but boʻladi.)","Albatta, sen u yerda tashna ham boʻlmassan, issiqda ham qolmassan», dedik.","Bas, shayton uni vasvasa qildi. U: «Ey Odam, men senga abadiyat daraxtini va bitmas-tuganmas mulkni koʻrsataymi?» dedi. ( Robbing manavi daraxt mevasidan yeyishingni man qilgan boʻlsa, sening abadiy yashashingni, mulking bardavom boʻlishini xohlamaganidandir, bu daraxtning mevasidan yesang, hech oʻlmaysan, mulking yoʻqolmaydi, dedi.)","Bas, ikkovlari undan yedilar. Keyin, avratlari oʻzlariga ochilib qolib, oʻzlarini jannat barglari bilan toʻsa boshladilar. Odam Robbiga osiy boʻldi va yoʻldan ozdi.","Soʻngra Robbi uni tanlab oldi, bas, tavbasini qabul qildi va hidoyatga boshladi.","U zot: «Hammangiz bir-biringizga dushman holda undan tushing. Agar Men tomonimdan sizga hidoyat kelganida, kim hidoyatimga ergashsa, adashmas va badbaxt boʻlmas.","Kim Mening zikrimdan yuz oʻgirsa, albatta, unga torchilik hayoti boʻlur va qiyomat kuni uni koʻr holida tiriltirurmiz», dedi.","U: «Ey Robbim, nima uchun meni koʻr holda tiriltirding. Axir, koʻruvchi edim-ku!» dedi.","U zot: «Shunday. Senga oyatlarimiz keldi. Sen esa, ularni unutding? Shuningdek, sen ham bugun unutiursan», dedi.","Isrof qilgan va Robbi oyatlariga iymon keltirmaganlarni ana shunday jazolayrmiz. Oxirat azobi, albatta, ashaddiyroq va boqiyroqdir.","Ulardan ilgari ularning maskanlarida yurgan asrlardan qanchadan-qanchasini halok qilganimiz ham hidoyat qilmadimi? Albatta, bunda aql egalari uchun ibratlar bordir.","Agar Robbingdan soʻz oʻtib qolmaganida va nomlangan ajal boʻlmaganida, albatta, (azob) lozim boʻlar edi.","Bas, ular aytayotgan narsalarga sabr qil. Robbingga quyosh chiqishidan oldin va botishidan oldin tasbih va hamd ayt. Shuningdek, kechaning bir qismida va kunduzning atrofida ham tasbih ayt. Shoyadki rozi boʻlsang. (Ey Muhammad, shunday ekan, kofir va mushriklarning noxush gap-soʻzlariga, soʻkishlariga, igʻvo-boʻhtonlariga sabr qil. Doimo Robbingga tasbihu hamd ayt. Quyosh chiqishidan oldin ham, quyosh botishidan oldin ham Robbingga tasbih va hamd ayt. Kechaning bir qismida ham Robbingga tasbih ayt, kunduzning atrofida ham. Namoz oʻqi. Albatta, rozi boʻlasan. Robbing ham sendan rozi boʻladi.)","Koʻzlaringni ularni sinash uchun ayrimlariga bahramand qilib berganimiz hayoti dunyoning turli ziynatlariga tikma. Robbingning rizqi yaxshi va boqiydir.","Ahlingni namozga amr et va oʻzing unga sabr qil. Biz sendan rizq soʻramasmiz. Biz senga rizq berurmiz. Oqibat taqvonikidir.","Ular: «Bizga Robbidan oyat-moʻjiza keltirsa edi», deydilar. Axir, ularga avvalgi sahifalardagi narsalarning bayonoti kelmadimi? (Kofir va mushriklar, Muhammad Robbidan bir lol qoldiruvchi moʻjiza keltirsa edi, deydilar. Axir, Qurʼonda avvalgi ummatlarga kelgan narsalarning bayoni keldi-ku. Shu ularga kifoya qilmaydimi?)","Agar Biz ularni u(kelishi)dan oldin azob-la halok qilganimizda edi, albatta: «Ey Robbimiz, bizga Paygʻambar yuborganingda edi, xoru zor va sharmanda boʻlishimizdan oldin oyatlaringga ergashgan boʻlar edik», derdilar.","Sen: «Barcha kutguvchidir. Bas, kutinglar. Albatta, kimlar toʻgʻri yoʻl sohiblari va kimlar hidoyat topganini bilursizlar», deb ayt. (Paygʻambarimizga (s. a. v.) qilingan bu xitob doimo yangilanib turadi.)"],"21":["Odamlarga hisoblari yaqinlashib qoldi. Ular esa, gʻaflatda, yuz oʻgiruvchi boʻlgan hollarida.","Qachon Robbilaridan yangi eslatma kelsa, faqat uni oʻynayotgan hollarida tinglarlar.","Qalblari gʻofil boʻlib. Zulm qilganlar oʻzaro: «Bu oʻzimizga oʻxshagan bashardan oʻzga emas-ku. Oʻzingiz koʻrib turib sehrga kelasizmi?» deb pichirlasharlar.","U: «Robbim osmonu yerdagi soʻzni bilur. U eshitguvchi va bilguvchi zotdir», dedi.","Ular: «Balki algʻov-dalgʻov tushlardir, balki oʻzi uydirib olgandir, balki u shoirdir. Bas, bizga avvalgilar yuborilganidek, moʻjiza keltirsin», dedilar.","Ulardan oldin biror shahar (aholisi) iymon keltirmadi. Biz ularni halok qildik. Endi ular iymon keltirarmidilar?! (Ulardan oldin lol qoldiruvchi moʻjiza keltirishni talab qilganlardan birortasi ham iymonga kelmadi. shuning uchun hammasini halok qildik. Endi ular iymonga kelarmidilar?!","Biz sendan ilgari ham faqat er kishilarni Paygʻambar qilib yuborib, ularga vahiy qilganmiz, xolos. Agar bilmasangiz zikr ahllaridan soʻrang. (Bashar Paygʻambar boʻlmaydi, deb daʼvo qilayotgan, ey kofir-mushriklar, agar Paygʻambarlar bashar ekanini bilmasangiz zikr-ilm egalaridan, ahli kitoblardan soʻrang.)","Biz ularni taom yemaydigan jasad qilganimiz yoʻq. Ular abadiy qolguvchi ham boʻlgan emaslar.","Soʻngra ularga (bergan) vaʼdamiz ustidan chiqdik. Bas, ularga hamda oʻzimiz xohlaganlarga najot berdik va isrofchilarni halok qildik. (Keyin Paygʻambarlarga bergan vaʼdamiz ustidan chiqdik, ularga ergashgan moʻminlarga najot va fathu nusrat berdik. Isrofchilarni, kofir boʻlganlarni halok etdik. Odat shu. Hozirgi kofirlar ibrat olsinlar.)","Batahqiq, Biz sizga kitob nozil qildik. Unda sizning zikringiz bor. Aql ishlatmaysizlarmi?!. (Zikringiz-sharafingiz bor. Odamlar aqlnini ishlatishlari lozim. Yana Qurʼonga qaytib, unga amal qilmoqlari shart.)","Biz zolim boʻlgan shahar-qishloqlardan qanchasini (belini) sindirdik va ulardan keyin boshqa qavmlarni paydo etdik.","Bizning azobimizni his qilganlarida esa, birdan u yerdan qochishga boshlarlar.","Qochmanglar! Maishatparsatlik qilgan narsalaringizga, maskanlaringizga qaytinglar. Hali ehtimol soʻralursizlar.","Ular: «Holimizga voy! Biz, albatta, zolim boʻlgan ekanmiz», dedilar.","Ularning oʻsha dod-voylari, Biz ularni oʻrilgan oʻtday, sovugan kulday qilgunimizcha bardavom boʻldi.","Biz osmonlaru yerni va ularning orasidagi narsalarni oʻyin uchun yaratganimiz yoʻq. (Bunday ulkan va ajoyib narsalar, albatta, oʻyin uchun yaratilmaydi. Behudaga shunchalik urinishning keragi yoʻq. Maqsad oʻyin boʻlsa, shunga mosroq narsa yaratilar edi.)","Agar Biz koʻngilxushi tutishni iroda qilsak, uni qiluvchi boʻlganimizda ham, Oʻz tomonimizdan tutar edik.","Yoʻq, Biz haqni botil ustiga oturmiz. Bas, uni yakson qilur. Koʻribsanki, u(botil) zavolga uchrabdi. Sizlarga esa, qilgan vasflaringizdan halokat kelur.","Osmonlaru yerdagi barcha jonzotlar Unikidir. Uning huzuridagilar ibodatidan takabburlik qilmaslar va malol olmaslar.","Ular kechayu kunduz tasbih aytarlar. Charchamaslar.","Yoki ular yerdan xudolar tutdilaru oʻshalar tiriltirurlarmi?","Agar u(osmonlaru yer)larda Allohdan oʻzga «xudo»lar boʻlganida, buzulib ketar edilar. Arshning Robbi Alloh ular vasf qilgan narsadan pokdir. (Borliqni bir zot yaratgan, bir zot idora qilib, boshqarib turadi. Borliq shunga boʻysunadi. Shu bois ham hadsiz-hisobsiz boʻlishiga qaramay, borliqda qoyil qolarlik darajada nizom va mutanosiblik hukm suradi. Agar borliqni yaratgan, uni idora qilib turgan zot bittadan koʻp boʻlsa, oʻsha zotlarning irodasi bir-biri bilan, albatta, toʻqnashar edi. Oqibatda borliqda nomutanosiblik kelib chiqar, jipslik yoʻqolar va nizom buzilar edi. Modomiki borliq bir nizomda turibdimi, mutanosibmi, demak, uni yaratgan va tadbirini qilib turgan zot bitta.)","U qilgan narsasidan soʻralmas. Holbuki, ular soʻralurlar.","Yoki undan oʻzga «xudo»lar tutdilarmi? Sen: «Hujjatlaringizni keltiring. Mana bu men bilan birgalarning zikridir va mendan oldingilarning zikridir», degin. Yoʻq, ularning koʻplari haqni bilmaslar. Bas, ular yuz oʻgirguvchidirlar. (Borliqqa nazar solib, undagi mavjudotlarni mulohaza qilib koʻrganda, Alloh taoloning sherigi boʻlishi mumkin emasligi isbotlandi. Yana nima uchun mushriklar Alloh taologa ibodat qilmayaptilar?)","Sendan ilgari yuborgan har bir Paygʻambarga: «Albatta, Mendan oʻzga ibodatga sazovor iloh yoʻq. Bas, Menga ibodat qiling», deb vahiy qilganmiz.","Ular: «Rohman farzand tutdi», dedilar. U pokdir. Yoʻq! Ikrom etilgan bandalardirlar. (Yaʼni, mushriklar, Alloh farishtalarni qiz qilib oldi, dedilar. Alloh bu nuqsondan pokdir. Farishtalar Allohning qizi emas, muhtaram bandalaridair.)","Ular undan oldin soʻz aytmaslar. Ular Uning amri ila amal qilurlar.","U zot ularning oldilaridagi narsani ham, ortlaridagi narsani ham biladir. Ular faqat u zot rozi boʻlgan shaxslargagina shafoat qilurlar. Ular u zotning qoʻrqinchidan titragan holda tururlar.","Ulardan kim: «Men undan oʻzga ilohman», desa, bas, oʻshani jahannam ila jazolarmiz. Zolimlarni shunday jazolarmiz.","Kufr keltirganlar osmonlaru yer bitishgan boʻlgan ekanini, bas, Biz ularni ochganimizni va suvdan har bir tirik narsani qilganimizni bilmaydilarmi? Iymon keltirmaydilarmi? (Oyati karima maʼnosi xususida tafsirchilar bir necha xil maʼnolar aytganlar. Birinchisi, Ibn Umar va Ibn Abboslardan (r. a.) rivoyat qilingan boʻlib, osmon yopiq edi, Biz uni ochdik va yomgʻir-qor yogʻdirdik, oqibatda oʻsha suv ila hamma tirik narsalar paydo boʻldi, degan maʼno chiqadi. Ikkinchisi, unga koʻra osmonlaru yer yoʻq edi, ularni Biz yaratdik, soʻngra suvdan tirik narsalarni paydo qildik, maʼnosi boʻladi. Uchinchisi, Hasan, Qatodalardan (r. a.) rivoyat qilingan boʻlib, osmonlaru yer bir-biriga bitishgan bir narsa edi, ularning orasini Biz ochdik, soʻngra suvdan tirik narsalarni paydo qildik, maʼnosi bor. Toʻrtinchisi hozirgi zamon baʼzi tafsirchilarning fikrlari boʻlib: osmonu yer, yulduzlaru quyosh hamma-hammasi bir butun edi, Allohning irodasi ila koʻp aylanish va ichki portlashlar oqibatida parchalanib, alohida-alohida boʻlib ketdi: quyosh alohida, yer alohida, oy alohida, yulduzlar alohida va boshqa narsalar ham; suvdan esa, barcha tirik narsalar, inson, hayvon va nabototlar paydo qilindi. Bular, oyati karimaning maʼnosini tushunishga urinishdir. Oyatning haqiqiy maʼnosini Allohning Oʻzi biladi.)","Biz yerda ularni tebranmasliklari uchun togʻlar qildik va shoyadki toʻgʻri yoʻl topsalar, deb unda daralar, yoʻllar qildik.","Va osmonni saqlagan shift qilib qoʻydik. Ular esa, Uning alomatlaridan yuz oʻgirguvchi boʻlmoqdalar.","U kechayu kunduzni, quyoshu oyni yaratgan zotdir. Hammasi falakda suzmoqdalar.","Sendan oldin ham biror basharga abadiylikni qilganimiz yoʻq. Agar sen oʻlsang, ular abadiy qolar ekanlarmi?","Har bir jon oʻlimni tatib koʻrguvchidir. Biz sizlarni yomonlik va yaxshilik ila imtihon uchun sinaymiz hamda bizgagina qaytarilursiz.","Kufr keltirganlar seni koʻrganlarida, masxara qilib: «Xudolaringizni zikr qilayotgan shumi?!» deyishdan boshqani bilmaslar. Holbuki, ular Rohmanning zikriga oʻzlari kofirdirlar.","Inson shoshqaloq oʻlaroq yaratilgandir. Men, albatta, sizlarga Oʻz oyat-alomatlarimni koʻrsaturman. Bas, meni shoshiltirmanglar.","Ular: «Agar sodiq boʻlsangiz, bu vaʼda qachon boʻladir», derlar.","Kufr keltirganlar yuzlaridan va sirtlaridan olovni toʻsa olmaydigan va oʻzlariga yordam berilmaydigan vaqtni bilsalar edi.","Yoʻq! U ularga toʻsatdan kelib, hayratu dahshatga solur. Bas, uni rad qilishga qodir boʻlmaslar va ularga muhlat ham berilmas.","Batahqiq, sendan oldin ham Paygʻambarlar masxara qilingan. Bas, ularni masxara qilganlarga oʻzlari masxara etib yurgan narsa tushdi.","Sen: «Kechasi va kunduzi sizni Rohmandan kim qoʻriydi?» degin. Yoʻq! Ular Robbilari zikridan yuz oʻgirguvchilardir!","Yoki ularning Bizdan oʻzga himoya qiladigan «xudo»lari bormi? Ular oʻzlariga ham yordam berishga qodir boʻla olmaslar va Bizdan doʻstlik topmaslar. (Doʻstlik topganlarida himoyamizga oʻtishlari mumkin edi. Lekin zinhor bizdan doʻstlik topmaslar. Chunki ular bunga munosib emaslar. Kofirlar esa, buni oʻylab ham koʻrmaydilar. Qachon va qayerda soxta xudolari ularga homiy boʻlibdi, biror yordam qilibdi, yaxshilik yetkazibdi?)","Balki Biz ularni va ota-bobolarini bahramand qildik, hatto ularga umr uzun koʻrindi. Ular yerga kelib, uni atrofidan qisqartirayotganimizni koʻrmaydilarmi?! Gʻolib kelguvchi ularmi? (Tafsirchi ulamolarimiz oyati karimadagi ushbu jumla maʼnosi haqida bir necha xil fikr bildirganlar. Qadimgi tafsirchilarimiz, yerning atrofidan qisqartirilishi–kufr yerlari qisqarib Islom yerlari kengayib borishi, deganlar. Mujohid va Ikrimalar (r. a.), yerning atrofidan qisqarishi–xarob boʻlishi, deyishgan. Al-Afviy Ibn Abbosdan (r. a.) qilgan rivoyatda esa, barakasining qisqarishi, deyilgan. Ash-Shaʼbiy, agar yer qisqaradigan boʻlsa, unga sigʻmay qolar eding, lekin jonlar va meva-cheva, hosillar qisqaradi, degan. Ikrima (r. a.) ham, agar yer qisqarganida, oʻtirgani joy topa olmay qolar eding, qisqarish oʻlimdir, deb aytgan. Keyingi davr tafsirchilari esa, rohat-farogʻatda yashagan, yerning turli atroflarida gʻolib boʻlib, oʻzining soʻzini oʻtkazib turgan davlatlar va xalqlar bahramandlikdan hovliqib ketib, hadlaridan oshganlarida, nuqsonga duchor qilinishlari–qisqartirilishlaridir, deydilar. Ushbu maʼnolar bir-birini toʻldirib keladi. Har bir tafsirchi olim oʻz zamonasidagi voqelikdan, oʻz tushunchasidan kelib chiqib maʼno aytgan boʻladi.)","Sen: «Men sizlarni faqat vahiy orqaligina ogohlantirurman. Gunglar ogohlantirilganlarida daʼvatni eshitmaslar», degin.","Qasamki, agar ularga Robbing azobidan salgina yetsa, albatta: «Holimizga voy! Haqiqatda biz zolimlar boʻlgan ekanmiz», derlar.","Biz qiyomat kuni uchun adolat tarozularini qoʻyurmiz. Biror jonga hech qanday zulm qilinmas. Agar (amal) achitqi donasi ogʻirligicha boʻlsa ham, keltirurmiz. Hisobchilikda Oʻzimiz kifoya qilurmiz.","Batahqiq, Biz Muso va Horunga Furqonni taqvodorlar uchun ziyo va eslatma qilib berdik. (Alloh taolo oyati karimada shunday kitobni Muso va Horunlarga alayhissalom berganini eslatmoqda. Shu bilan birga, Tavrot ham Furqon sifatiga, ham «taqvodorlar uchun ziyo va eslatma» sifatiga ega ekani bayon qilinmoqda. Ha, ilohiy kitob ziyosidan bahramand boʻlish va undagi eslatmalardan ibrat olish uchun taqvodor boʻlish kerak. Betavfiq va taqvosizlar uning ziyosidan ham, eslatmasidan ham bahramand boʻla olmaydilar.)","Ular Robbilaridan gʻoyibona qoʻrqurlar va ular (qiyomat) soatidan titrarlar.","Bu, Biz nozil qilgan muborak eslatmadir. Sizlar uni inkor qilguvchi boʻlasizlarmi?!","Batahqiq, ilgari Biz Ibrohimga rushdi hidoyatni bergan edik. Biz uning (holini) bilguvchi edik. (Ibrohim Alloh tomonidan rushdi hidoyat berilgan zotlar ichida avvalgilaridan biri edi. Biz unga rushdni bexosdan berganimiz yoʻq. Biz Ibrohimning rushdi hidoyatga, Paygʻambar boʻlishga loyiq zotligini yaxshi bilar edik.)","Oʻshanda u otasiga va qavmiga: «Manavi siz ibodatiga berilayotgan haykallar nima?» degan edi.","Ular: «Ota-bobolarimizni ularga ibodat qilgan hollarida topganmiz», dedilar.","U: «Batahqiq, siz ham, ota-bobolaringiz ham ochiq-oydin zalolatdasizlar», dedi.","Ular: «Sen bizga haq ila keldingmi yoki oʻyin qilguvchilardanmisan?» dedilar.","U: «Yoʻq! Robbingiz osmonlaru yerning Robbidir. U zot ularni yaratgandir. Men bunga guvohlik berguvchilardanman.","Allohga qasamki, sizlar ortga oʻgirilib ketganingizdan keyin sanamlaringizga bir balo qilaman», dedi. (Yaʼni, Ibrohim alayhissalom oʻzlari bilan tortishayotgan qavmlariga, ularning sanamlariga bir yomonlik yetkazishlari aniqligini qasam ila taʼkidlab aytdilar. Ammo nima qilishlarini ochiq-oydin aytmadilar. Arab tilida «sanam» deb bosh qismi inson shakliga oʻxshatib ishlangan butlarga aytiladi.)","Bas, ularni parcha-parcha qilib tashladi. Magar eng kattasini, shoyadki unga qaytsalar, deb qoldirdi. (Mushrik qavm yillik bayramlarida shahardan tashqariga chiqar edi. Ular navbatdagi yillik bayramni nishonlash uchun ketganlarida Ibrohim alayhissalom hamma butlarni parcha-parcha qilib tashladilar va eng katta butga tegmasdan qoldirib qoʻydilar.)","Ular: «Bizning xudolarimizga kim bunday qildi?! Albatta, u zolimlardandir!» dedilar.","Ular: «Ularni eslab yurgan bir yigitni eshitgan edik, uni Ibrohim, deb aytilardi», dedilar.","Ular: «Uni odamlar koʻzi oldiga olib kelinglar. Shoyadki guvoh boʻlsinlar», dedilar.","Ular: «Xudolarimizga buni sen qildingmi, ey Ibrohim?!» dedilar.","U: «Yoʻq, buni manavi, ularning kattasi qildi. Agar gapiradigan boʻlsalar, ulardan soʻrab koʻringlar», dedi.","Bas, ular oʻzlariga keldilar va: «Albatta, sizlar oʻzingiz zolimdirsiz», dedilar. (Ibrohimning alayhissalom mantiqli savollaridan keyin mushriklar oʻzlariga keldilar.)","Soʻngra yana boshlari aylanib: «Sen, batahqiq, bularning gapirmasligini bilar eding!» dedilar.","U: «Allohni qoʻyib, siz hech manfaat ham, zarar ham bermaydigan narsaga ibodat qilasizmi?!","Sizga ham, Allohni qoʻyib, ibodat qilayotgan narsalaringizga ham suf-e! Axir, aql yuritib koʻrmaysizlarmi?!» dedi.","Ular: «Uni kuydiringlar! Agar (bir ish) qiladigan boʻlsangiz, xudolaringizga yordam bering!» dedilar. (Yaʼni, Ibrohimni kuydirib yuborishingiz xudolaringizga yordam boʻladi, dedilar. Xullas, mushriklar katta gulxan yoqib, Ibrohimni alayhissalom oʻsha gulxanga otdilar.)","Biz: «Ey olov, sen Ibrohimga salqin va salomatlik boʻl!» dedik.","Ular u(Ibrohim)ga yomonlik iroda qilgan edilar. Biz ularni eng ziyonkorlar qilib qoʻydik.","Unga va Lutga najot berib, olamlar uchun barakali qilgan yerga yubordik. (Alloh taolo Ibrohim alayhissalomga va u kishining jiyanlari Lut alayhissalomga najot berdi. Qavmlariga yetgan balodan ularni sogʻ-salomat olib qolib, «olamlar uchun barakali qilgan yer»ga–Shomga yubordi. Darhaqiqat, Shom yeri eng barakali yerlardan hisoblanadi. Barcha Paygʻambarlar oʻsha joydan chiqqan. U yer muqaddas joy. U yurtda Baytul Maqdis joylashgan.)","Unga Isʼhoqni hadya etdik va Yaʼqubni ziyoda qilib berdik va hammalarini ahli solihlar qildik.","Va ularni Oʻz amrimiz ila hidoyatga boshlovchilar qildik. Ularga yaxshiliklar qilishni, namozni tugal ado etishni va zakot berishni vahiy qildik. Ular Bizga ibodat qilguvchilar boʻldilar.","Va Lutga hukm va ilm berdik va unga iflosliklar qilayotgan qishloqdan najot berdik. Albatta, ular yomon, buzgʻunchi qavm edilar.","Va Biz uni Oʻz rahmatimizga kiritdik. Albatta, u solihlardandir.","Va Nuhni (esla). Bundan oldin u nido etganida, Biz uning nidosiga javob qildik va unga hamda uning ahliga ulugʻ gʻamdan najot berdik.","Unga oyatlarimizni yolgʻonga chiqargan qavmga qarshi nusrat berdik. Albatta, ular yomon qavm edilar. Bas, Biz ularning barchasini gʻarq qildik. (Nuh alayhissalomning qissalari boshqa suralarda batafsil kelgan. Bu surada siyoqqa qarab ikki oyatda qisqacha bayon qilinmoqda.)","Va Dovud bilan Sulaymonning ekinzor haqida hukm qilayotganlarini (esla). Oʻshanda u(ekinzor)ga qavmning qoʻyi kechasi tarqalib ketgan edi. Biz ularning hukmiga shohid boʻlgan edik. (Oʻz davrining Paygʻambari va podshohi boʻlmish Dovud alayhissalomning huzurlariga ikki kishi oralarida hukm chiqarishni soʻrab kelishibdi. Ulardan biri ekinzor sohibi, ikkinchisi qoʻylar egasi ekan. «Oʻshanda u (ekinzor)ga qavmning qoʻyi kechasi tarqalib ketgan edi». Kechasi bilan ekinzorni payhon qilib, yeb bitirgan edi. Dovud alayhissalom ikki tomonning gapini eshitib boʻlib, qoʻylarni ekinzor egasiga berilishiga hukm chiqardilar. Payhon boʻlib yoʻqolgan ekinzor oʻrniga uni payhon qilgan qoʻylarni olib berish ayni adolat edi. Bu hukmdan keyin qaytib ketayotgan qoʻy egasi Sulaymonni alayhissalom koʻrib qolib, boʻlgan hodisani u kishiga aytib berdi. Shunda Sulaymon alayhissalom otalari Dovud alayhissalom oldilariga kirdilar va «Ey Allohning Nabiyi, hukm siz chiqargan hukmdek boʻlmasligi kerak edi», dedilar. Dovud alayhissalom: «Qanday boʻlishi kerak edi», dedilar. Sulaymon alayhissalom: «Qoʻyni ekinzor egasiga bering, u foydalanib tursin. Ekinzorni esa, qoʻy egasiga bering, uni tuzatib asl holiga keltirsin. Soʻngra har kim oʻz narsasini qaytarib oladi. Ekinzor egasi ekinzorini eski holiga kelgandan soʻngra qaytarib oladi. Qoʻy egasi ham qoʻylarini qaytarib oladi», dedilar. Shunda Dovud alayhissalom: «Hukm sen chiqargan hukmdir», dedilar.)","Bas, Biz uni Sulaymonga fahmlatdik. Ularning har biriga hukmni va ilmni bergan edik. Dovud bilan birga tasbih aytsin deb togʻlarni va qushlarni boʻyinsundirib qoʻydik. Shularni qilguvchi boʻlgan Bizmiz.","Biz unga sizlar uchun sizni yomonlikdan saqlaydigan kiyim qilish sanʼatini oʻrgatdik. Endi shukr qilarsizlar?!","Sulaymonga shamolni qattiq esuvchi qilib berdik. U(shamol)ni uning amri ila, Biz barakali qilgan yerga esadigan qilib qoʻydik. Barcha narsani bilguvchi boʻldik.","Va shaytonlardan unga gʻavvoslik qiladiganlarni va bundan boshqa amallarni qiladiganlarni qildik. Biz ularni muhofaza qilguvchi boʻldik.","Va Ayyubning oʻz Robbiga nido qilib: «Albatta, meni zarar tutdi. Sening Oʻzing rahmlilarning rahmligisan!» deganini esla. (Ayyub alayhissalomga juda katta zarar yetgani maʼlum. Lekin oʻsha zararning aynan nomini Qurʼoni Karim aniq aytmaydi. Ushbu oyatda ham Ayyubning alayhissalom Allohga yolborib nido qilayotganlari kelyapti, xolos.)","Bas, Biz uning (duosini) istijobat qildik. Unga yetgan zararni ketkazdik. Unga ahlini, ular bilan birga yana shunchani ham berdik. Buni Oʻz rahmatimiz ila va, obidlarga eslatma boʻlsin, deb qildik.","Va Ismoil, Idris va Zul-kiflni esla. Ularning har biri sabr qilguvchilardandir.","Va ularni Oʻz rahmatimizga kiritdik. Albatta, ular solihlardandir.","Zunnunni esla. Oʻshanda u gʻazablangan holda chiqib ketgan edi. Bas, u Bizni oʻziga (yer yuzini) tor etmaydi, deb gumon qildi. Zulmatlarda turib, Sendan oʻzga Iloh yoʻq, Sen poksan, albatta, men zolimlardan boʻldim, deb nido qildi. (Zunnundan murod Yunus alayhissalomdir. «Nun» baliq degani, Zunnun esa, baliq egasi degani. Yunusni alayhissalom dengizda baliq yutib yuborgan, keyin qirgʻoqqa kelib, Allohning amri bilan chiqarib tashlangan. Shuning uchun Zunnun–baliq egasi, laqabini olganlar. U zotning qissalari As-Saffot surasida keladi. Ammo bu surada siyoqqa mos ravishda qisqacha bayon qilinmoqda. Yunus alayhissalom qavmlarining qilmishlaridan gʻazablanib, yurtlarini tashlab chiqib ketdilar. Ulamolarimiz aytishlaricha, aslida u kishi boshqa Paygʻambarlarga oʻxshab sabr qilishlari, Allohning amrini kutishlari kerak edi. Ammo bunday qilmadilar. Qavmlariga zarda qilib, yurtlaridan chiqib ketdilar. Soʻngra Alloh taolo, u kishini baliqqa yuttirib, sinovga uchratdi. Ana oʻshanda, «zulmatlarda turib», yaʼni kecha zulmati, dengiz osti zulmati va baliq qorni zulmatida turib, Alloh taologa yolborib: «Sendan oʻzga Iloh yoʻq, Sen poksan, men zolimlardan boʻldim, deb nido qildi».)","Bas, Biz uning (duosini) ijobat qildik. Unga gʻamdan najot berdik. Moʻminlarga shunday najot berurmiz.","Va Zakariyoni esla. Oʻshanda u Robbiga nido qilib: «Ey Robbim, meni yolgʻiz tashlab qoʻyma, Sen, Oʻzing vorislarning eng yaxshisisan», degan edi.","Bas, Biz uning (duosini) ijobat etdik va unga Yahʼyoni hadya qildik hamda juftini oʻnglab qoʻydik. Albatta, ular yaxshiliklarga shoshilishar edi va Bizga ragʻbat ila va qoʻrqib duo qilishar edi. Ular Bizga taʼzim ila boʻyinsunuvchi edilar.","Farjini pok saqlagan ayolni esla. Biz unga Oʻz ruhimizdan pufladik. Uni va uning oʻgʻlini olamlarga oyat-belgi qildik. («Farjini pok saqlagan» ayol deganda, Bibi Maryam nazarda tutilgan.)","Albatta, sizning ushbu ummatingiz bir ummatdir va Men sizning Robbingizman. Bas, Mengagina ibodat qiling.","Ular esa ishlarini parchaladilar. Barchalari Bizga qaytuvchidirlar. (Aslida, hamma bir ummat boʻlib, bir dinga ishonib, yagona Allohga ibodat qilishi kerak edi. Ammo odamlar bu yoʻldan yurmay, oʻzlaricha yoʻllarini, dinlari va ishlarini boʻlak-boʻlak qilib oldilar. Ularning hammasi baribir oxir-oqibat bizga qaytadilar. Oʻshanda biz oʻzimiz bilib hisob-kitob qilamiz.)","Kim moʻmin holida solih amallardan qilsa, saʼyi-harakati zoye ketmas. Albatta, Biz uni yozib qoʻyguvchidirmiz.","Biz halok qilgan qishloq-shaharlarning qaytmasligi haromdir. (Bu dunyodagi gunohlari uchun yoʻqotib yuborilgan shahar-qishloqlarning aholisi qiyomat kuni jazolarini olish uchun qaytariladilar. Ularning qaytmasliklari mumkin emas.)","Nihoyat, Yaʼjuj va Maʼjuj ochilib, ular har bir tepaliklardan oqib kelganlarida.","Va haq vaʼda yaqinlashgandagi holni koʻrsang, kufr keltirganlarning koʻzlari chaqchayib: «Holimizga voy! Bizlar bundan gʻaflatda edik. Yoʻq! Bizlar zulm qilguvchilar edik», derlar. (Kahf surasida aytib oʻtilganidek, qiyomatning alomatlaridan biri–Zulqarnayn qurgan sadd-toʻgʻon ochilib, Yaʼjuj va Maʼjujlar chiqib ketishidir, ular juda koʻp boʻlib, koʻpliklaridan yurganlarida xuddi sel oqqandek oqib kelar ekanlar. Qiyomat qoyim boʻlgandagi holni koʻrsang, unda «... kufr keltirganlarning koʻzlari chaqchayib», yaʼni qotib qoladi. Shunday, gʻaflatda emas. Balki bilib turib tayyorgarlik koʻrmagan edik. Ishonmay, zulm qilgan edik, deydilar.)","Albatta, sizlar va Allohdan oʻzga ibodat qilgan narsalaringiz jahannam yoqilgʻisidirsiz. Sizlar unga kirguvchilardirsiz.","Agar anavilar xudolar boʻlganida unga kirmas edilar. Hammalari unda abadiy qolurlar. (Sizlar Allohdan oʻzga sigʻingan narsalar haqiqatda xudolar boʻlganida, jahannamga kirmas edilar. Ammo ular hech qachon xudo boʻlgan emas, ularni sizlar xudo deb olgansiz, shuning uchun jahannamga tushmoqdalar.)","U yerda ularga ingrash bordir. Ular u yerda eshitmaslar.","Albatta, Bizdan ularga yaxshilik ravo koʻrilganlar, ana oʻshalar, undan uzoqlashtirilgandirlar. (Yaʼni, Allohning moʻmin bandalari, Alloh ularga yaxshilikni ravo koʻrgan bandalar jahannamdan uzoqda boʻladilar. Uning yaqiniga ham kelmaydilar.)","Ular uning chisirlashini eshitmaslar. Ular oʻz nafslari ishtaha qilgan narsalari ichida abadiy qolguvchilardir.","Ularni buyuk dahshat gʻami bosmas. Ularni farishtalar: «Bu sizlarga vaʼda qilingan kuningizdir», deb kutib olarlar.","Oʻsha kunda osmonni xuddi maktub yozilgan daftarni yopgandek yopamiz. Avval qanday yaratgan boʻlsak, shunday holga qaytaramiz. Bu zimmamizdagi vaʼdadir. Albatta, Biz buni qilguvchimiz. (Xuddi hisob-kitob yozib boruvchi shaxs ishini tugatib daftarini yopganidek, qiyomat kunida osmon shunday yopiladi. Demak, dunyodagi ishlar hammasi bitgan, oxiriga yetgan boʻladi. Endi ishga, amalga, savob topish yoki tavba qilishga fursat qolmaydi.)","Batahqiq, Biz zikrdan soʻng Zaburda ham: «Albatta, yerga solih bandalarim merosxoʻr boʻlurlar», deb yozgan edik. (Tafsirchilarimiz ushbu oyati karimadagi «zikr» va «yer» soʻzlaridan koʻzlangan maqsad haqida ikki xil fikr bildirganlar. Baʼzilari, «zikr»dan murod–Tavrotdir, shunga koʻra, oyatning maʼnosi: «Batahqiq, Biz Tavrotdan soʻng Zaburda ham: «Albatta, yerga solih bandalarim merosxoʻr boʻlurlar», deb yozgan edik» boʻladi, deydilar. Boshqalari esa, «zikr»dan murod–Lavhul Mahfuz, binobarin, avval oʻsha maʼnoni Lavhul Mahfuzga yozib, keyin Zaburga ham yozgan edik, maʼnosi chiqadi, deganlar. «Yer» haqida esa, baʼzi ulamolarimiz oddiy yer koʻzda tutilgan desalar, boshqalari jannat yeri nazarda tutilgan, deydilar. Ushbu ikki xil maʼnoni qoʻshib, har ikkisi koʻzda tutilgan, desa ham boʻladi.)","Albatta, bu(Qurʼon)da ibodat qilguvchi qavm uchun yetarli oʻgit bordir.","Biz seni faqat olamlarga rahmat qilib yubordik.","Sen: «Menga faqat, albatta, sizning ilohingiz bitta ilohdir, deb vahiy etiladi. Bas, sizlar musulmon boʻlasizlarmi?!» deb ayt.","Agar ular yuz oʻgirib ketsalar: «Men sizlarga barobarlik boʻlishi uchun eʼlon qildim. Sizga vaʼda qilinayotgan narsa yaqinmi yoki uzoqmi bilmasman. (Yaʼni, iymon masalasida hamma barobar boʻlishi uchun, menga tushgan vahiyni eʼlon qildim. Keyin bexabar edik, degan daʼvo boʻlmasligi uchun eshittirdim.)","Albatta, U soʻzning oshkorasini biladir va nimani berkitayotgan boʻlsangiz ham biladir.","Bilmayman, ehtimol, bu sizlar uchun sinovdir yoki vaqtinchalik halovatdir», deb ayt. (Azobning kelmay turishi ehtimol sinovdir, ehtimol bu dunyoning huzur-halovatidan foydalanib olishingiz uchun muhlatdir.)","U: «Ey Robbim, Oʻzing haq ila hukm qil. Robbimiz Rohmandir va sizlar qilgan vasflardan madad soʻraladigan zotdir», dedi. (Yaʼni, Paygʻambar alayhissalomey Robbim, men omonatingni ado etdim. Kishilarga taʼlimotlaringni yetkazdim. Endi oʻzing haq ila hukm qilaver, dedilar.)"],"22":["Ey odamlar! Robbingizdan qoʻrqing! Albatta, (qiyomat) soati zilzilasi ulkan narsadir.","Uni koʻradigan kuningizda, har bir emizuvchi oʻzi emizayotgan narsasini unutar. Har bir homilador homilasini tashlar. Odamlarni mast holda koʻrarsan. Holbuki, ular mast emas. Lekin Allohning azobi shiddatlidir.","Odamlardan Alloh haqida bilmasdan tortishganlari va bebosh shaytonga ergashganlari ham bor. (Alloh taolo haqida, «bilmasdan» tortishish johillikdir. Bunday tortishuvga jurʼat qilgan shaytonga ergashgan boʻladi.)","Unga bitilganki, albatta, unga kim doʻst boʻlsa, shubhasiz, uni adashtiradi va doʻzax azobiga «hidoyat» qiladi.","Ey odamlar! Agar qayta tirilish haqida shubha qiladigan boʻlsangiz, bas, Biz sizga bayon qilishimiz uchun sizlarni tuproqdan, soʻngra nutfadan, soʻngra alaqadan, soʻngra bitgan-bitmagan bir chaynam goʻshtdan yaratdik. Va bachadonlarda xohlagan narsamizni maʼlum muddatgacha qaror topdiramiz. Keyin sizlarni buvak holingizda chiqaramiz. Soʻngra voyaga yetishingiz uchun (tarbiya qilamiz). Sizdan vafot qilib ketadiganlar ham, bilganidan keyin hech narsani bilmay qoladigan darajada tuban umrga yetadiganlar ham bor. Va yerni qaqragan holda koʻrasan. Qachonki, Biz unga suv tushirsak, u seskanar va koʻpchir. Hamda har xil goʻzal juftlarni oʻstiradir. (Sizning otangiz Odamni tuproqdan yaratganmiz. Inson yoʻq edi. U otasining nutfa-spermasidan dunyoga keldi. Oddiy koʻzga koʻrinmas ushbu maniy hayvonchalar bilan barkamol inson orasida qancha farq bor?! Ana shu zarradan odam yaratgan Xoliq Alloh oʻlgan odamni qayta tiriltira olmasmi?! Qurʼoni Karimda «alaqa» deb nomlangan bosqichdagi homila zulukdek bachadonga yopishib turishi maʼlum boʻldi. Alaqaning suvrati haqiqiy zuluk bilan solishtirilsa, ularni farqlab boʻlmaydi. Xoʻsh, oʻsha zulukka oʻxshash qotgan laxta qon bilan inson orasida qancha farq bor? Homila rivojlanib, alaqa-laxta qon shaklidan bir parcha chaynalgan goʻsht holiga oʻtadi. Ana oʻshanda unga shakl kiradi. Shakl kirsa, bitgan boʻladi. Shakl kirmasa, bitmagan boʻladi, bachadondan tushib ketadi. Hech kim uni eslamaydi ham. Endi, oʻsha bir parcha chaynalgan goʻshtga oʻxshash narsa bilan inson orasida qancha farq borligini bir oʻylab koʻraylik? Oʻsha goʻshtdan inson yaratgan Alloh oʻlgan odamni qayta tiriltira olmasmi?!)","Bular koʻrsaturki, albatta, Alloh haq zotdir va, albatta, U oʻliklarni tiriltirur hamda U har bir narsaga qodirdir.","Va, albatta, (qiyomat) soati kelguvchidir, bunga shubha yoʻq. Va, albatta, Alloh qabrlardagi kimsalarni tiriltirur.","Odamlardan Alloh haqida bilmasdan, hidoyatga yoki nurli kitobga ega boʻlmasdan turib tortishadiganlari bor.","Allohning yoʻlidan adashtirish uchun, boʻynini bulqab (tortishadi). Unga dunyoda rasvolik bor. Qiyomat kuni unga kuydirish azobini totdiramiz.","Bunday boʻlishi oʻz qoʻllaring taqdim qilgan narsalardandir. Albatta, Alloh bandalarga zulm qilguvchi emasdir.","Odamlardan Allohga bir tomonlama ibodat qiladiganlari ham bor. Agar unga yaxshilik yetsa, koʻngli toʻlur. Agar unga balo yetsa, yuz oʻgirib ketur. U dunyoda ham, oxiratda ham ziyon koʻrur. Ana oʻsha ochiq-oydin ziyondir. (Islom tijorat emaski, unga oʻtkinchi foydani koʻzlab kirilsa. Islom–iymon, eʼtiqod, Allohga bandalik qilish, Uning yoʻlida jonni ham, molni ham fido etish, har xil balo-ofatlarga bardosh berish demakdir. Ana oʻsha sinovlardan oʻtganlar ikki dunyo baxtiga sazovor boʻladilar. Ammo Islomga muayyan foydani koʻzlab kirgan, oʻsha foydaga erishsa, xursand boʻlib, erishmasa, dinni tark etib, yuz oʻgirib ketadigan munofiqlar ikki dunyoda ziyon koʻrishlari muqarrar. Aslini olganda munofiq, Islomdan, Allohdan yuz oʻgirib, qayoqqa ham borardi, kimga ham topinardi?)","U Allohni qoʻyib, oʻziga zarar ham bermaydigan, manfaat ham bermaydigan narsaga iltijo qilur. Shuning oʻzi qattiq adashishdir.","U manfaatidan koʻra zarari yaqinroq boʻlganga iltijo qiladir. U qanday ham yomon xoja va qanday ham yomon doʻstdir!","Albatta, iymon keltirib, yaxshi amallarni qilganlarni Alloh ostilaridan anhorlar oqib turgan jannatlarga kiritadir. Albatta, Alloh iroda etgan narsani qiladir.","Kimki unga bu dunyoyu oxiratda Alloh nusrat berishiga shubha qilsa, bir vosita topib, osmonga osilsin, soʻngra uni kessin. Bas, nazar solsin-chi, uning bu hiylasi gʻam-gʻussani ketkizarmikan?! (Allohga iymoni yoʻq kishining holi shunday boʻladi. Uning balo-ofatdan, gʻam-gʻussadan qutulishga chorasi yoʻq. Allohga iymoni boʻlmagani uchun undan nusrat kelishiga ham umid qilmaydi. Shuning uchun yo osmonga chiqib, yordam topsin, yo, unday qila olmasa, oʻzini ossin. Boshqa iloji yoʻq.)","Mana shunday qilib, Biz u(Qurʼon)ni ochiq-oydin oyatlar holida nozil qildik. Albatta, Alloh xohlagan kishilarni hidoyat qiladir.","Albatta, Alloh qiyomat kuni iymon keltirganlar, yahudiy boʻlganlar, sobiiylar, nasorolar, majusiylar va shirk keltirganlar orasida Oʻzi ajrim qilur. Albatta, Alloh har bir narsaga shohiddir.","Osmonlardagi kimsalar, yerdagi kimsalar, quyosh, oy, yulduzlar, togʻlar, daraxtlar, jonivorlar va odamlardan koʻplari, albatta, Allohga sajda qilishini koʻrmaysanmi? Koʻplariga esa, azob haq boʻldi. Kimni Alloh xor qilsa, uni ikrom qilguvchi boʻlmas. Albatta, Alloh xohlagan narsasini qiladi. (Demak, dunyodagi barcha mavjudot Alloh taologa sajda qiladi. Ularning qanday sajda qilishini Allohning Oʻzi biladi. «Osmonlardagi kimsalar, yerdagi kimsalar Allohga sajda qiladi», deb qoʻyilsa, kifoya edi, butun borliqning sajda qilishi tushunaverilar edi. Lekin baʼzi maxluqlar alohida qayd etildi, chunki baʼzi odamlar oʻsha maxluqlarga–quyosh, oy va yulduzlarga sajda qiladilar. Oyatda oʻsha narsalarning Allohga sajda qilishini taʼkidlashdan maqsad ular xudo boʻla olmasligini yana bir bor taʼkidlashdir. Butun borliq hech bir istisnosiz Allohga sajda qilayotgani aytilgan boʻlsa ham, odamlarga kelganda, «koʻplari» sajda qilmasliklariga ishora etilmoqda. Ha, faqat odam bolasigina Allohga isyon qiladi. Allohga sajda qilmagani uchun, kofir boʻlgani uchun ularga azob haq boʻldi. Allohning azobiga duchor boʻlganlar ikki dunyoda xordir.)","Mana bu ikki gʻanim Robbilari haqida talashgan edilar. Bas, kufr keltirganlarga olovdan kiyim bichildi. Boshlari ustidan oʻta qaynoq suv quyiladir.","U bilan qorinlaridagi narsalar va terilari eritiladi.","Ular uchun temir gurzilar bor.","Ular har qachon undagi gʻamdan chiqmoqchi boʻlsalar, unga qaytariladilar va «Yonish azobini toting!» deyiladir.","Albatta, Alloh iymon keltirib, yaxshi amallarni qilganlarni ostidan anhorlar oqib turgan jannatlarga kiritur. Ular u yerda oltin bilakuzuklar va injular ila bezanurlar. U yerdagi liboslari esa, ipakdandir. (Bir-biriga qarama-qarshi ikki narsani bir joyda, bir xil saviyada vasf qilishlik Qurʼoni Karimga xos xususiyatlardan biridir. Jahannamda olovning azobiga qoʻshimcha qilib, oʻta qaynoq suv quyilsa, jannatda soya-salqin bogʻlar ostidan muzdek zilol, huzurbaxsh suvlar oqib turibdi. Jahannamda azob ustiga azob kelsa, jannatda huzur ustiga huzur. Doʻzaxilarga olovdan kiyim kiydirilsa, jannatilarga ipakdan koʻylak kiydiriladi. Doʻzaxilar boshiga temir gurzi bilan urilsa, jannatilarga oltin va injulardan bezak taqilgan.)","Ular shirin soʻzga hidoyat qilinurlar va maqtalgan Zotning yoʻliga hidoyat qilinurlar. (Jahannam ahliga «Yonish azobini toting!» deb gurzi bilan urilsa, jannat ahliga shirin soʻzlar aytilib, Alloh taoloning yoʻliga hidoyat qilib qoʻyiladi.)","Kufr keltirganlar va Allohning yoʻlidan hamda yerli va chetdan kelgan odamlar uchun barobar qilib qoʻyganimiz Masjidul Haromdan toʻsganlarga va u yerda kim zulm ila yanglish yoʻlga burilishni iroda qilsa, unga alamli azobni tottiramiz.","Biz Ibrohimga Baytning joyini belgilab berib: «Menga hech narsani sherik qilma, Baytimni tavof qilguvchilar, (ibodatda) qoim turguvchilar hamda rukuʼ, sujud qilguvchilar uchun poklagin.","Odamlarni hajga chaqir, ular sen tomon piyoda, uzoq-uzoq yoʻllardan yurib, ozigan ulovlar ustida kelsinlar.","Va oʻzlariga boʻladigan manfaatlarga shohid boʻlsinlar. Maʼlum kunlarda ularga rizq qilib bergan chorva hayvonlarini (soʻyishda) Allohning ismini zikr qilsinlar. Bas, ulardan yenglar va bechora va faqirlarga ham yegizinglar.","Soʻngra oʻzlaridagi kirlarni ketkazsinlar, nazrlariga vafo qilsinlar va «qadimgi uy»ni tavof qilsinlar», deganimizni esla. (Baytullohning egasi Alloh taolo tomonidan, uning quruvchisi Ibrohim alayhissalomga aytilayotgan bu sifatlar Quraysh kofirlarida emas, musulmonlarda mavjud. Demak, Baytullohga, Masjidul Haromga Quraysh kofirlari emas, musulmonlar haqlidirlar. Ey Ibrohim, odamlarni haj ibodatiga chaqir. Eng uzoq yurtlardan ham kelsinlar. Piyoda yurib boʻlsa ham, kelsinlar. Yoʻl uzoqligidan, mashaqqatliligidan ulovlari ozib-horib ketsa ham, kelsinlar. Hajga keluvchilar, avvalo, Allohga ibodat qiladi, taqvosi ziyoda boʻladi, oʻzaro fikr va tajriba almashadilar, foydali maslahatlar oladilar, shuningdek, savdo-sotiq, tijorat ham qiladilar. Haj mavsumning avji, iyd kunlari boʻlib, unda zikr qurbonlik soʻyish jarayonida yana avjlanadi. Qurbonlik qiluvchi hoji qurbonligidan oʻzi yesa ham boʻladi, beva-bechora, faqir-fuqarolarga yegizsa ham boʻladi Qurbonlik qilib boʻlganidan keyin, hojiga ehromdan chiqishga ruxsat boʻladi, ehrom vaqtida mumkin boʻlmagan soch oldirish yoki qisqartirishga, qoʻltiq ostidagi va boshqa joylardagi tuklarni, tirnoqlarni olishga izn beriladi. Hoji bu ishlarni bajarib, yuvinib-taranadi. Oyatda«... oʻzlaridagi kirlarni ketkazsinlar...» deyishdan maqsad shu. «Qadimgi uy»dan murod Kaʼbatulloh. Bu tavofni farz tavof, ifoza tavofi, deyiladi. Bu tavofsiz haj haj boʻlmaydi. Shuni ado etishlik bilan haj ibodati ham tugaydi.)","Ana shunday. Kim Alloh harom qilgan narsalarga rioya qilsa, bas, bu Robbi huzurida uning oʻzi uchun yaxshidir. Va sizlarga (kelajakda) tilovat qilinadiganlardan boshqa chorva hayvonlari halol qilindi. Bas, butlardan iborat najosatdan yiroq boʻling va yolgʻon soʻzdan yiroq boʻling.","Allohga boʻlgan iymondan ogʻmang, Unga shirk keltirguvchi boʻlmang. Kim Allohga shirk keltirsa, bas, u goʻyoki osmondan qulab tushganu uni yirtqich qush olib qochgan yoki uni shamol uzoq yerga uchirib ketgan kabidir. (Inson iymonga erishganda, yuqori martabalarga erishgan boʻladi, kimki oʻsha yuksak martabani xohlamay, Allohga shirk keltirsa, xuddi osmondan qulab tushgan kabi boʻladi.)","Ish bundoq. Kim Allohning nishonlarini ulugʻlasa, bas, albatta, bu qalblarning taqvosidandir. (Ushbu oyat maʼnosida «nishonlar» deb tarjima qilgan ibora Qurʼoni Karimda «shaoir» deb aytilgan. Bu «shaʼiyra» soʻzining jami–koʻpligi, nishon, belgi, alomat maʼnolarini bildiradi. Bu soʻz Alloh taologa nisbat berilib, «shaoirulloh–Allohning nishonlari», deyilganda esa, Allohning dini, Islomning koʻzga koʻringan, shon-shavkati alomati boʻlgan ibodatlar koʻzda tutiladi. Ushbu oyati karimada esa, qurbonlikka soʻyiladigan katta hayvonlar koʻzda tutilmoqda.)","Sizga u(nishon)larda maʼlum vaqtgacha manfaatlar bordir. Soʻngra ularni (soʻyish) halol makoni «qadimgi uy» (atrofi)dadir.","Har bir ummatga ularga chorva hayvonlarini rizq qilib berganiga Allohning ismini eslashlari uchun qurbonlik qilishni joriy etganmiz. Bas, ilohlaringiz bir ilohdir. Bas, Ungagina musulmon boʻling. Itoatli, mutavozeʼlarga bashorat ber.","Ular Alloh zikr qilingan vaqtda qalblari titraydigan va oʻzlariga yetgan musibatga sabr qilguvchilar hamda namozni toʻkis ado etguvchilardir, ularga rizq qilib bergan narsamizdan infoq qilarlar.","Va tuyalarni siz uchun Allohning nishonlaridan qildik. Ularda sizga yaxshilik bor. Ularga old oyoqlaridan biri bogʻliq turgan holida Allohning nomini zikr qiling. Yonlari yerga tekkanida esa, bas, ulardan yeng va qanoatli va tilangan kambagʻallarni ham taomlantiring. Shunday qilib, Biz ularni sizga boʻyinsundirib qoʻydik. Shoyadki shukr qilsangiz.","Ularning goʻshtlari ham, qonlari ham zinhor Allohga yetmaydir. Lekin Unga sizdan taqvo yetadir. Shunday qilib, sizni hidoyat qilgani evaziga Allohga takbir aytishingiz uchun ularni sizga boʻyinsundirib qoʻydi. Yaxshilik qilguvchilarga bashorat ber. (Qurbonlik qilishdan maqsad bandaning Alloh amriga itoatini, taqvosini namoyon etishdir. Banda Allohni qancha ulugʻlasa, shuncha oz. Birgina hidoyatga boshlab qoʻygani uchun qancha takbir aytsa, oz. Qurbonlik qilish ham, Allohning yoʻlida har qanday qurbonlik berishga tayyor ekanini koʻrsatish ham oʻsha hidoyat uchun Alloh taoloni ulugʻlashdir.)","Albatta, Alloh iymon keltirganlarni mudofaa qiladir. Albatta, Alloh barcha xoin va kofirlarni xush koʻrmas.","Oʻzlariga qarshi urush ochganlarga ularga zulm qilingani uchun (urushga) izn berildi. Albatta, Alloh ularga nusrat berishga qodirdir. (Demak, kofirlar avval musulmonlarga qarshi urush ochgan. Musulmonlar hujumga va zulmga uchraganlar. Endi ular oʻzlarini himoya qilmasalar, boʻlmaydi. Kofirlar ularni yoʻq qilib yuborishlari mumkin. Musulmonlar urushga kirsalar, Alloh ularga yordam berishga qodirdir.)","Ular nohaqdan, faqatgina «Robbimiz Alloh» deganlari uchun oʻz diyorlaridan chiqarilgandirlar. Agar Alloh odamlarning baʼzilarini baʼzilari bilan daf qilib turmasa, uzlatgohlar, kanisalar, havralar va Allohning nomi koʻplab zikr qilinadigan masjidlar vayron qilingan boʻlur edi. Albatta, Alloh Oʻziga yordam berganlarga yordam berur. Albatta, Alloh kuchli va gʻolibdir.","Ularga yer yuzida imkon bersak, namozni toʻkis ado etarlar, zakotni berarlar, yaxshilikka buyurib, yomonlikdan qaytararlar. Ishlarning oqibati Allohga oiddir. (Oyati karimadagi «Ularga yer yuzida imkon bersak» jumlasidan «makon bersak» maʼnosi ham tushuniladi. Bunga qoʻshimcha «yer yuzida nusrat, gʻalaba bersak» maʼnolari ham chiqadi. Diyorlaridan «Robbimiz Alloh» deganlari uchun chiqarilgan musulmonlarga yer yuzida makon, nusrat, gʻalaba–imkon bersak: Xovliqib ketmaydilar, balki Alloh taologa ixlos bilan ibodat qiladilar, u bilan bogʻlanishni kuchaytiradilar. Alloh xohlagan oqibatini keltirib chiqaradi. Xohlasa, magʻlubiyatni ham gʻalabaga aylantirib yuboradi.)","Agar seni yolgʻonchi qilayotgan boʻlsalar, bas, bulardan oldin Nuh qavmi, Od va Samud ham yolgʻonchi qilgan edilar.","Ibrohim qavmi, Lut qavmi.","Madyan egalari ham. Va Muso ham yolgʻonchi qilindi. Men kofirlarga bir oz muhlat berdim, soʻngra ularni tutdim. Bas, Mening inkorim qandoq boʻldi?! (Albatta, oʻta shiddatli boʻldi. Oʻta qoʻrqinchli boʻldi. Oʻsha kofir, jinoyatchi, Paygʻambarlarini yolgʻonchiga chiqargan qavmlarning baʼzilarini toʻfon azobi tutdi. Baʼzilarini yer yutdi, zilzila va boshqa azoblarga duchor boʻldilar.)","Qanchadan-qancha shahar-qishloqlarni zulm qilguvchi boʻlgan holida halok etdik. Bas, ular (hozirda) shiftlari qulagan, tashlandiq quduq, (huvillagan) yuksak qasr (holidadir).","Axir, yer yuzida aylanib yurmaydimilarki, ularga aql etadigan qalblar, eshitadigan quloqlar boʻlsin. Zero, koʻzlar koʻr boʻlmas, koʻksilardagi qalblar koʻr boʻlur. (Oʻsha kofirlar yer yuzida aylanib yurganlarida, oʻtgan kofirlardan qolgan asarlarni koʻrar edilar. Ularni koʻrib, tafakkur qilganlarida qalblari taʼsirlanib, aqllari kirar edi. Odamlardan oʻtgan zolim kofir qavmlar nima uchun va qanday qilib halokatga uchraganlari haqidagi rivoyatlarni eshitar, ulardan ibrat olar edilar.)","Ular sendan azobning tezroq kelishini soʻrarlar. Holbuki, Alloh vaʼdasiga xilof qilmas. Darhaqiqat, Robbing huzuridagi bir kun, siz sanaydigan ming yildekdir. (Modomiki kofirlarga azob yuborishni vaʼda qildimi, ularga Allohning azobi, albatta, keladi. Shoshilmay tursinlar. Azobni qachon yuborishni Allohning Oʻzi biladi. Alloh taolo hech shoshilmaydi. «Darhaqiqat, Robbing huzuridagi bir kun siz sanaydigan ming yildekdir». Shuning uchun ham U zot shoshilmaydi.)","Qanchadan-qancha shahar-qishloqlarga zulm qilguvchi boʻlgan holida ham muhlat berdim. Soʻngra ularni (azobga) tutdim. Qaytish faqat mengaginadir.","Sen: «Ey odamlar! Men sizlar uchun faqat bir ochiq ogohlantirguvchiman, xolos», deb ayt.","Iymon keltirib, yaxshi amallarni qilganlarga magʻfirat va ikromli rizq bordir.","Bizning oyatlarimizni ojiz qoldirmoqchi boʻlib, saʼyi-harakat qilganlar, ana oʻshalar jahiym egalaridir.","Biz sendan ilgari hech bir Rasul va Nabiy yubormadikki, u bir narsani tamanniy qilganida, shayton uning tamanniysiga (shubha) tashlamagan boʻlsa. Bas, Alloh shayton tashlaydigan narsani ketkazur. Soʻngra Alloh Oʻz oyatlarini mustahkam qilur. Alloh oʻta bilguvchi va hikmatli zotdir. (Lugʻat jihatidan qaraydigan boʻlsak «Tamanniy» soʻzi arab tilida «oliy orzu» (ajNabiy tildagi «ideal») maʼnosini anglatadi. Shuning uchun ham oyati karima maʼnosini tarjima qilishda bu soʻzni shu holda qoldirishni ravo koʻrdik. Ushbu oyati karimada, bu oliy orzu boshqa Rasul va Nabiylarda ham boʻlganligi, bu koʻproq shayton tomonidan notoʻgʻri fikr yoki holatlarga olib borishi mumkinligi, ammo Alloh doimo Oʻzi Paygʻambarlarni bundan saqlab kelganligi aytilmoqda. Ushbu holat Paygʻambarimiz (s. a. v) hayotlarida bir necha marta koʻrilgan.)","Shayton tashlaydigan narsaning qalblarida kasali borlarga va qalblari toshlarga fitna boʻlishi uchundir. Albatta, zolimlar (haqdan) uzoq tortishuvdadirlar.","Ilm berilganlar u(Qurʼon) Robbingdan kelgan haq ekanini bilishlari, unga iymon keltirishlari va qalblari unga bogʻlanib, taskin topishi uchundir. Albatta, Alloh iymon keltirganlarni toʻgʻri yoʻlga hidoyat qilguvchidir.","Kufr keltirganlar, ularga (qiyomat) soati toʻsatdan kelgunicha yoki qisir Kun azobi kelgunicha u(Qurʼon)dan shubhada boʻlishda davom eturlar. (Kofirlar qiyomatgacha Qurʼoni Karim Allohdan kelgan haq ekaniga shubhada boʻladilar. Shuning uchun iymon keltirmaydilar. Lekin bu bilan faqat oʻzlariga ziyon qiladilar, xolos.)","Oʻsha kunda hukmronlik (yolgʻiz) Allohgagina xosdir. U ular orasida hukm qilur. Bas, iymon keltirganlar va yaxshi amal qilganlar nozu neʼmat jannatlaridadirlar.","Kufr keltirgan va oyatlarimizni yolgʻonga chiqarganlar esa, bas, ana oʻshalarga xorlovchi azob bordir.","Alloh yoʻlida hijrat qilganlar, soʻngra oʻldirilib yoki vafot etganlarni, albatta, Alloh goʻzal rizq ila rizqlantirur. Albatta, Alloh rizq berguvchilarning eng yaxshisidir. (Hijrat Alloh yoʻlida vatandan, qarindosh-urugʻdan, molu dunyodan, turli qulayliklardan uzoqda boʻlishdir. Hijrat barcha Paygʻambarlar, ulugʻ zotlar boshidan oʻtkazgan holatdir. Islomda esa, Islom Paygʻambari Muhammad (s. a. v.) va u kishining safdoshlari–sahobalarning bir qismi hayotidagi katta sinovdir. Alloh taolo ularning Makkadan Madinaga qilgan hijratlaridan soʻng Islomga fathu futuh, shonu shavkat berdi.)","Albatta, U zot ularni oʻzlari rozi boʻladigan joyga kiritur. Albatta, Alloh oʻta bilguvchi va halim zotdir.","Ish bundoq. Kim oʻziga iqob qilinganiga oʻxshash iqob qilsayu, soʻngra unga yana zoʻravonlik qilinsa, Alloh, albatta, unga nusrat berur. Albatta, Alloh avfli va magʻfiratli zotdir. (Birov zulmga uchrab, boshqa bir kishi tomonidan iqobga uchrasa, qasos olish tariqasida oʻsha zolimdan oʻziga qilingan iqob darajasida oʻch olsayu, soʻngra unga yana tajovuz qilinsa, oʻsha odamga Alloh yordam beradi. Chunki u zulm qilmayapti, haddidan oshmayapti, faqat oʻz haqqini talab qilyapti. Boshqa tomon esa, avval nohaqdan tajovuzkorlik qilgan edi. Tajovuziga yarasha javob kelganida, tushunib oʻzini tiyishi kerak edi. Ammo u yana tajovuzkorlik qildi.)","Chunki Alloh, albatta, kechani kunduzga kiritur va kunduzni kechaga kiritur. Albatta, Alloh oʻta eshitguvchi va oʻta koʻrguvchi zotdir. (Doimiy suvratda kecha kunduzga, kunduz kechaga kirib turadi. Buni Allohga kufr keltirib, gerdayib yurgan odamlar ham, boshqalari ham qila olmaydi. Buni faqat Alloh taologina qiladi. Allohning bu ishini birov toʻxtata olmaganidek, u zotning mazlumlarga nusrat berishini ham toʻxtata olmaydi.)","Chunki Allohning Oʻzigina haqdir, Undan boshqa topinayotganlari esa, botildir. Albatta, Alloh yuksak va buyukdir.","Alloh osmondan suv tushirganida, yerning yam-yashil boʻlishini koʻrmadingmi?! Albatta, Alloh oʻta lutfli va xabardor zotdir.","Osmonlaru yerdagi narsalar Unikidir. Albatta, Alloh, Uning Oʻzigina behojat va maqtalgan zotdir. (Alloh taolo osmonlaru yerdagi narsalarga ega boʻlganidan, U zotning hech bir narsaga hojati yoʻq. Shunday ham maqtalgan, hamdu sano egasi boʻlgan zotdir. Oʻzidan boshqa yordamchiga Uning hojati boʻlmaganidek, birovning maqtoviga ham hojati yoʻqdir.)","Alloh yerdagi narsalarni, dengizda Oʻz izni ila yuradigan kemani sizlarga boʻysundirib qoʻyganini hamda osmonni iznisiz yerga tushishdan tutib turishini koʻrmadingizmi?! Albatta, Alloh odamlarga shafqatli va mehribondir. (Insof bilan fikr ishlatib qaralsa, Alloh taolo yer yuzidagi hamma narsalarni inson foydasi uchun, unga boʻysunadigan, unga beminnat xizmat qiladigan qilib qoʻygan. Havodan tortib, toshu toqqacha, nabototu jamodot, katta-kichik jonzotlar, hamma-hammasi inson uchun xizmatkor. Ularning evaziga insondan haq talab qilinmaydi.)","Sizlarni tiriltirgan, keyin oʻldiradigan, soʻngra (qayta) tiriltiradigan ham Uning Oʻzidir. Albatta, inson oʻta noshukrdir. (Insonga hayot berib, uni yoʻqdan bor qilgan kim?! Albatta, Alloh! Ana shu zotga shukr qilib, Unga iymon keltirib, Uning ibodatini qilsa, boʻlmasmidi?! Bu dunyoda yashab yurgan insonni oʻldiradigan kim?! Albatta, Alloh! Oʻlganlarni qiyomat kuni qayta tiriltiradigan, ularni soʻroq-savolga tutadigan, qilganiga yarasha mukofot yoki jazo beradigan kim?! Albatta, Alloh! Shunday ekan, inson oʻsha kunga tayyorgarlik koʻrsa boʻlmasmidi?! «Albatta, inson oʻta noshukrdir». Shuning uchun ham Allohga kufr keltiradi. Unga isyon qiladi. Uning koʻrsatgan yoʻlidan yurmaydi.)","Biz har bir ummatga shariat berganmiz. Ular oʻshanga amal qilguvchilardir. Bas, bu ishda hargiz sen ila nizo qilmasinlar. Robbingga daʼvat qil. Albatta, sen mustaqiym hidoyatdasan.","Agar ular sen bilan tortishsalar: «Alloh nima qilayotganingizni bilguvchidir.","Alloh qiyomat kuni siz ixtilof qilgan narsa boʻyicha orangizda hukm qiladir», deb ayt.","Alloh, albatta, osmonu yerdagi narsani bilishini, ana oʻsha, albatta, kitobda ekanini va, albatta, u narsa Allohga oson ekanini bilmaysanmi?! (Ushbu oyatdagi savol iqror qildirish maʼnosidadir. Yaʼni, bilar eding-ku, deyilmoqda. Oyati karimadagi «kitob»dan murod «Lavhul mahfuz»dir. Demak, hukm qilish Alloh taolo uchun hech narsa emas.)","Ular Allohni qoʻyib, U zot haqlarida biron hujjat tushirmagan, oʻzlarida u haqda ilm boʻlmagan narsaga ibodat qiladilar. Zolimlarga hech bir nusrat berguvchi yoʻqdir.","Ularga ochiq-oydin oyatlarimiz tilovat qilinayotganida, kufr keltirganlarning yuzlarida inkorni koʻrursan. Ular oʻzlariga oyatlarimizni tilovat qilib berayotganlarga chang solishga oz qolurlar. Sen ularga: «Buningizdan ham yomonroq narsaning xabarini beraymi? U doʻzaxdir. Alloh uni kufr keltirganlarga vaʼda qilgandir. Va u naqadar yomon qaytish joyidir», deb ayt.","Ey odamlar! Bir masal aytilmish, bas, unga quloq soling! Albatta, sizlar Allohni qoʻyib, topinayotgan narsalaringiz, agar barchalari birlashsalar ham, bitta pashsha yarata olmaslar. Va agar pashsha ulardan biron narsani tortib olsa, undan oʻshani qutqarib ololmaslar. Talab qiluvchi ham, talab qilingan ham ojiz boʻldi. (Boshqa katta jonzotlarni qoʻysinlar-u, eng kichik, eng haqir, eng ahamiyatsiz koʻringan pashshani yaratishga urinib koʻrsinlar. Yarata olmaslar. Xoʻsh, endi bir dona pashshani yarata olmagan butga qanday qilib topinish, sigʻinish, aytganini (agar aytolsa,) qilish mumkin? Aslo mumkin emas. Umuman aqlga, mantiqqa toʻgʻri kelmaydi. Pashsha juda zaif, haqir jon. Ammo, u sabab boʻlib baʼzi bir kasalliklarni tashib keltirsa, hammasi toʻplanib, harakat qilsa ham, oʻsha kasallikdan zarar koʻrayotganni yoki oʻlayotganni qutqarib qololmaydilar. Buni hamma hayotda koʻrgan. «Talab qiluvchi ham, talab qilingan ham ojiz boʻldi». Yaʼni, Allohdan oʻzganing ibodatini talab qiluvchi ham, ibodati talab qilingan narsalar ham ojizdirlar. Biron narsa qoʻllaridan kelmas.)","Ular Allohning qadrini joyiga qoʻymadilar. Albatta, Alloh kuchli va azizdir. (Yaʼni, ular yolgʻiz Allohning Oʻziga eʼtiqod qilishlari, faqat Ungagina ibodat qilishlari lozim edi. Ammo ular Allohning qadrini bilmadilar, unga shirk keltirdilar, Undan oʻzgalarga topindilar.)","Alloh farishtalardan va odamlardan Paygʻambarlar tanlar. Albatta, Alloh oʻta eshitguvchi va koʻrguvchidir.","U zot ularning oldilaridagi va ortlaridagi narsani bilur. Barcha ishlar yolgʻiz Allohgagina qaytarilur.","Ey iymon keltirganlar! Rukuʼ, sajda qilinglar va Robbingizga ibodat qilinglar hamda yaxshilik qilinglar, shoyadki najot topsangiz.","Va Alloh (yoʻlida) haq jihod qilingiz. U sizlarni tanlab oldi. Va sizga bu dinda hech tanglik qilmadi. Bu otangiz Ibrohimning millati. U sizlarni bundan oldin va bu(Qurʼon)da Paygʻambar sizlarga guvoh boʻlishi uchun, sizlar esa, odamlarga guvohlar boʻlishingiz uchun musulmonlar deb nomladi. Bas, namozni toʻkis ado etinglar, zakot beringlar va Allohga bogʻlaninglar. U sizning xojangizdir. Bas, U zot qanday ham yaxshi xoja va qanday ham yaxshi nusrat berguvchi. (Suraning oxiridagi ushbu ikki oyatda Alloh taolo Islom ummatiga nido qilmoqda. Bu nido musulmonlarga eng mahbub murojaat bilan «Ey iymon keltirganlar», deb boshlamoqda. Bu nido oʻzidan keyin keladigan amrlarni alohida koʻtarinki ruhda ado etishga undaydi. Undan keyin kelayotgan amrlar esa, rukuʼ, sajda qilmoqlikdir.)"],"23":["Batahqiq, moʻminlar najot topdilar.","Ular namozlarida xushuʼ qiluvchilardir.","Ular behuda narsalardan yuz oʻgirguvchilardir.","Ular zakotni ado qilguvchilardir.","Ular farjlarini saqlovchilardir.","Magar oʻz jufti halollari va qoʻllarida mulk boʻlganlardan (saqlamasalar), albatta, ular malomat qilinuvchi emaslardir.","Kim ana shundan boshqani talab qilsa, bas, ana oʻshalar tajovuzkorlardir.","Ular omonatlariga va ahdlariga rioya qilguvchilardir.","Ular namozlarini muhofaza qiluvchilardir.","Ana oʻshalar voris boʻlguvchilardir.","Ular Firdavsni meros olurlar, ular unda abadiy qolguvchilardir.","Qasamki, batahqiq, insonni loy sulolasidan yaratdik.","Soʻngra uni mustahkam qarorgohda nutfa qildik.","Soʻngra nutfadan alaqa yaratdik, alaqadan chaynalgan goʻsht yaratdik, chaynalgan parcha goʻshtdan suyak yaratdik, bas, suyakka goʻsht qopladik, soʻngra uni boshqa bir jonzot etib paydo qildik. Bas, yaratguvchilarning eng yaxshisi Alloh barakotli va buyukdir.","Soʻngra, albatta, sizlar bundan keyin oʻlguvchisizlar.","Soʻngra, albatta, sizlar qiyomat kuni qayta tiriltirilursizlar.","Batahqiq, Biz ustingizda yetti yoʻlni yaratdik. Biz maxluqotdan gʻofil boʻlgan emasmiz. (Ey odamlar, Biz ustingizga yetti tabaqa osmonni yaratib qoʻyganmiz. Shunday jonsiz, mustahkam va cheksiz narsalarda nima boʻlayotganini ham bilib turamiz.)","Biz osmondan oʻlchov ila suv tushirib, uni yerga joylashtirdik. Albatta, Biz uni ketkazishga ham qodirdirmiz. (Osmondan oʻlchov ila suv tushirib, uni yerda qarorlashtirish ham Alloh taoloning ishidir. Kim kerakli miqdorda osmondan suv tushira oladi? Yerdagi hamma suv osmondan oʻlchov bilan tushgandir. Ortiqcha ham emas, kam ham emas. Shuning oʻzini ibrat nazari bilan oʻylagan odam iymonga kelishi kerak. Suvni keltirgan zot ketkaza olmasmidi? Alloh taolo suvni ketkazishiga dalil sifatida baʼzan maʼlum joylarni suvdan bebahra qilib qoʻyadi. Oʻsha yerda qurgʻoqchilik boʻlib, hamma narsa halokatga yuz tutadi. Ana shu qurgʻoqchilik hodisalari ham Alloh taoloning qudratiga dalolat qiladi. Ular ham odamlarni iymonga chaqiradigan ibratli narsalardir.)","Va u(suv) ila siz uchun xurmo va uzum bogʻlari paydo qildik, sizga u(bogʻ)larda koʻp mevalar boʻlib, ulardan yersizlar.","Va Turi Siynodan chiqadigan bir daraxtni (paydo qildikki), u yogʻ va yeguvchilarga nonxurish ila oʻsur. (Yaʼni, ham yogʻ, ham nonxurish sifatida ishlatiladigan, koʻproq Turi Siynoda oʻsadigan zaytun ham ibratga sazovor daraxt sanaladi.)","Albatta, siz uchun chorva hayvonlarida ibrat bordir. Biz sizni ularning qorinlaridagi narsa ila sugʻorurmiz va siz uchun ularda koʻpgina manfaatlar bor va ulardan yersizlar.","Va ularga va kemalarga yuklanursizlar.","Batahqiq, Biz Nuhni qavmiga yubordik. Bas, u: «Ey qavmim, Allohga ibodat qiling. Siz uchun Undan oʻzga hech bir iloh yoʻqdir. Nahotki qoʻrqmasangiz?!» dedi.","Bas, uning qavmidan kufr keltirgan zodagonlari: «Bu sizga oʻxshash bashar, xolos, sizdan afzal boʻlib olmoqchi. Agar Alloh xohlasa, farishtalarni tushirar edi. Avvalgi ota-bobolarimizda buni eshitgan emasmiz.","U faqat bir jinni odam, xolos. Bas, uni bir oz muddat poylab turing», dedilar.","U: «Ey Robbim, meni yolgʻonchi qilganlarga qarshi menga nusrat ber», dedi. (Nuh alayhissalom haqiqiy nusrat qayerdaligini yaxshi bilganlari uchun darhol Allohga iltijo qilib, oʻzlarini yolgʻonchi sanaganlarga qarshi yordam soʻradilar.)","Bas, Biz unga: «Bizning koʻz oʻngimizda va vahiyimiz ila kema yasa. Bas, Bizning amrimiz kelib, tannur favvora boʻlganda, u(kema)ga har bir turdan bir juftdan va ahlingni chiqar, magar kimning ziddiga oldin soʻzimiz oʻtgan boʻlsa (chiqarma). Zulm qilganlar haqida Menga xitob qilma. Albatta, ular gʻarq qilinguvchilardir.","Bas, sen oʻzing bilan birga boʻlganlar ila kemaga joylashib olgach: «Bizni zolim qavmlardan qutqargan Allohga hamdlar boʻlsin», degin.","Va: «Ey Robbim, meni muborak manzilga tushirgin, Sen, Oʻzing manzilga tushirguvchilarning eng yaxshisisan», degin», dedik.","Albatta, bunda oyat-ibratlar bordir. Albatta, Biz sinovchi boʻlgan edik.","Soʻngra ulardan keyin boshqa avlodlarni paydo qildik. (Yaʼni, Nuh va uning qavmidan keyin boshqa xalqlarni paydo qildik.)","Bas, ularning ichiga oʻzlaridan boʻlgan Paygʻambarni: «Allohga ibodat qiling. Siz uchun Undan oʻzga iloh yoʻqdir, nahotki, qoʻrqmasangiz», deb yubordik. (Eʼtibor beradigan boʻlsak, bu Paygʻambar ham Nuh alayhissalomning soʻzlarining aynan oʻzini takrorlamoqda. Allohdan oʻzga ibodatga sazovor iloh yoʻqligini taʼriflamoqda va Allohga iymon keltirmay yurish qoʻrqinchli ekanini uqtirmoqda.)","Uning qavmidan kufr keltirgan, oxiratga roʻbaroʻ boʻlishini yolgʻonga chiqargan va Biz ularni hayoti dunyoda maishatparast qilib qoʻygan zodagonlari: «Bu sizga oʻxshagan bashar, xolos. Siz yegan narsadan yeydi, siz ichgan narsadan ichadi.","Agar oʻzingizga oʻxshagan basharga itoat qilsangiz, unda, albatta, siz ziyonkorlardandirsiz.","U sizga, oʻlsangiz, tuproq va suyak boʻlsangiz ham, albatta, chiqarilguvchi boʻlishingizni vaʼda qilmoqdami?!","Hayhot! Hayhot! Sizga vaʼda qilingan narsa naqadar uzoq!","Shu dunyodagi hayotimizdan boshqa hayot yoʻqdir. Oʻlamiz, tirilamiz va biz qayta tirilguvchi emasmiz.","U faqat Allohga nisbatan yolgʻon uydirgan odam, xolos. Biz unga iymon keltirguvchi emasmiz», dedilar. (Bu qavmning javobi ham mohiyatan Nuh qavmi javobining aynan oʻzi. Bu safar ham qavm nomidan zodagonlari javob bermoqda.)","U: «Ey Robbim, meni yolgʻonchi qilganlarga qarshi menga nusrat ber», dedi.","U zot: «Ozginadan soʻng ular nadomat chekuvchi boʻlurlar», dedi. (Yaʼni, Alloh taolo u Paygʻambar alayhissalomning duolarini qubul qildi. U zot alayhissalomga nusrat beradigan boʻldi. Va sabr qil, ozgina vaqtdan soʻng u kofirlar pushaymon qiluvchi boʻladilar, dedi.)","Bas, ularni haq ila qichqiriq oldi. Bas, Biz ularni xasu choʻpga aylantirdik. Daf boʻlsin zolim qavmlar!","Soʻngra ulardan keyin boshqa asr avlodlarini paydo qildik. (Yaʼni, qissasi keltirilgan oʻsha qavmdan keyin boshqa turli qavmlarni dunyoga keltirdik.)","Hech bir ummat oʻz ajalidan oldin ham ketmas, ortda ham qolmas.","Soʻngra Paygʻambarlarimizni ketma-ket yubordik. Har qachon bir ummatga oʻz Paygʻambari kelsa, uni yolgʻonchi qildilar. Bas, Biz ham ularni baʼzilari ortidan baʼzilarini (halokatga) ergashtiraverdik va ularni gapu soʻzga aylantirdik. Bas, daf boʻlsin iymon keltirmaydigan qavmlar!","Soʻngra biz Muso va birodari Horunni oyatlarimiz va ochiq hujjat ila yubordik.","Firʼavn va uning aʼyonlariga. Bas, ular mutakabbirlik qildilar va oʻzini yuqori qoʻygan qavm boʻldilar.","Bas, ular: «Oʻzimizga oʻxshagan ikki basharga iymon keltiramizmi?! Holbuki, ularning qavmi bizga qullik qilguvchi boʻlib turibdi-ku?! « dedilar. (Yaʼni, qanday qilib oʻzimizga oʻxshagan, qoʻlimizda qul boʻlib turgan Bani Isroil qavmining ikki odamiga Paygʻambar deb iymon keltiramiz, dedilar.)","Bas, ikkovlarini yolgʻonchi qildilar va halok qilinganlardan boʻldilar.","Batahqiq, Biz, shoyadki, hidoyat topsalar, deb Musoga Kitobni bergan edik.","Ibn Maryamni va uning onasini oyat-alomat qildik va ikkovlarini oqar suvli qarorgoh tepalikka joyladik. (Iyso ibn Maryam alayhissalomni va u kishining onalari Bibi Maryamni Alloh Oʻz qudratiga dalolat qiluvchi moʻjiza-alomat oʻlaroq yubordi va Baytul Maqdis yeridan oqar suvi bor, bir tepalikka joyladi.)","Ey Paygʻambarlar! Pok narsalardan yenglar va solih amallar qilinglar. Albatta, Men nima amal qilayotganingizni oʻta bilguvchiman.","Albatta, sizning bu ummatingiz yagona ummatdir. Men esa, Robbingizman. Bas, Mengagina taqvo qiling. (Ey Paygʻambarlar, sizning diningiz Islomdir. Robbingiz boʻlgan Allohga taqvo qiling.)","Bas, ular ishlarini oʻz oralarida pora-pora qilib boʻlib yubordilar. Har firqa oʻz huzurlaridagi narsa ila xursanddirlar. (Paygʻambarlar bir dinda boʻlgan edilar. Ammo ulardan keyingilar yagona dinni turli firqalarga parchalab yubordilar.)","Bas, sen ularni gʻaflatlarida bir muddat qoʻyib qoʻy.","Ular Bizning oʻzlariga molu dunyo va farzandlar ila madad berayotganimizni.","Ularga yaxshiliklarni tezlatishimiz, deb hisoblaydilarmi? Yoʻq! Ular sezmaslar.","Albatta, Robbilaridan qoʻrqib xavfda turuvchilar.","Va Robbilari oyatlariga iymon keltiradiganlar.","Va Robbilariga shirk keltirmaydiganlar.","Va beradigan narsalarini, albatta, Robbilariga qaytguvchi ekanliklaridan qalblari titragan holda berurlar.","Ana oʻshalar yaxshiliklarga shoshilurlar va ular oʻsha(yaxshilik)lar uchun musobaqa qilurlar.","Biz hech bir jonga toqatidan tashqari taklif qilmasmiz. Huzurimizda kitob bor. U haqni soʻzlaydir. Ularga zulm qilinmas.","Yoʻq! Ularning qalblari bundan gʻaflatdadir. Ularning bundan boshqa amallari bordir. Ular oʻsha (amal)larni qilguvchidirlar.","Toki ularning maishatparastlarini azob ila tutganimizda, birdan faryod solurlar.","Endi, bugun faryod solmang! Albatta, Biz tomonimizdan sizga nusrat qilinmas.","Batahqiq, Mening oyatlarim sizga tilovat qilinar edi. Siz esa, ortingizga qochar edingiz.","U(Kaʼba) bilan kibrlanar, tungi suhbatingizda behuda soʻzlar aytar edingiz.","Nahotki ular bu soʻzni tadabbur qilib koʻrmadilar? Yoki ularga avvalgi ota-bobolariga kelmagan narsa kelibdimi?","Yoki oʻz Paygʻambarlarini tanimasdan ular unga inkor qilguvchi boʻlmoqdalarmi?","Yoki, unda jinnilik bor, deydilarmi? Yoʻq! U ularga haq ila keldi. Ularning koʻplari esa, haqni yomon koʻrguvchidirlar. (Muhammad (s. a. v.) ularga haq din ila keldi. Shuning uchun ular Islomdan yuz oʻgirmoqdalar. Ular haqni yomon koʻradilar.)","Agar haq ularning havoyi nafslariga ergashsa, albatta, osmonlaru yer va ulardagi kimsalar fasodga uchrar edi. Yoʻq! Biz ularga oʻz sharaflarini keltirdik. Ular esa, sharaflaridan yuz oʻgirmoqdalar. (Haq bitta, yaʼni, Allohning dinidir. Hamma haqqa ergashmogʻi lozim. Chunki haq bitta, odamlarning havoyi nafslari esa, cheksizdir. Inchunin, havoyi nafs ila haqiqatga erishib boʻlmaydi. Qachon havoyi nafsning koʻyiga tushilsa, fasodga uchraladi. Allohdan kelgan haq–Islom odamlarni yoʻlga solishi kerak. Ammo odamlar u haqdan–Islomdan yuz oʻgirmoqdalar. Haqni–Islomni havoyi nafslariga ergashtirishni istaydilar. Biz keltirgan Qurʼon–Islom–haq ular uchun sharafdir. Kim haqqa ergashsa, amal qilsa, shon-sharafga ega boʻladi.)","Yoki sen ulardan xaroj soʻrayapsanmi?! Bas, Robbingning xaroji yaxshiroqdir. U zot eng yaxshi rizq berguvchidir.","Albatta, sen ularni toʻgʻri yoʻlga chaqirasan.","Albatta, oxiratga iymon keltirmaydiganlar bu yoʻldan ozguvchidirlar.","Agar ularga rahm qilib, ularga yetgan zararni kushoyish qilsak ham, tugʻyonlarida bardavom boʻlib, adashib-uloqib yuraveradilar.","Batahqiq, Biz ularni azob ila tutdik, bas, ular Robbilariga boʻyin ham egmadilar, tazarruʼ ham qilmadilar.","Toki qachon ularga shiddatli azob eshigini ochganimizda, toʻsatdan noumid boʻlguvchilardir.","U zot sizga quloqni, koʻzlaru qalblarni paydo qilgan zot. Naqadar oz shukr qilursiz!","U zot sizlarni yer yuzida yaratib, taratgandir. Va Ungagina toʻplanursizlar.","U zot tiriltirur va oʻldirur. Kechayu kunduzning almashinishi ham Unga oid. Nahotki aql yuritmasangiz?","Yoʻq! Ular avvalgilar aytgan narsaga oʻxshash narsani aytdilar.","Ular: «Biz oʻlib tuproq va suyak boʻlganimizdan keyin ham-a? Biz, albatta, qayta tiriltiriluvchimizmi-a?","Batahqiq, bizga ham, bundan oldin ota-bobolarimizga ham bu vaʼda qilingan edi. Bu avvalgilarning afsonasidan boshqa narsa emas», dedilar.","Sen: «Agar bilsangiz, Yer va undagi kimsalar kimnikidir?» deb ayt.","«Allohnikidir», derlar. Sen: «Nahotki eslatma olmasangiz?!» degin.","Sen: «Yetti osmonning Robbi kim? Ulugʻ arshning Robbi kim?» deb ayt.","Ular: «Allohnikidir», derlar. Sen: «Nahotki qoʻrqmasangiz?!» deb ayt.","Sen: «Agar bilsangiz (ayting-chi), har bir narsaning mulki qoʻlida boʻlmish, Oʻzi himoya qiladigan va Undan himoya qilinmaydigan zot kim?!» deb ayt. (Yaʼni, xohlagan kishisini Oʻz himoyasiga ola biladigan, boshqalar Undan himoyalana olmaydigan zot kim?)","«Allohnikidir», derlar. Sen: «Qandoq ham sehrlanmoqdasiz-a?!» deb ayt. (Agar oʻsha narsalar Allohniki ekanini bilsangiz, nima uchun Allohga iymon keltirmayapsiz?! Kofir holingizda yuribsiz? Buni faqat sehrlangan odam qilishi mumkin, xolos. Siz qandoq ham sehrlangansiz-a?! Ushbu savollar mushriklarga, Allohga shirk keltiradiganlarga berilmoqda. Bunda Allohga turli-tuman but-sanamlarni shirk keltiradiganlar ham, ahli kitob boʻla turib, Allohga baʼzi shaxslarni shirk keltiradiganlar ham barobardirlar. Chunki ularning hammasi Allohdan boshqa hech bir zot biror narsani yarata olmasligini, biror narsaga molik boʻla olmasligini bilgani holda, Allohning vahdoniyatiga emas, shirkka qarab yuradilar. Ular bu ishni hujjat-dalil yoʻqligidan qiladilarmi?)","Yoʻq! Biz ularga haqni keltirdik. Ular esa yolgʻonchilardir.","Alloh hech bir farzand tutmagan, U bilan birga hech bir iloh boʻlmagan. Shundoq boʻlganida, har bir iloh oʻzi yaratgan narsasi bilan ketib, baʼzilari baʼzilaridan ustun kelar edi. Alloh ular qilayotgan vasfdan pok boʻldi. (Yaʼni, Allohdan boshqa yana iloh boʻlganida, u ham oʻziga biror narsalarni yaratgan boʻlar edi. Oqibatda har bir iloh oʻzi yaratgan narsani oʻzicha tasarruf qilaverib, dunyoning nizomi buzilar edi. Har bir iloh oʻzinikini oʻtkazaman deb urinishi natijasida oralarida nizo chiqar, baʼzilari baʼzilaridan ustun kelar edi. Dunyo nizomi buzilar edi. Bu aqida Allohdek zotga ayb, nuqsonni vasf qilishdir.)","U gʻaybni va hozirni bilguvchidir. U ular shirk keltirayotgan narsadan oliydir. (Alloh taolo hamma narsani–gʻaybni ham, hozirni ham bilguvchi zotdir. U zot mushriklar shirk keltirayotgan narsadan oliydir.)","Sen: «Ey Robbim, agar menga, albatta, ularga vaʼda qilingan narsani koʻrsatadigan boʻlsang.","Ey Robbim, meni zolim qavmlar ichida qilmagin», deb ayt.","Albatta, Biz ularga vaʼda qilayotgan narsamizni senga koʻrsatishga qodirmiz.","Sen esa, yomonlikni goʻzal narsa ila daf qil. Biz nima vasf qilayotganlarini yaxshi bilguvchimiz.","Sen: «Ey Robbim, sendan shaytonlarning vasvasasidan panoh soʻrayman!","Sendan, ey Robbim, ularning menga hozir boʻlishlaridan panoh soʻrayman», deb ayt.","Toki ulardan biriga oʻlim kelgan chogʻda: «Ey Robbim, meni (hayotga) qaytargin.","Shoyadki tark qilgan narsamda solih amal qilsam», der. Yoʻq! Albatta, bu (quruq) soʻz boʻlib, u aytguvchi, xolos. Ularning ortida qayta tiriladigan kunlarigacha toʻsiq bordir.","Bas, qachonki surga puflanganda, u kunda oralarida na nasab qolur va na bir-birlarini surishtirurlar. (Yaʼni, qiyomatdan darak berguvchi surga puflangan paytda har kim oʻzi bilan ovora boʻlib, odamlar orasida naslu nasab aloqalari qolmas. Balki hamma otasi, onasi, aka-ukasi, bola-chaqasidan qochadigan boʻlib qoladi.)","Kimning mezonlari ogʻir kelsa, bas, ana oʻshalar, oʻzlari najot topguvchilardir.","Kimning mezoni yengil kelsa, bas, ana oʻshalar, oʻzlariga ziyon qilibdilar. Jahannamda abadiy qolguvchi boʻlibdilar.","Yuzlarini olov kuydirur. Ular unda badbashara holda boʻlurlar.","Sizlarga oyatlarim tilovat qilingan emasmidi?! Bas, siz ularni yolgʻonga chiqargan emasmidingiz?! (Shunda ular oʻz ayblariga iqror boʻladilar.)","Ular: «Ey Robbimiz, badbaxtligimiz oʻzimizdan ustun kelib, zalolatga ketgan qavm boʻlgan ekanmiz.","Ey Robbimiz, bizni bu (doʻzax)dan chiqargin, agar yana (eski holimizga) qaytsak, bas, albatta, zolimlardan boʻlurmiz«, derlar.","U zot: «U(yer)da xor boʻlib qolavering va Menga gapirmang!","Aniqki, Mening bandalarimdan bir guruhi: «Ey Robbimiz, Biz iymon keltirdik. Bizni magʻfirat qilgin. Bizga rahm qilgin. Sening Oʻzing rahm qilguvchilarning yaxshisisan», degan edilar.","Bas, siz ularni masxara qildingiz. Hattoki ular (ni masxara qilish) sizga Mening zikrimni unuttirdi. Siz ulardan kular edingiz.","Albatta, Men bugun ularni sabr qilganlari uchun mukofotladim. Albatta, ular oʻzlari yutuqqa erishguvchilardir.","U zot: «Yer yuzida necha yil qoldingiz?» dedi.","Ular: «Bir kun yoki kunning baʼzisicha qoldik. Hisoblovchilardan soʻra», dedilar.","U zot: «Agar bilsangiz, juda oz qoldingiz, xolos», dedi. (Endi koʻradigan kuningizga nisbatan juda oz qoldingiz.)","Nahotki Bizning sizni yaratishimiz behuda boʻlgan va siz Bizga qaytarilmassiz, deb hisoblasangiz?! (Ey mushriklar, nahotki Biz sizni behudaga yaratgan boʻlsak? Nahotki siz oxiratda bizga qaytarilmasangiz?!)","Bas, haq podshoh Alloh yuksakdir. Hech bir iloh yoʻq. Magar u–karamli Arshning Robbi bor.","Kim Alloh bilan birga boshqa ilohga iltijo qilsa, bu xususda hech bir dalili yoʻqdir. Bas, uning hisobi faqat Robbining huzuridadir. Albatta, kofirlar najot topmaslar. (Allohga boshqa ilohni sherik etganlar, hech bir dalil-hujjatsiz shirk keltirgan boʻladilar. Undoq odamlar bilan Alloh taolo Oʻzi bilib hisob-kitob qiladi. Suraning avvalida moʻminlarning, albatta, najot topishlari aytilgan edi. Suraning oxirida esa, kofirlarning najot topmasliklari taʼkidlanmoqda. Va nihoyat, oxirgi oyatda Alloh taolodan rahmat va magʻfirat soʻrash tavsiya qilinmoqda.)","Sen: «Ey Robbim, magʻfirat qil, rahm qil. Oʻzing rahm qilguvchilarning yaxshisisan», deb ayt."],"24":["(Bu bir) suradir. Biz uni nozil qildik. Biz uni farz qildik. Biz unda ochiq-oydin oyatlarni nozil qildik. Shoyadki eslasangiz.","Zinokor ayol va zinokor erkak, ikkovlaridan har birini yuz darradan uring. Agar siz Allohga va oxirat kuniga iymon keltiradigan boʻlsangiz, sizlarni ularga nisbatan Allohning dinida shafqat tutmasin. Va ularning azobiga bir toifa moʻminlar guvoh boʻlsinlar. (Nikohda boʻlmay, er-xotinlik hayotini tanib olmaganlar zino qilsalar, ushbu oyatning hukmiga binoan yuz darradan uriladi.)","Zinokor erkak faqat zinokor yoki mushrika ayolga nikohlanur. Zinokor ayolga faqat zinokor yoki mushrik erkak nikohlanur. Bu moʻminlarga harom qilinmishdir. (Zinokor Islom jamiyati jismidan umuman olib tashlanadi. Guvohligi qabul qilinmaydigan boʻladi, moʻminlar bilan nikohda boʻlishdan man etiladi va hokazo.)","Pokiza ayollarga (boʻhton) toshi otib, soʻngra toʻrtta guvoh keltira olmaganlarni sakson darra uringlar va ularning guvohligini abadiy qabul qilmanglar. Ana oʻshalar fosiqlardir.","Magar bundan keyin tavba qilib, oʻzini isloh qilganlar (mustasno). Zero, Alloh oʻta magʻfiratli va oʻta rahmlidir.","Oʻz juftlariga (boʻhton) toshi otib, faqat oʻzlaridan boshqa guvohlari boʻlmaganlar esa, bas, ulardan har birining guvohligi Allohning nomi ila toʻrt marta, albatta, u rostgoʻylardan ekanligi haqida shohidlik berishdir.","Beshinchisida esa, agar yolgʻonchilardan boʻlsa, unga Allohning laʼnati boʻlishini (aytishlikdir).","Va u(ayol)dan azobni qaytaradigan narsa, Allohning nomi ila toʻrt marta, albatta, u(er) yolgʻonchilardandir, deb shohidlik berishidir.","Beshinchisida esa, agar u(er) rostgoʻylardan boʻlsa, oʻzi(ayol)ga Allohning gʻazabi boʻlishini (aytishlikdir).","Agar sizlarga Allohning fazli va marhamati boʻlmaganida!.. Albatta, Alloh tavbalarni koʻplab qabul qilguvchi va oʻta hikmatli zot boʻlmaganida edi!..","Albatta, ifkni keltirganlar oʻzingizdan boʻlgan bir toʻdadir. Uni oʻzingizga yomonlik deb hisoblamang. Aksincha, u siz uchun yaxshilikdir. Ulardan har bir kishi uchun oʻzi qilgan kasbning gunohi bordir. Ulardan (gunohning) kattasini koʻtargan kimsaga buyuk azob bordir. (Islom dushmanlari aqliy tortishuvlarda, jang maydonlarida musulmonlardan ustun kela olishlariga koʻzlari yetmaganidan keyin musulmonlarning eng kuchli nuqtasini zaiflashtirish uchun ochiqdan-ochiq igʻvo, boʻhton, tuhmat va uydirma qilishga oʻtdilar. Gapni boshqa yoqqa burib, haqiqatdan chetga chiqish, yolgʻondan uydirma toʻqish, boʻhton va igʻvo qilish arab tilida »ifk« deyiladi. Munofiqlar Oyisha onamizga nisbatan ifk uyushtirdilar. Ularning ifkiga baʼzi sodda musulmonlar ham qoʻshildilar. Orada katta fitna chiqdi. Oyisha onamizni zino qilganlikda ayblay boshladilar. U kishiga nisbatan ifk–igʻvo, boʻhton, tuhmat va uydirma uyushtirildi. Bu hodisa »Ifk hodisasi« nomi bilan mashhurdir.)","U(ifk)ni eshitgan vaqtingizda moʻminlar va moʻminalar oʻzlari haqida yaxshi gumonga borib: «Bu ochiq-oydin ifk-ku!» desalar boʻlmasmidi?!","U(ifkchi)lar oʻsha(ifk)ga toʻrtta guvoh keltirsalar boʻlmasmidi?! Bas, guvohlarni keltira olmagan chogʻda ana oʻshalar oʻzlari Allohning huzurida yolgʻonchidirlar.","Agar dunyoyu oxiratda sizlarga Allohning fazli, marhamati boʻlmaganida, oʻzingiz ichiga shoʻngʻigan narsa uchun sizni, albatta, buyuk azob tutar edi.","Oʻshanda siz u(ifk)ni tillaringiz ila ilib olar, ogʻzingiz ila oʻzingiz bilmagan narsani gapirar edingiz va u(ifk)ni oʻzingizga yengil sanardingiz. Holbuki, u Allohning nazdida buyukdir.","Uni eshitgan chogʻingizda: «Bizga buni gapirmogʻimiz toʻgʻri kelmaydi. Sen, Oʻzing poksan! Bu katta boʻhtondir! « desangiz boʻlmasmidi?!","Agar moʻmin boʻlsangiz, hargiz u(ifk)ga oʻxshash narsaga qaytmasligingizni Alloh sizga vaʼz-nasihat qilur.","Alloh sizga oyatlarni bayon qilur. Va Alloh oʻta bilguvchi, oʻta hikmatli zotdir.","Albatta, iymon keltirganlar ichida fohisha tarqalishini yaxshi koʻradiganlarga bu dunyoyu oxiratda alamli azob bordir. Alloh biladir, sizlar bilmassizlar.","Agar sizlarga Allohning fazli, marhamati boʻlmaganida... Va, albatta, Alloh oʻta shafqatli va rahmli boʻlmaganida...","Ey iymon keltirganlar! Shaytonning izidan ergashmang. Kim shaytonning izidan ergashsa, bas, albatta, u fohisha va munkarga buyuradi. Agar sizlarga Allohning fazli va marhamati boʻlmaganida abadul-abad ichingizdan biror kishi poklana olmas edi. Lekin Alloh Oʻzi xoxlagan kishini poklaydir. Alloh oʻta eshitguvchi, oʻta bilguvchi zotdir.","Sizlardan fazl va boylik egasi boʻlganlar qarindoshlarga, miskinlarga va Allohning yoʻlida muhojir boʻlganlarga (nafaqa) bermaslikka qasam ichmasinlar, bas, avf etsinlar, oʻtib yuborsinlar. Alloh sizlarni magʻfirat qilishini xush koʻrmaysizlarmi?! Alloh oʻta magʻfiratli, oʻta rahmli zotdir». (Oyisha onamiz quyidagilarni aytadilar: «Alloh taolo meni oqlash uchun ushbu oyatlarni nozil qilganida Abu Bakr (u kishi qarindosh boʻlgani va faqirligi uchun Mistoh ibn Asosaga nafaqa berib turardilar): »Allohga qasamki, Oyisha haqida qilgan gapi uchun Mistohga abadiy hech narsa bermayman», dedilar. Shunda Alloh taolo quyidagi oyatni nozil qildi. Abu Bakr (r. a.) darhol: «Ha! Allohga qasamki, albatta, Alloh meni magʻfirat qilishini xush koʻraman», dedilar va Mistohga berib yurgan nafaqalarini qaytadan joriy qildilar. Soʻngra: «Allohga qasamki, bu nafaqani undan hech uzmayman», dedilar».)","Albatta, pokiza, gʻofila va moʻmina ayollarga (boʻhton) toshi otganlar, bu dunyoyu oxiratda laʼnatlanurlar. Ularga katta azob bordur.","U kunda tillari, qoʻllari va oyoqlari qilib yurgan amallari haqida ularga qarshi guvohlik berur.","Oʻsha kunda Alloh ularning haq jazolarini toʻliq berur va ular Allohning Oʻzi ochiq haq ekanini bilurlar.","Nopok xotinlar nopok erkaklar uchundir. Nopok erkaklar nopok xotinlar uchundir. Pokiza ayollar pokiza erkaklar uchundir. Pokiza erkaklar pokiza ayollar uchundir. Ana oʻshalar u (boʻhtonchi)lar aytayotgan narsalardan poklangandirlar. Ularga magʻfirat va goʻzal rizq bordir. (Shu bilan ifk hodisasi — musulmonlar jamoasini katta musibatga solgan hodisa haqidagi oyatlar nihoyasiga yetdi. Bu hodisa Paygʻambar (s. a. v.) oilasining pokligini va bu oilani Allohning Oʻzi saqlashini isbot etdi.)","Ey iymon keltirganlar! Oʻz uylaringizdan boshqa uylarga to izn soʻramaguningizcha va ularning ahliga salom bermaguningizcha, kirmang. Ana shunday qilmogʻingiz siz uchun yaxshidir, shoyadki eslasangiz. (Ushbu oyatga amal qilinsa, birovning xonadoniga izn soʻrab, salom berib kirilsagina, turli noqulay holatlarning oldi olinadi. Izn soʻramay kirgan odam uy egalarining noqulay holda turganlarini koʻrib qolsa, gunoh boʻladi. Ikki tomon ham hijolatga tushadi. Balki xusumat, urush-janjal chiqishi ham mumkin. Baʼzi hollarda uyda ayol kishi yolgʻiz boʻlishi, ustiga begona erkak kirib, orada igʻvo, boʻhton, fitna chiqishi mumkin.)","Bas, agar u(uy)larda birortani topmasangiz, to sizga izn berilmaguncha ularga kirmang. Agar sizga, qayting, deyilsa, bas, qayting, oʻsha siz uchun pokdir. Alloh nima amal qilayotganingizni oʻta bilguvchidir.","Maskan boʻlmagan, siz uchun foyda bor uylarga (iznsiz) kirishingizda gunoh yoʻqdir. Alloh nimani oshkor qilayotganingizni va nimani yashirin qilayotganingizni biladi.","Sen moʻminlarga ayt, koʻzlarini tiysinlar va farjlarini saqlasinlar. Ana shu ular uchun pokdir. Albatta, Alloh nima hunar qilayotganlaridan xabardordir.","Sen moʻminalarga ayt: Koʻzlarini tiysinlar, farjlarini saqlasinlar va ziynatlarini koʻrsatmasinlar, magar zohir boʻlgan ziynatlar boʻlsa (mayli). Roʻmollarini koʻksilariga toʻsib yursinlar. Ziynatlarini koʻrsatmasinlar, magar erlariga yo otalariga yo erlarining otalariga yo oʻgʻillariga yo erlarining oʻgʻillariga yo aka-ukalariga yo aka-ukalarining oʻgʻillariga yo opa-singillarining oʻgʻillariga yo ayollariga yo oʻz qoʻllarida mulk boʻlganlarga yo (ayollarga) behojat erkak xizmatchilarga yo ayollar avratining farqiga bormagan yosh bolalarga (boʻlsa mayli). Maxfiy ziynatlarini bildirish uchun oyoqlarini (yerga) urmasinlar. Allohga barchangiz tavba qiling, ey moʻminlar! Shoyadki, najot topsangizlar». (Ushbu oyatda Alloh taolo Paygʻambarimizga (s. a. v.) xitob qilib, moʻmina ayollarga kiyim kiyish va avrat berkitish borasida oʻzlarini qanday tutishlari lozimligini bayon qilib berishini buyurmoqda. Muslima ayollar ham nomahramlarga shahvat nazari bilan qaramasliklari lozimligi ushbu oyatdan tushuniladi. Ayolning ayolga nisbatan avrati kindigidan tizzasigachadir. Ayol kishining nomahram erkaklarga nisbatan avrati yuzi va ikki kaftidan boshqa butun badanidir. Moʻmina-muslima ayol sharafini saqlash uchun Allohning amriga itoat etib, avratini nomahram erkaklardan berkitmogʻi kerak. Buning uchun esa, yuzi va ikki kaftidan boshqa butun tanasini toʻsib turadigan kiyim kiymogʻi lozim. Shuningdek, kiyim yupqa, badanga yopishgan, tor boʻlmasligi ham zarur. Nomahram erkaklarning eʼtiborini jalb qilmaydigan darajada boʻlishi kerak. Ziynat deganda chiroyli kiyimlar, taqinchoqlar va ayollar oʻzlarini chiroyli koʻrsatish uchun ishlatadigan turli vositalar koʻzda tutiladi. Ayol kishi ushbu oyatga amal qilib, ziynatini nomahramlardan berkitmogʻi lozim, berkitishning imkoni boʻlmay qolganda gunoh emas. boshlariga oʻragan roʻmollari faqat sochlarini emas, balki tomoqlari, koʻksilari va koʻkraklarini ham toʻsib tursin. Toki, ularning jamoli begona koʻzlarga moʻljal boʻlmasin, turli fitnalar keltirib chiqarmasin. Johiliyat davrida ayollar oyoqlariga ham turli taqinchoqlar, qoʻngʻiroqlar taqib olishar ekan. Keyin esa, erkaklarning eʼtiborini jalb etish uchun oyoqlarini yerga qattiq-qattiq urib yurib, haligi taqinchoqlarning ovozini chiqarishar ekan. Bu esa, oʻz navbatida, erkaklarning shahvatini qoʻzgʻagan, ayolning ortidan tushib xiralik qilishiga va oxir-oqibat zinoga olib borishi mumkin boʻlgan.)","Oralaringizdagi nikohsizlarni va qulu choʻrilaringizdan solihlarini nikohlab qoʻying. Agar faqir boʻlsalar, Alloh ularni Oʻz fazlidan boy qilur. Alloh (fazli) keng, oʻta bilguvchi zotdir.","Nikoh (imkoni)ni topa olmaganlar, to Alloh ularni Oʻz fazlidan boy qilgunicha iffatlarini saqlasinlar. Qoʻllaringizda mulk boʻlganlardan (ozodlik) vasiqasini istaydiganlari boʻlsa, bas, ularda yaxshilik borligini bilsangiz, ular ila vasiqa yozing va Allohning sizga bergan molidan ularga bering. Hayoti dunyoning oʻtkinchi matohini istab, poklikni iroda qilgan choʻrilaringizni fohishalikka majbur qilmang. Kim ularni majbur qilgan boʻlsa, bas, albatta, Alloh ular majbur qilganlaridan keyin oʻta magʻfiratli va rahmli zotdir. (Ushbu oyati karimada uchta muhim masala–nikohga qodir boʻlmaganlar nima qilishligi, ozod boʻlishni istab, oʻz xojasi bilan shartnoma tuzgan, maʼlum mablagʻ evaziga ozod boʻlishga harakat qilayotgan qulu choʻrilar va fohishabozlik, yaʼni, baʼzi ayollarni zinoga majburlab pul topishga urinish masalalari muolaja etilmoqda.)","Batahqiq, Biz sizlarga ochiq-oydin oyatlarni, sizdan oldin oʻtganlardan misolni va taqvodorlar uchun vaʼzni nozil qildik.","Alloh osmonlar va yerning nuridir. Uning nurining misoli xuddi bir tokcha, uning ichiga chiroq qoʻyilgan, chiroq esa, shisha ichida, shisha esa, goʻyo durdan boʻlgan bir yulduz boʻlib, sharqiy ham, gʻarbiy ham boʻlmagan muborak zaytun daraxtidan yoqilur. Uning moyi oʻziga olov tegmasa ham, yoritib yuboray deydir. (Bu) nur ustiga nurdir. Alloh xohlagan odamni Oʻz nuriga hidoyat qilur. Alloh odamlarga misollarni keltirur. Alloh har bir narsani oʻta bilguvchidir. (Suraning nomi ushbu oyati karimadan olingan. Bu oyati karima «Nur» oyati deb ham nomlanadi. Oyatda Alloh taoloning Oʻzi Oʻz zoti oliysini «Nur» deb atamoqda. Lekin bu nur siz bilan bizning tushunchamizdagi moddiy, koʻzga taʼsir oʻtkazadigan yorugʻlik nuri emas. Alloh taoloning hech bir sifati siz bilan bizning tasavvurimizga toʻgʻri kelmaydi. Bu jumlani baʼzi ulamolarimiz, «Alloh osmonlar va yerni munavvar qilguvchidir», deb tushuntirganlar. Boshqa birlari esa, «Alloh osmonlaru yerni vujudga keltirguvchidir», deganlar. Yana boshqalari, Alloh taolo osmonlar va yerni, yaʼni, borliqni Oʻz nuridan yaratgandir, degan maʼnoda tafsir qilganlar. Bu tushunchalarning hammasi arab tilida «nur» soʻzi ifoda etadigan maʼnolardan olingandir. «Nur» soʻzi aslida oʻzi zohir boʻlib, oʻzgalarni ham zohir etuvchi vujudga nisbatan ishlatiladi. Misol uchun, qorongʻulikda yorugʻlik zohir boʻlib, avval oʻzi koʻrinadi va shuning barobarida atrofni ham yoritadi-koʻrsatadi.)","(U) bir uylardaki, Alloh ularning koʻtarilishiga va ularda Oʻz ismi zikr qilinishiga izn bergandir. Ularda Unga ertayu kech tasbih ayturlar;","Bir kishilarki, ularni tijorat ham, oldi-sotdi ham Allohning zikridan, namozni toʻkis ado etishdan va zakot berishdan mashgʻul qila olmas. Ular qalblar va koʻzlar iztirobga tushadigan kundan qoʻrqarlar.","Alloh ularni qilgan amallarining eng goʻzali ila mukofotlashi va fazli karamidan ziyoda qilib berishi uchundir. Alloh xohlagan kishiga behisob rizq berur.","Kufr keltirganlarning amallari sahrodagi sarobga oʻxshaydir. Chanqoq odam uni suv deb hisoblaydir. Qachonki, uning oldiga kelsa, hech narsani topmas. Va u oldida Allohni topur. Bas, U zot uning hisobini toʻliq qilur. Alloh oʻta tez hisob qilguvchidir. (Ushbu oyati karimada Alloh taoloning nuridan mahrum boʻlgan kofir va munofiqlarning holi ajoyib uslub ila vasf etilmoqda. Oʻzlari chanqoq odamga, amallari esa, sahrodagi sarobga oʻxshatilmoqda. Munofiqlar ham bu dunyoda oʻzlaricha, u qildim-bu qildim, deb amallarini sanab, »yaxshi-yaxshi« umidlar bilan oxirat tomon ketaveradilar. Qiyomat qoim boʻlib, »manzil«ga yetganlarida esa, hech narsa topmaydilar. Qilgan amalimizning savobini topamiz, deb borgan joylarida Allohni topadilar va Alloh ularni bekamu koʻst hisob-kitob qiladi.)","Yoki xuddi qaʼrsiz dengizdagi zulmatlarga oʻxshaydir. Uning ustidan mavj qoplagandir, u(mavj)ning ham ustidan mavj va uni esa, bulut (qoplagandir). Bir-birining ustidagi zulmatlardir. U qoʻlini chiqarsa, koʻra olmas. Kimgaki Alloh nur bermasa, uning uchun nur boʻlmas. (Ushbu oyati karimada ham Allohning nuridan mahrum boʻlgan kofir va munofiqlarning holati ajoyib uslub ila vasf qilinmoqda. Yaʼni, dengizni katta toʻlqin qoplab olgandir. Bu toʻlqin esa, zulmat ustiga zulmatdir. Ammo bu hali hammasi emas. Oʻsha qop-qora toʻlqinning ustidan qop-qora bulut qoplab turibdi. Bu zulmatlar ostida kofir va munofiq qanday qilib Allohning nurini koʻrsin. U oʻz qoʻlini koʻra olmagandan keyin, Allohning nurini koʻra olmasligi turgan gap.)","Allohga osmonlar va yerdagi bor jonzot va saf tortgan holidagi qushlar tasbih aytishini ham koʻrmaysanmi?! Har biri oʻz duosi va tasbihini, batahqiq, bilmishdir. Alloh nima amal qilishlarini oʻta bilguvchidir.","Osmonlar va yerning mulki Allohnikidir va qaytish ham faqat Allohgadir.","Alloh bulutlarni haydashini, soʻngra birga toʻplashini, soʻngra uyib qoʻyishini koʻrmayapsanmi?! Bas, uning orasidan yomgʻir chiqayotganini koʻrursan. U zot osmondan, undagi togʻlardan doʻl tushirib, u bilan Oʻzi xohlagan kishilarga musibat yetkazur va uni Oʻzi xohlagan kishilardan burib yuborur. Uning chaqmogʻining yarqirashi koʻzlarni ketkazgudek boʻlur.","Alloh kecha va kunduzni aylantirib turur. Albatta, bunda koʻzi borlar uchun ibrat bordir.","Alloh hamma jonivorni suvdan yaratdi. Bas, ulardan baʼzilari qorni bilan yuradir, baʼzilari ikki oyoq bilan yuradir va baʼzilari toʻrt (oyoq) bilan. Alloh Oʻzi xohlagan narsani yaratur. Albatta, Alloh har bir narsaga qodirdir.","Batahqiq, Biz ochiq-oydin bayon qilguvchi oyatlarni tushirdik. Alloh Oʻzi xohlagan kimsani toʻgʻri yoʻlga hidoyat qiladir.","Ular: «Allohga va Paygʻambarga iymon keltirdik va itoat qildik», derlar. Soʻngra ulardan bir guruhi yuz oʻgirib keturlar. Ana oʻshalar moʻmin emaslar. (U guruh–munofiqlardir. Ular tillari bilan: «Allohga va Paygʻambarga iymon keltirdik va itoat qildik», deydilar. Lekin iymonga amalni qoʻshmaydilar. Ogʻizlari bilan iymonli ekanlari haqida safsata sotsalar ham, hayotda iymon taqozosi ila amal qilmay, Islom shariatiga yurishni istamay, boshqa qonun-qoidalar asosida yashashga urinadilar. Allohga va Paygʻambarga (s. a. v.) iymonlari borligini aytsalar ham, ularga itoat etishlari haqida ogʻiz koʻpirtirib soʻzlasalar ham, amal qilmaydilar. Ularga, ayniqsa, Nur surasi oʻqilganda yuraklari siqilib ketadi. Chunki bu sura ularga zinoni, ochiq-sochiqlikni, axloqiy buzuqlik boʻlmish havoyi nafsning xohishlarini man qilib, odob-axloq doirasida halol-pok yashashni taklif etadi. «Soʻngra ulardan bir guruhi yuz oʻgirib keturlar». Tillari bilan aytgan gaplariga amal qilish kerak boʻlganda yuz oʻgirib, boshqa tomonga qarab ketadilar.)","Ularni qachonki Allohga va Uning Paygʻambariga oralarida hukm chiqarish uchun chorlansa, banogoh ulardan bir guruhi yuz oʻgirguvchilardir.","Agar haq ular(tarafda) boʻlsa, u (Paygʻambar)ga boʻyin egib kelurlar.","Ularning qalblarida maraz bormi?! Yoki shubha qildilarmi?! Yoxud Alloh va Uning Paygʻambari ularga zulm qilishidan qoʻrqadilarmi?! Yoʻq! Ularning oʻzlari zolimlardir.","Albatta, moʻminlarning Allohga va Uning Paygʻambariga oralarida hukm chiqarish uchun chorlanganlaridagi gaplari: «Eshitdik va itoat qildik», demoqlaridir. Ana oʻshalarning oʻzlarigina najot topguvchilardir.","Kim Allohga va Uning Paygʻambariga itoat etsa hamda Allohdan qoʻrqib, Unga taqvo qilsa, bas, ana oʻshalargina yutuqqa erishguvchilardir.","Ular agar amr qilsang, albatta, (jihodga) chiqishlari haqida Alloh nomi bilan jon-jahdlari ila qasam ichadilar. Sen: «Qasam ichmanglar! (Bu jihod) maʼlum toatdir! Albatta, Alloh nima amal qilayotganlaringizdan xabardordir», deb ayt.","Sen: «Allohga itoat qilinglar, Paygʻambarga itoat qilinglar. Bas, agar yuz oʻgirib ketsangiz, u(Paygʻambar)ga oʻziga yuklatilgan narsa, sizga oʻzingizga yuklatilgan narsa. Agar unga itoat qilsangiz, hidoyat topursiz. Paygʻambarning zimmasida ochiq-oydin yetkazishdan boshqa narsa yoʻq», deb ayt.","Alloh sizlardan iymon keltirib, solih amallarni qilganlarga ularni yer yuzida xuddi ulardan oldin oʻtganlarni xalifa qilganidek xalifa qilishni, ular uchun Oʻzi rozi boʻlgan dinni mustahkamlashni va ularning xavf-xatarlaridan soʻng omonlikni badal qilib berishni vaʼda qildi. Mengagina ibodat qilurlar va Menga hech narsani shirk keltirmaslar. Shundan keyin ham kim kufr keltirsa, bas, ana oʻshalar, oʻzlari fosiqlardir. (Oldingi oʻtgan ummatlardan qaysi biri Alloh taologa iymon keltirgan va bu iymoni haqiqiy boʻlib, butun vujudini qamrab olgan hamda oʻsha haqiqiy iymonlari taqozosi ila solih amallar qilib hayot kechirgan boʻlsa, Alloh taolo ularni yer yuziga Oʻzining xalifasi etib tayinlab qoʻygan edi. Yer yuzida hukmi yuritilishi uchun ularni Oʻziga oʻrinbosar qilib qoʻygan edi. Endi oʻshalar kabi yer yuzida xalifa boʻlish imkoniyati faqat Muhammadning (s. a. v.) ummatlarida bordir. Ularning mazkur xalifalikka erishishlari uchun asosiy shart–iymon keltirib, amali solih qilishdir. Islom ummati qachon ushbu shartni bajarganida, Alloh taolo vaʼdasining ustidan chiqqan.)","Namozni toʻkis ado etinglar, zakot beringlar va Paygʻambarga itoat qilinglar. Shoyadki rahm qilsangiz.","Sen kufr keltirganlarni yer yuzida qochib qutula olguvchilardir, deb hisoblama! Ularning joyi doʻzaxdir. U naqadar yomon borar joydir!","Ey iymon keltirganlar! Qoʻlingizda mulk boʻlganlar va oʻzingizdan balogʻatga yetmaganlar sizdan uch vaqtda izn soʻrasinlar: bomdod namozidan oldin, peshinda kiyimlaringizni yechadigan paytingizda va xufton namozidan soʻng. (Ushbu) uch vaqt, siz uchun avratdir. Ulardan keyin sizga ham, ularga ham gunoh yoʻq. Ular sizning atrofingizda, bir-biringizga aylanib turuvchidirsiz. Alloh sizlarga oyatlarni ana shunday bayon qilur. Alloh oʻta bilguvchi, oʻta hikmatli zotdir. (Ushbu oyati karimada zikri kelagan shaxslar uch vaqtda, albatta izn soʻrashlari kerak: «... bomdod namozidan oldin...» Chunki bu vaqtda odam hali oʻrnida yotgan boʻladi. «... peshinda kiyimlaringizni yechadigan paytingizda...» Qurʼon nozil boʻlgan issiq oʻlkalarda peshin vaqtida yechinib, salqinlab, dam olmaslikning hech iloji yoʻq. «... xufton namozidan soʻng». Bu vaqtda ham kishilar yechinib, dam olayotgan boʻladi. «(Ushbu) uch vaqt siz uchun avratdir». Yaʼni, avratlar ochiladigan vaqtdir. Shuning uchun qul va choʻrilar ham, balogʻatga yetmagan yosh bolalar ham izn soʻrab kirsinlar. Odatda xizmatchilar va yosh bolalarning kirib chiqishlari koʻp boʻladiShuning uchun mazkur avrat vaqtlaridan boshqasida izn soʻramay kirishlariga ruxsat berildi.)","Qachon sizning yosh bolalaringiz balogʻatga yetsalar, ulardan oldingilar izn soʻraganidek, izn soʻrasinlar. Alloh Oʻz oyatlarini sizga ana shunday bayon qilur. Alloh oʻta bilguvchi, oʻta hikmatli zotdir.","Ayollardan (keksayib) oʻtirib qolganlari, nikohni umid qilmaydiganlariga ziynatlarini koʻz-koʻz qilmagan holda kiyimlarini qoʻyishlarida gunoh yoʻqdir. Iffat talabida boʻlsalar, oʻzlari uchun yaxshidir. Alloh oʻta eshitguvchi, oʻta bilguvchi zotdir. (Ushbu oyatdagi «kiyimlari»dan murod katta yopinchiq va hamda ustdan kiyiladigan ridodir. Ayol kishi oʻta qarib, nikohdan umuman umidsiz boʻlib qolganda paranji-chimmat qilmaslikka ruxsat bor. Lekin, shunday boʻlsa ham, iffatlarini saqlaganlari oʻzlari uchun yaxshidir. Ammo voqeʼlikda qari ayollarning oʻranib-chirmanib, yoshlarning ochilib-sochilib yurgani koʻriladi. Bu ham, yaʼni, yoshlarning bu holati shariatga boʻyinsunmaslikning bir koʻrinishidir.)","Koʻzi ojizga gunoh-tanglik yoʻqdir. Choʻloqqa gunoh-tanglik yoʻqdir. Bemorga gunoh-tanglik yoʻqdir. Sizning oʻzingizga ham oʻz uyingizdan yo otalaringizning uylaridan yo onalaringizning uylaridan yo aka-ukalaringizning uylaridan yo opa-singillaringizning uylaridan yo amakilaringizning uylaridan yo ammalaringizning uylaridan yo togʻalaringizning uylaridan yo xolalaringizning uylaridan yo siz kalitiga molik boʻlgan yoki doʻstingiz (uyidan) yemoqligingizda (gunoh-tanglik) yoʻqdir. Sizlarga jamlangan yoki tarqoq holda yemoqlikda ham gunoh-tanglik yoʻqdir. Uylarga kirgan chogʻingizda oʻzlaringizga Allohdan boʻlgan pokiza va muborak tabrik ila salom beringlar. Alloh sizlarga oyatlarni ana shunday bayon qilur. Shoyadki aql yuritsangiz. (Ushbu oyati karimaning avvalida koʻzi ojiz, choʻloq va bemor kishilarga nimada gunoh boʻlmasligi, tanglik yoʻqligi haqida mufassir ulamolarimiz ixtilof qilishgan. Bir guruhlari, ularning jihodga chiqmay qolishlarida gunoh va tanglik yoʻq, deydilar. Boshqalari, bu yerda esa, soʻz jihod haqida emas, balki aynan taom yemoq haqida ketmoqda, shuning uchun ham mazkur jumlani «taom yeyishda ularga gunoh va tanglik yoʻq», deb tushunmoq kerak, deydilar va bu fikrlarini tasdiqlovchi rivoyatlarni keltiradilar. Ikkinchi toifa mufassirlarning fikrlari kuchliroqdir. «Kalitga molik boʻlish» uy egasining kalitni ishonib topshirib qoʻyishidir. Ana shunday kishilar insof bilan, qorinlari toʻyguncha yesalar, boʻlaveradi. Oyisha onamizdan Imom az-Zuhriy qilgan rivoyatda aytilishicha, Rasululloh (s. a. v.) bilan jihodga joʻnab ketayotgan musulmonlar uylari kalitlarini oʻzlari bilgan kishilarga topshirib, hojatingiz tushganda yemoqni sizga halol qildik, deb ketar ekanlar. Ammo kalitni olib qolganlar, quruq manzirat uchun aytilgan boʻlsa kerak, deb oʻzlarini tiyisharkan. Ushbu oyat bilan ularga Alloh ham izn bergan.)","Albatta, moʻminlar Allohga va Uning Rasuliga iymon keltirgan kishilardir. Ular u (Paygʻambar) bilan birga jamlovchi (muhim) ishda boʻlsalar, undan izn soʻramasdan turib ketib qolmaslar. Albatta, sendan izn soʻraydiganlar, ana oʻshalar Allohga va Uning Rasuliga iymon keltiradiganlardir. Ular baʼzi ishlari uchun sendan izn soʻrasalar, ulardan kimga xohlasang, izn ber va ular uchun Allohga istigʻfor ayt. Albatta, Alloh oʻta magʻfiratli, oʻta rahmli zotdir.","Paygʻambarning orangizdagi daʼvatini bir-biringizning daʼvatingizga oʻxshatmang. Batahqiq, Alloh sizlardan panalab, asta-asta sugʻirilib chiqib ketadiganlarni yaxshi biladir. Uning ishiga xilof qiladiganlar oʻzlariga fitna yetishi yoki alamli azob yetishidan hazir boʻlsinlar. (Ushbu oyati karimaning birinchi jumlasi haqida ulamolar uch xil fikr aytganlar. Uchala fikr ham bir-birini toʻldirib keladi. Birinchi fikrga binoan, Paygʻambarni chaqirishda, bir-biringizni chaqirishingizdagi lafzlarni qoʻllamang, degani. Ikkinchi fikrga koʻra, Paygʻambarning chaqirigʻini, buyrugʻini boshqalarning chaqirigʻi kabi oddiy qabul qilmang, balki alohida ahamiyat va eʼtibor bilan qabul qiling, deganidir. Uchinchi fikrga koʻra esa, Paygʻambarning duosini, boshqalarning duosiga oʻxshatmang, deganidir. U zotning duosi, albatta, qabul boʻlishi muqarrardir.)","Ogoh boʻlinglar! Albatta, osmonlaru yerdagi narsalar Allohnikidir. U zot sizning qay holatda ekaningizni yaxshi biladir. Uning Oʻziga qaytariladigan kunda esa, qilgan amallari haqida ularga xabar berur. Alloh har bir narsani oʻta bilguvchi zotdir."],"25":["Olamlarga ogohlantiruvchi boʻlsin uchun bandasiga Furqonni nozil qilgan Zot barakotli, ulugʻdir.","U osmonlaru yerning mulki Unga xos boʻlgan, Oʻziga farzand tutmagan, mulkida sherigi boʻlmagan, har bir narsani oʻlchov ila oʻlchab yaratgan Zotdir.","U Zotdan boshqa, hech narsa yarata olmaydigan, oʻzlari yaratiladigan, oʻzlari uchun zararga ham, nafga ham ega boʻlmaydigan, oʻlimga ham, hayotga ham, qayta tirilishga ham molik boʻlmaydigan «xudo»lar tutdilar.","Kufr keltirganlar: «Bu (Qurʼon) uydirmadan boshqa narsa emas. Uni oʻzi uydirib oldi va bunda unga boshqa qavmlar koʻmak berdilar», dedilar. Bas, shubhasiz, zulm va yolgʻon guvohlik keltirdilar.","Ular: «Bu avvalgilarning afsonasidir. Ularni yozdirib olgan. Holbuki, ular unga ertayu kech imlo qilinur», dedilar. (Avvalgi mushriklar har qancha johil boʻlsalar ham, hozirgilarga qaraganda bir oz insofli boʻlgan ekan. Ular hozirgi mushriklarga oʻxshab, «yozib olgan», demasdan, «yozdirib olgan», demoqdalar. Chunki ular Muhammadning (s. a. v.) oʻqish va yozishni bilmasliklarini yaxshi biladilar. Shuning uchun afsonalarni boshqalarga yozdirib olgan, dedilar. Yaʼni, oʻsha afsonalar Muhammadga (s. a. v.) ertayu kech aytib turiladi, deydilar.)","Sen: «Uni osmonlaru yerdagi sirni biladigan Zot nozil qildi. Albatta, U magʻfiratli va rahmli Zotdir», degin. (Qurʼonni hamma narsani bilguvchi zot–Alloh nozil qilgandir. Hamma narsani bilguvchi zot oʻtgan ummatlarning tarixini ham juda yaxshi biladi. Oʻtganlarning afsonalarini birovdan yozdirib olishga hojat yoʻq. Balki bu afsonalar yolgʻon, bidʼat va xurofotlarga toʻliqdir. Qurʼoni Karimda esa, oʻtgan ummatlarning qissalari eng rost va toʻgʻri ravishda keltiriladi. Kishilarni ulardan oʻrnak olishga chaqiriladi. Vaqt oʻtib, ilm rivojlanishi bilan bu haqiqat yana ham ravshanlashib bormoqda.)","Ular: «Bu ne Paygʻambarki, taom yeb, bozorda yuradir?! Unga bir farishta tushirilsa edi, u bilan ogohlantirguvchi boʻlar edi.","Yoki unga xazina tashlansa yoxud uning bogʻi boʻlsayu undan yesa», dedilar. Zolimlar: «Sizlar faqat sehrlangan kishiga ergashyapsizlar, xolos», dedilar.","Senga qanday misollar keltirganiga nazar sol! Bas, ular yoʻldan ozdilar. Endi yoʻl topishga qodir emaslar.","Agar xohlasa, senga oʻshandan yaxshirogʻini–ostidan anhorlar oqib turadigan bogʻlarni va qasrlarni qilib beradigan Zot barakotli va ulugʻ boʻldi. (Alloh xohlasa, bu narsalarni istagan lahzada Paygʻambariga ato etishi hech gap emas. Lekin maqsad bogʻu rogʻ va qasrlar emas. Maqsad hamma narsaning xoliqi Alloh taoloning roziligiga erishishdir.)","Yoʻq! Ular soat(qiyomat)ni ham yolgʻonga chiqardilar. Va Biz soat(qiyomat)ni yolgʻonga chiqarganlarga doʻzaxni tayyorlab qoʻydik. (Kofirlar, qiyomat boʻlmaydi, dedilar. Qiyomat boʻladi, deyayotganlarning gapi yolgʻon, dedilar. Holbuki, doʻzax ularni kutib turibdi. Ushbu mushriklar toʻppa-toʻgʻri oʻsha tayyor doʻzaxga ravona boʻladilar.)","Vaqtiki u ularni uzoq joydan koʻrganida, uning gʻazabnok qaynashini va boʻkirishini eshiturlar. (Qiyomat soatini yolgʻonga chiqarganlarga Alloh taolo tomonidan tayyorlab qoʻyilgan doʻzax shu darajada dahshatliki, u kofirlarni uzoqdan koʻrishi bilan gʻazabi toʻlib-toshib, qaynab oʻkira boshlaydi.)","Uning tor joyiga kishanlangan hollarida tashlaganlarida esa, oʻsha joyda (oʻzlariga) halokat tilarlar.","Bugungi kunda bir halokatni emas, koʻp halokatni tilanglar! (Bir marta halok boʻlib qutulib keta olmaysizlar. Hali koʻp halok boʻlasizlar. Oʻzingizcha, halok boʻlsak, bu azoblardan qutularmiz, deb oʻylamanglar.)","Bu yaxshimi yoki taqvodorlarga tayyorlab qoʻyilgan mangulik jannati yaxshimi? U (jannat) ular uchun mukofot va qaytish joyidir.","Ularga u yerda xohlagan narsalari bor, abadiy holda qolurlar. Bu Robbing zimmasidagi masʼuliyatli vaʼdadir. (Jannatda taqvodor moʻminlarga istagan narsalari bor. Jannatda nimalar borligini sanab adogʻiga yetib boʻlmaydi. Shuning uchun osongina, istagan narsalari bor, deb qoʻyildi.)","U(mushrik)larni va Allohdan oʻzga ibodat qilgan narsalarini toʻplagan kunda U zot: «Anavi bandalarimni sizlar adashtirdingizmi yoki ular oʻzlari yoʻldan ozdilarmi?!» deydir. (Bu dunyoda mushrik boʻlib, Allohdan oʻzga narsalarga ibodat etib, oʻshalarning «aytgani»ni qilib, oʻshalarning «roziligi»ni tilab oʻtgan manavi bandalarning mushrik boʻlishlari sababi nima? Ularni oʻsha «xudo»lari adashtirdimi? Yoki oʻzlari yoʻldan ogʻdilarmi?)","Ular: «Ey pok Parvardigor, Sendan oʻzgani doʻst tutmoq biz uchun yarashmas. Lekin sen ularni va ota-bobolarini (shunchalik) huzurlantirdingki, hatto ular zikringni unutdilar va halokat qavmi boʻlib qoldilar», derlar.","Batahqiq, ular sizlarni aytayotgan narsangizda yolgʻonchiga chiqardilar. Endi (azobni) burishga ham, yordam olishga ham qodir boʻlmassiz. Sizdan kim zulm qilgan boʻlsa, unga azobni tortdiramiz.","Biz sendan oldin yuborgan Paygʻambarlarimiz ham, albatta, taom yer va bozorlarda yurar edilar. Baʼzilaringizni baʼzilaringizga sinov qildik. Sabr qilasizlarmikin?! Robbing koʻrguvchi boʻlgan zotdir. (Oddiy bashardan Paygʻambar yuborib odamlarni sinovga uchratdik, baʼzilari sinovdan oʻta olmay, oddiy bashar ham Paygʻambar boʻladimi, deb yoʻldan adashdi. Ularning bu tasarruflari esa, iymonlilar uchun sinov boʻldi.)","Bizga uchrashdan umidsiz boʻlganlar, bizga farishtalar tushirilsa yoki, Robbimizni koʻrsak edi, derlar. Batahqiq, ular oʻzlaridan ketdilar va katta tugʻyon-la tugʻyon qildilar.","Ular farishtalarni koʻradigan kunda, ha, oʻsha kunda jinoyatchilarga xushxabar boʻlmas. Va u(farishta)lar: «Harom, harom», derlar. (Ey kofir-mushriklar, sizlarga xushxabar harom, jannat harom, magʻfirat harom, mehr-shafqat harom, osoyishtalik harom... derlar.)","Va qilgan amaliga kelib, ularni toʻzon kabi sochib yuborurmiz. (Kofirlarning bu dunyoda qilgan baʼzi bir yaxshi amalaridan umidlari boʻlishi mumkin. Ammo iymon boʻlmaganidan keyin u ishlar hech foyda bera olmaydi. Qiyomat kuni Alloh taolo u amallarni ham toʻzon kabi sochib yuboradi.)","Oʻsha kunda jannat egalarining qarorgohlari va oromgohlar gʻoyat yaxshidir.","U kunda bulutli osmon yorilib, farishtalar boʻlak-boʻlak tushurilurlar.","U kunda hukmronlik Rohmanga haq boʻlur. U kun kofirlar uchun koʻp qiyin kun boʻlur.","U kunda zolim ikki qoʻlini tishlab: «Ey voh!!! Paygʻambar ila bir yoʻlni tutganimda edi!» der.","«Ey voh!!! Koshki falonchini doʻst tutmasam edi.","Batahqiq, menga zikr (Qurʼon) kelgandan soʻng u (doʻst) meni adashtirdi. Shayton insonni yordamsiz tashlab ketguvchidir», der. (Muhammaddan (s. a. v.) boshqaga ergashganlarning barchasining holi shu boʻladi. Qurʼon yoʻlidan boshqa yoʻlga yurgan, Qurʼondan boshqa dasturga amal qilganlarning barchasining holi shu boʻladi. Qiyomat kuni ularning hammasining bu dunyodagi «doʻst»lari yordamsiz tashlab ketadi.)","Va Paygʻambar: «Ey Robbim, albatta, mening qavmim ushbu Qurʼonni tark etdilar», dedi. (Muhammad (s. a. v.) Robbilariga shikoyat qilib, ey Robbim, mening qavmim–Quraysh ushbu Qurʼonni tark etdi, dedilar. Alloh taolo ularning qilmishlarini juda yaxshi biladi. Ammo Paygʻambar (s. a. v.) oʻzlarining dardlarini toʻkib solish uchun, Allohning amrini toʻla bajarganliklarini bildirish uchun aytmoqdalar.)","Ana shunday. Har Paygʻambar uchun jinoyatchilardan dushman qilganmiz. Hidoyat va yordamchilikda Robbing Oʻzi kifoya qilur.","Kufr keltirganlar: «Unga Qurʼon bir yoʻla nozil qilinsa edi», dedilar. Biz sening qalbingni u bilan sobit qilish uchun shunday qildik va uni dona-dona qilib oʻqidik. (Yaʼni, ey Muhammad, Biz sening qalbingni Qurʼon bilan sobit qilish, quvvatlash uchun uni boʻlak-boʻlak holda nozil etdik va goʻzal ravishda dona-dona qilib oʻqib berdik. Qurʼon birdaniga tushmasdan, boʻlak-boʻlak boʻlib tushar, har vahiy kelganida Paygʻambarning (s. a. v.) qalblari quvvatlanar, kuchlariga kuch, gʻayratlariga gʻayrat qoʻshilar edi.)","Ular senga biror masal keltirsalar, Biz, albatta, senga haqni va goʻzal sharhini keltiramiz.","Jahannam tomon yuz tuban hollarida sudraladiganlar, ana oʻshalar, makonlari eng yomon, yoʻllari eng adashgan kimsalardir.","Batahqiq, Biz Musoga kitobni berdik va unga akasi Horunni vazir qildik.","Bas: «Ikkingiz bizning oyatlarimizni yolgʻonga chiqargan qavmga boring», dedik. Soʻng ularni yer bilan yakson qildik.","Va Nuh qavmi Paygʻambarlarni yolgʻonga chiqarganlarida gʻarq etdik va ularni odamlarga ibrat qildik. Hamda Biz zolimlarga alamli azoblar tayyorlab qoʻydik.","Od, Samud va quduq egalarini hamda bu oradagi asrlarni esla. (Biz «quduq» deb tarjima qilgan soʻz oyati karimada «rass» iborasi ila ifodalangan boʻlib, ichi mahkamlanmagan, nurab turgan quduqqa aytiladi. Rivoyatlarda kelishicha, oʻsha jinoyatchi qavm quduq atrofida oʻtirganlarida, u qulab, hammalari ichiga tushib halok boʻlgan ekanlar. Baʼzi tafsirchilarimiz, bu qavm Solih alayhissalom qavmi, desalar, boshqalari Shuayb alayhissalom qavmidir, deydilar. Ibn Jarir Tabariy esa, ular Uxdud egalaridir, degan ekanlar. Ular haqida Buruj surasida soʻz yuritilgan.)","Ulardan har biriga misollar keltirdik. Va ularni qirib bitirdik. (Yaʼni, oʻsha oʻtmish asrlardagi barcha jinoyatchi qavmlarning har biriga oʻrnak boʻlsin uchun misollar keltirdik. Ular ibrat olmadilar, oʻzlarini oʻnglamadilar.)","Batahqiq, ular yomonlik yomgʻiri yogʻdirilgan shaharga kelgan edilar. Uni koʻrmagan edilarmi?! Yoʻq! Ular qayta tirilishdan umidsiz edilar. (Ushbu oyati karimadagi «yomonlik yomgʻiri yogʻdirilgan shahar»dan murod Lut alayhissalom qavmi yashagan shahardir. Maʼlumki, bu shaharni Alloh taolo tosh yogʻdirib halok qilgandir. Oyatdagi «Ular»dan murod esa, Makka kofirlari. Ular Shomga qilgan safarlarida Lut alayhissalom qavmi shahri xarobalari yonidan oʻtar edilar. Agar ularda insof boʻlganida, zarracha tafakkur boʻlganida, koʻrganlaridan ibrat olardilar.)","Ular seni koʻrgan vaqtlarida: «Alloh Paygʻambar qilib yuborgan shumi?!","Agar sabr qilmaganimizda, albatta, u bizni sal boʻlmasa xudolarimizdan ozdirardi-ya!» deb masxaraga olurlar. Yaqinda–azobni koʻrgan chogʻlarida–kim yoʻldan ozganroq ekanini bilurlar.","Havoi nafsini oʻziga xudo qilib olganni koʻrdingmi?! Endi sen unga vakil boʻlasanmi?! (Yoʻq, albatta. Paygʻambarning vazifasi havoi nafsini oʻziga xudo qilib olganlarga vakil boʻlish emas, balki Allohdan kelgan amrlarni kishilarga yetkazishdir.)","Yoki sen ularning koʻplari tinglay oladilar yo anglay oladilar, deb hisoblaysanmi? Aslida, ularning hayvonlardan farqi yoʻq. Balki yana ham yoʻldan ozganroqdirlar. (Ushbu oyati karimada Paygʻambarga (s. a. v.) tasalli va havoi nafslarini xudo qilib olgan kofirlarni yerga urish bor.)","Robbingning soyani qanday yoyib qoʻyganini koʻrmadingmi? Agar xohlasa, uni jilmas qilardi. Soʻngra quyoshni Biz unga dalil qildik. (Ha, agar Alloh xohlasa, soyani jilmas qilib, bir xilda, yaʼni, uzaymay ham, qisqarmay ham turadigan qilib qoʻyar edi. Misol uchun yerni aylanmaydigan qilib qoʻysa, soya jilmay turaverar edi, biz eʼtibor bermaydigan soyaning yoyilishi hodisasi ortida Allohning ulkan qudrati turibdi.)","Soʻngra Biz uni Oʻzimizga asta-sekin tortib oldik.","U siz uchun kechani libos, uyquni istirohot qilgan va kunduzni tirilish (zamoni) qilgan Zotdir.","U Oʻz rahmati oldidan shamollarni xushxabar qilib yuborgan Zotdir. Va osmondan pok suv tushirdik.","U ila oʻlik yurtni tiriltirishimiz va oʻzimiz yaratgan koʻplab chorva hayvonlari hamda insonlarni sugʻorishimiz uchun.","Batahqiq, Biz u(Qurʼon)ni eslatma olishlari uchun oralarida turlicha tasarruf qilib koʻrdik. Odamlarning koʻplari kufrdan boshqa narsadan bosh tortdilar. (Alloh osmondan pok suv tushiradi. Alloh osmondan pok soʻz (Qurʼon) tushiradi. Alloh osmondan tushirgan pok suvi ila oʻlik diyorlarni tiriltiradi, chanqoq hayvon va odamlarni sugʻoradi. Alloh osmondan tushirgan pok soʻzi bilan maʼnaviy oʻlik xalqlarni tiriltiradi, ruhiy chanqoqlarni, tashnalarni ruhiy-maʼnaviy taʼlimotlar ila sugʻoradi. Qurʼonni ularga turli uslublar ila taqdim qildik. Lekin ular bundan oʻzlariga eslatma olmadilar.)","Agar xohlasak, har shaharga bitta ogohlantirguvchi yuborar edik.","Kofirlarga itoat etma! Ularga qarshi u(Qurʼon) bilan katta jihod qil!","U ikki dengizni-bunisi chuchuk-shirin, unisi shoʻr-achchiq qilib oqizib qoʻygan va oralariga koʻrinmas toʻsiq hamda ochilmas sarhad qilgan Zotdir. (Barcha ummonlar va dengizlar shoʻr, daryolar chuchuk. Daryolar oqib borib suvini dengizlarga, ummonlarga quyadi. Ammo bu bilan dengiz suvi chuchuk boʻlib qolmaydi, daryo suvi shoʻr boʻlib qolmaydi. Zotan, daryolarning suvi ham dengiz va ummonlardan bugʻlanib koʻtarilgan suvdan iborat.)","U suvdan bashar yaratgan va uni nasl-nasab, quda-anda qilib qoʻygan Zotdir. Robbing qodir boʻlgan Zotdir.","Ular Allohdan oʻzga ularga naf ham, zarar ham yetkazmaydigan narsalarga ibodat qilarlar. Va kofir Robbiga qarshi yordamchi boʻlgandir.","Biz seni faqat xushxabarchi va ogohlantirguvchi etib yuborganmiz, xolos.","Sen: «Men sizlardan buning uchun ajr soʻramayman, faqat, kim xohlasa, Robbi tomon yoʻl olishini (soʻrayman)», deb ayt. (Islomda eʼtiqod-dinga kirish yoki uning aʼzolari safida boʻlish uchun toʻlanadigan badal yoki soligʻu majburiyatlar yoʻq. Xohlagan kishi Allohga tomon yoʻl olsin. Unga iymon keltirsin, ibodat qilsin. Boshqalar esa, uning yoʻlini toʻsmasin.)","Va barhayot, oʻlmaydigan Zotga tavakkal qil hamda Uni hamdu sano ila poklab yod et. Bandalarining gunohlaridan oʻta xabardor boʻlishda Uning Oʻzi kifoyadir.","U osmonlaru yerni va ularning orasidagi narsalarni olti kunda yaratgan, soʻngra arshni egallagan zotdir. U Rohmandir. Bas, oʻsha oʻta Xabardordan soʻra. (Ushbu maʼnolar eʼtiqod bobida oʻta nozik va hassos ekanligi eʼtiboridan ulamolarimiz juda ham ehtiyotkorlik bilan bayon qilishga harakat qiladilar. «Olti kun» masalasiga kelganda, baʼzilari, bu dunyoning kunlariga oʻxshash kunlar, Alloh «boʻl» desa boʻlib qolar edi-yu, lekin bandalarga shoshilmay ish qilishni oʻrgatish maqsadida shunday qildi, deydilar. Boshqalari esa, «olti kun» qanday kunlar ekanini Allohning Oʻzi biladi. Bizning kunlarimiz osmonlaru yer yaratib boʻlingandan keyin, quyosh majmuasidagi sayyoralar nizomi yaratilgandan keyin vujudga kelgan tushunchalar, deydilar. «Soʻngra» kalimasi odatda «keyin» maʼnosidagi tartibni ifoda qiladi, bu oyatdagi «soʻngra» esa, martabani bildiradi.)","Qachonki ularga: «Rohmanga sajda qilinglar!» deyilsa, ular: «Rohman nima? Sen buyurgan narsaga sajda qilaveramizmi?» derlar. Bu ularning uzoqlashishini ziyoda qilur.","Osmonda burjlar qilgan va unda chiroq va nur sochguvchi oy qilgan Zot barakotli-buyuk boʻldi.","U ibrat olmoqni iroda qilgan va shukr qilmoqni iroda qilgan kishi uchun kecha-kunduzni birin-ketin qilgan Zotdir.","Rohmanning bandalari yer yuzida tavozuʼ ila yuradigan va johillar xitob qilganida, «salom», deydiganlardir. (Rohmanning suyukli bandasi boʻlish sharafiga erishgan inson yer yuzida kamtarlik, sodda va muloyimlik bilan yuradi. Unda takabburlik, manmanlik, vahshatu dahshat, turli soxta koʻrinishlardan asar ham boʻlmaydi. Shu bilan birga, boʻshanglik, irodasizlik, behuda qisilib-qimtinish, oʻzini pastga urishlik ham boʻlmaydi.)","Ular tunlarni Robbilariga sajda qilib, bedor oʻtkazurlar.","Ular: «Ey Robbimiz, Oʻzing bizdan jahannam azobini burgin, albatta, jahannam azobi doimiydir.","Albatta, u eng yomon qarorgoh va turar joydir», deydiganlardir.","Ular infoq qilganlarida isrof ham va xasislik ham qilmaslar. U ikkisi oʻrtasida moʻtadil boʻlurlar.","Ular Alloh bilan birga biror ilohga iltijo qilmaslar. Alloh (oʻldirishni) harom qilgan jonni nohaqdan oʻldirmaslar. Zino qilmaslar. Kim ana shuni qilsa, uqubatga duchor boʻlur. (Allohga shirk keltirish ulkan zulmdir. Birovni nohaqdan oʻldiradigan odam Rohmanning suyukli bandasi boʻla olmaydi. Zinoda ham moddiy, ham maʼnaviy ravishda odam oʻldirish ruhi bor. Zinokorlar bola koʻrishdan qochadilar. Ular, zinodan bola boʻlib qolmasligiga urinadilar. Bu esa, oʻziga xos odam oʻldirishdir. Allohga shirk keltirsa, nohaqdan odam oʻldirsa va zino qilsa, gunohning uqubatiga duchor boʻladi.)","Qiyomat kuni uning azobi bir necha barobar koʻpaytirilur va u(azob) da xor boʻlib abadiy qolur.","Magar kim tavba qilsa, iymon keltirib, solih amal qilsa, bas, Alloh ana oʻshalarning yomonliklarini yaxshiliklarga almashtirur. Alloh magʻfiratli va rahmli boʻlgan zotdir.","Kim tavba qilib, solih amal qilsa, u, albatta, Allohga (haqiqiy) qaytish ila qaytar. (Tavbaning haqiqiy yoki soxta ekanligi uning eʼlonidan keyingi amaldan bilinadi. Agar eʼlondan keyingi amal solih-yaxshi boʻlsa, tavba haqiqiy, yomon boʻlsa, tavba soxta boʻladi. Gunoh ham faqat niyat emas, balki qilingan amaldir, tavba ham amalsiz boʻlmas.)","Ular yolgʻon guvohlik bermaydiganlardir va behuda narsalar oldidan oʻtsalar, hurmatlarini saqlagan holda oʻtarlar.","Ularga Robbilarining oyatlari eslatilganda, u(oyat)larga gung va koʻrlardek tashlanmaslar. (Rohmanning suyukli bandalari butparast mushriklarga oʻxshab, oʻzlari anglamagan narsaga yopishib olmaydilar. Mushriklar soxta xudolariga xuddi koʻr va karquloqdek bilib-bilmay, koʻrib-koʻrmay, eshitib-eshitmay yopishib oladilar. Agar ular «xudo»larining nima ekanligini bilganlarida, koʻrganlarida va eshitganlarida, hech qachon ularga ibodat qilmas edilar.)","Ular: «Ey Robbimiz, Oʻzing bizga jufti halollarimizdan va zurriyotlarimizdan koʻzimiz quvonadigan narsa hadya et hamda bizlarni taqvodorlarga yoʻlboshchi et», deydiganlardir.","Ana oʻshalar sabr qilganlari uchun «gʻurfa» ila mukofotlanurlar va unda tabrik va salom bilan qarshilanurlar. (Arab tilida oliy maqom xos xonani «gʻurfa» deyiladi. Tafsirchi ulamolarimizdan baʼzilari ushbu oyatdagi «gʻurfa» soʻziga, «oliy daraja», «jannat», «jannatdagi alohida xona» maʼnolarini berishgan. Aslida, hammasini qoʻshib, jannatdagi oliy maqom xos xona, desak maqsadga muvofiq boʻlsa kerak.)","Ular oʻshanda abadiy qolurlar. U qanday ham goʻzal qarorgoh va manzildir.","Sen: «Agar duo-iltijolaringiz boʻlmasa, Robbim sizlarga hech qiymat bermas. Bas, batahqiq, siz yolgʻonga chiqardingiz. Endi sizlarga (azob) lozim boʻlur», deb ayt."],"26":["To. Sin. Mim.","Bular ochiq kitobning oyatlaridir.","Ehtimol, (ular) moʻmin boʻlmaganlari uchun sen oʻzingni halok qilmoqchidirsan?!","Agar xohlasak, ularga osmondan oyat-moʻjiza nozil qilurmiz. Bas, ularning boʻyinlari unga egilib qoladir.","Ularga Rohmandan yangi eslatma kelibdiki, albatta, undan yuz oʻgirguvchi boʻlganlar.","Bas, batahqiq, yolgʻonga chiqardilar. Yaqinda ularga oʻzlari istehzo qilgan narsaning xabari kelajakdir.","Ular yerga qaramaydilarmi?! Biz unda goʻzal navlardan qanchalarini undirib qoʻyibmiz.","Albatta, bunda oyat-belgi bor. Lekin koʻplari moʻmin boʻlmaslar.","Albatta, Robbing Oʻzi azizu mehribondir.","Robbing Musoga: «U zolim qavmga borgin.","Firʼavn qavmiga. (Bizdan) qoʻrqmaydilarmi?! « deb nido qilganini esla.","U: «Ey Robbim, ular meni yolgʻonchi qilishlaridan qoʻrqaman.","Va dilim siqilishidan hamda tilim burro boʻlmay qolishidan. Bas, Horunni elchi qil.","Mening zimmamda ular nazdida gunoh bor. Bas, meni oʻldirishlaridan xavfdaman», dedi.","U zot: «Yoʻq! Bas, ikkingiz Bizning oyat-moʻjizalarimiz ila boringlar. Albatta, Biz ikkingiz bilan eshitguvchilarmiz.","Bas, Firʼavnga boringlar va unga: «Biz Robbul Olamiynning Paygʻambarlarimiz.","Bani Isroilni biz bilan qoʻyib yubor», deb aytinglar, dedi.","U (Firʼavn): «Biz seni goʻdakligingdan oʻz ichimizda tarbiya qilmadikmi?! Umringning bir necha yilini bizning ichimizda oʻtkazmadingmi?!","Va nonkoʻrlardan boʻlib, qiladigan ishingni qilib qoʻymadingmi?!» dedi. (Firʼavnning minnatlaridan asosiy maqsadi–Muso alayhissalom olib kelgan dinni inkor qilish edi. Qoʻlimizda katta boʻla turib, endi, bizga, dinimizga va mulkimizga qarshi chiqasanmi? Yangi din keltirdim, deb daʼvo qilasanmi? Bizning qavmimizdan bir kishini oʻldirib qoʻymadingmi?!)","(Muso): «Oʻsha ishni qilgan boʻlsam, bilmasdan qilganman.","Bas, sizlardan xavfsirab qochib ketdim. Keyin Alloh menga hikmat berdi va meni Paygʻambarlardan qildi. (Oʻsha qitbtiy mening bir Bani Isroillik qabiladoshim bilan urishayotgan ekan. Qabiladoshim mendan yordam soʻradi, men uyega yordam beraman deb qibtiyni bir ursam oʻlib qoldi. Soʻngra xatoni tushundim.)","Oʻsha menga qilayotgan minnating Bani Isroilni qul qilib olganingdandir», dedi.","Firʼavn: «Robbul Olamiyn nima?» dedi.","U (Muso): «Agar anglamoqchi boʻlsangiz, U osmonlaru yer va ularning orasidagi narsalarning Robbidir», dedi.","U atrofidagi kishilarga: «Eshitmayapsizlarmi?!» dedi.","U(Muso): « U zot sizning Robbingiz va avvalgi ota-bobolaringizning Robbidir», dedi.","U: «Albatta, sizga yuborilgan Paygʻambaringiz jinnidir», dedi.","U(Muso): «U, agar aql yuritsangiz, mashriqu magʻribning va ular oʻrtasidagi narsalarning Robbidir», dedi.","U: «Agar mendan boshqani iloh qilib olsang, albatta, men seni zindonbandlardan qilurman», dedi.","U(Muso): «Agar men senga ochiq-oydin narsa keltirsam ham-a?!» dedi.","U: «Agar rostgoʻylardan boʻlsang, keltir uni!» dedi.","Bas, u (Muso) asosini tashladi. Banogoh u aniq ajdarga aylandi.","Va qoʻlini chiqardi. Banagoh u nazar qilguvchilarga oppoq koʻrindi.","U(Firʼavn) atrofidagi aʼyonlariga: «Albatta, bu oʻta bilimdon sehrgardir.","U oʻz sehri bilan sizlarni yeringizdan chiqarmoqchi, nima deysizlar?», dedi. (Xudoning diniga qarshi chiqqan, Allohning yoʻlidagi daʼvatchilarni oʻziga dushman bilgan tugʻyonkorlarning doimiy gaplaridan biri. Atrofidagi gumashtalariga va sodda xalqqa daʼvatchini xavfli qilib koʻrsatadi va ularni qoʻrqitadi.)","Ular: «Uni va akasini qoʻyib turgin-da, shaharlarga toʻplovchilarni yubor.","Senga barcha oʻta bilimdon sehrgarlarni olib kelsinlar», dedilar. (Bu taklif Firʼavnga maʼqul tushdi. Zotan, u atrofidagilardan aynan shu javobni kutgan edi. Boshqa sura va oyatlardan bilamizki, Muso alayhissalom bilan sehrgarlarning musobaqalashadigan joyi, vaqti va boshqa shartlari kelishib olinadi. Fiʼravn shaharlarga odamlarini yuborib, sehrgarlarni toʻplatib keladi.)","Bas, sehrgarlar maʼlum kuni kelishilgan vaqtda jamlandilar.","Va odamlarga: «Sizlar toʻplanib boʻldingizmi?","Ajab ermas, ustin kelsalar, sehrgarlarga ergashsak», deyildi. (Turli munosabatlar ila odamlarni toʻplash, bilan ularni chalgʻitish va oʻziga mahliyo etish ham tugʻyonkor hokimlarning odati. Sehrgarlar bilan Muso alayhissalom tortishuvini gʻanimat bilib rosa odam yigʻdilar.)","Sehrgarlar kelgan chogʻlarida Firʼavnga: «Agar biz gʻolib kelguvchi boʻlsak, bizga, albatta, haq beriladimi?» dedilar.","U: «Ha! U holda siz, albatta, eng yaqinlarimdan boʻlasiz», dedi.","Muso ularga: «Siz tashlaydigan narsangizni tashlang», dedi.","Bas, ular arqonlari va asolarini tashladilar va «Firʼavnning izzati bilan qasamki, albatta, biz gʻoliblarmiz», dedilar.","Soʻngra Muso asosini tashlagan edi, birdan u ularning uydirmalarini yuta boshladi. (Sehrgarlar arqonlarini tashlaganida, ilonga aylanmagan, ularning nayrangi tufayligina kishilar koʻziga shunday koʻringan edi, xolos. Keyin Muso alayhissalom asolarini tashladilar va u ajdarga aylanib, Firʼavn sehrgarlarining aso va arqonlarini yuta boshladi.)","Bas, sehrgarlar sajda qilgan hollarida yiqildilar.","Ular: «Robbul Olamiynga iymon keltirdik.","Muso va Horunning Robbiga», dedilar.","U: «Men sizga izn bermasimdan oldin unga iymon keltirdingiz! Albatta, u sizga sehr oʻrgatgan kattangizdir! Endi tezda bilasiz, men, albatta, qoʻl-oyogʻingizni qarama-qarshi tomonidan kesajakman va barchangizni osajakman», dedi.","Ular: «Zarari yoʻq. Albatta, biz Robbimizga qaytguvchimiz.","Moʻminlarning avvalgisi boʻlganimiz uchun Robbimiz xatolarimizni kechirishidan umid qilamiz», dedilar.","Va Musoga: «Bandalarim bilan kechasi yoʻlga chiq. Albatta, taʼqib etilursiz», deb vahiy yubordik.","Bas, Firʼavn shaharlarga toʻplovchilar yubordi:","«Shubhasiz, anavilar ozgina toifadirlar.","Albatta, ular bizni gʻazablantirguvchilardir.","Albatta, biz hammamiz hushyormiz», deb.","Bas, Biz ularni bogʻ-rogʻlar va buloqlardan.","Xazinalar va muhtaram maskandan chiqardik. (Yaʼni, Firʼavn va uning qavmini bogʻ-rogʻlaridan va buloqlaridan, xazinalaridan va hashamatli maskanlaridan chiqardik.","Ana shunday. Oʻsha(narsa)larni Bani Isroilga meros qilib berdik.","Bas, ularni quyosh chiqish paytida quvib yetdilar.","Ikki jamoat bir-birlarini koʻrgan chogʻida, Musoning odamlari: «Endi qoʻlga tushdik», dedilar.","U (Muso): »Yoʻq! Albatta, Robbim men bilan, U menga toʻgʻri yoʻlni koʻrsatur«, dedi.","Bas, Biz Musoga: «Asong bilan dengizni ur», deb vahiy qildik. Bas, u (dengiz) boʻlinib, har boʻlagi ulkan togʻdek boʻldi.","Va keyin boshqalarni ham yaqinlashtirdik. (Yaʼni, Firʼavn va uning askarlarini ham dengizga yaqinlashtirdik.)","Muso va unga ergashganlarga, hammalariga najot berdik.","Soʻngra boshqalarni gʻarq qildik. (Firʼavn va uning askarlari dengiz bagʻriga toʻliq tushib boʻlganlaridan keyin, ulkan togʻdek haybat-la toʻxtab turgan dengiz yana harakatga kelib, hammalarini halok qildi.)","Albatta, bunda oyat-belgi bor. Lekin koʻplari moʻmin boʻlmadilar.","Albatta, Robbing Oʻzi azizu mehribondir.","Va ularga Ibrohimning xabarini tilovat qilib ber.","Oʻshanda u otasi va qavmiga: «Nimaga ibodat qilmoqdasizlar?» degan edi.","Ular: «Sanamlarga ibodat qilmoqdamiz. Va ularga ixlos ila ibodat qilishda bardavom boʻlurmiz», dedilar. (Tosh yoki boshqa narsadan yuzi inson yuziga oʻxshatib ishlangan butga «sanam» deyiladi.)","U: «Iltijo qilganingizda ular sizni eshitadilarmi?","Yoxud naf yoki zarar yetkaza oladilarmi?» dedi.","Ular: «Yoʻq, biz ota-bobolarimizni shunday qilayotganlarini koʻrdik», dedilar.","U: «Nimaga ibodat qilayotganingizni bildingizmi?!","Siz va qadimgi otalaringiz?!","Albatta, Robbul Olamiyndan boshqa ularning barchasi menga dushmandir», dedi.","U meni yaratgan zotdir. Bas, meni hidoyat qiladi ham Uning Oʻzi.","Va meni taomlantiradigan va sugʻoradigan ham Uning Oʻzi.","Bemor boʻlganimda menga shifo beradigan ham Uning Oʻzi.","Meni oʻldiradigan, soʻngra tiriltiradigan ham Uning Oʻzi.","Va mening xatoimni qiyomat kuni magʻfirat qilishidan umidvor boʻlganim ham Uning Oʻzi.","Ey Robbim, menga hikmat hadya et va meni solihlarga qoʻshgin.","Va menga keyin kelguvchilar ichida sodiq maqtovlar boʻladigan qilgin. (Yaʼni, oʻtib ketganimdan keyin ham odamlar meni qiyomatgacha yaxshilik bilan eslab yuradigan qilgin.)","Va meni naʼiym jannati vorislaridan qilgin.","Va otamni magʻfirat qil. Albatta, u adashganlardan boʻldi.","Va qayta tiriltiriladigan kunda meni sharmanda qilmagin.","U kunda na mol manfaat berar va na bolalar.","Magar kim Alloh huzuriga toza qalb ila kelar, (oʻsha manfaat topar).","Va jannat taqvodorlarga yaqinlashtirildi.","Jahiym igʻvoga uchganlarga zohir qilindi.","Va ularga: »Allohdan oʻzga ibodat qilib yurgan narsalaringiz qani?!","Ular sizga yordam bera olurlarmi yoki oʻzlarini qutqara olurlarmi?! « deyildi.","Bas, unga ular, igʻvoga uchganlar.","Va Iblisning askarlari birgalikda yuztuban taxlab tashlandilar.","Ular uning ichida bir-birlari ila xusumat qilar ekanlar, dedilar:","«Allohga qasamki, albatta, biz ochiq-oydin adashuvda ekanmiz.","Chunki sizlarni Robbul Olamiynga tenglashtirardik.","Bizni faqat jinoyatchilar yoʻldan ozdirdilar.","Mana endi biz uchun shafoatchilar ham yoʻq.","Biron qadrdon doʻst ham yoʻq.","Qani endi ortga qaytsagu moʻminlardan boʻlsak».","Albatta, bunda oyat-belgi bor. Lekin koʻplari moʻmin boʻlmadilar.","Albatta, Robbing Oʻzi azizu mehribondir.","Nuh qavmi Paygʻambarlarni yolgʻonchi qildi.","Oʻshanda ularga birodarlari Nuh dedi: «U zotdan qoʻrqmaysizmi?!","Albatta, men sizlarga ishonchli Paygʻambarman.","Bas, Allohdan qoʻrqinglar va menga itoat qilinglar.","Men sizlardan buning uchun haq-ajr soʻramasman. Mening ajrim faqatgina Robbul Olamiynning zimmasidadir.","Bas, Allohdan qoʻrqinglar va menga itoat qilinglar».","Ular: «Senga pastkashlar ergashib turgan holda, biz senga iymon keltirarmidik?!» dedilar.","U dedi: «Mening ular nima qilayotganlari haqida ilmim yoʻq.","Agar sezsangiz, ularning hisobi faqat Allohning zimmasidadir.","Va men moʻminlarni haydab yuborguvchi emasman.","Men faqat ochiq-oydin ogohlantirguvchiman, xolos».","Ular: «Ey Nuh, agar toʻxtamasang, albatta, toshboʻron qilinganlardan boʻlursan», dedilar.","U: «Ey Robbim, shubhasiz, qavmim meni yolgʻonchi qildilar.","Bas, Oʻzing men bilan ularning oramizni yaxshilab ochgin va menga hamda men bilan birga boʻlgan moʻminlarga najot bergin», dedi.","Bas, Biz unga va u bilan birga boʻlganlarga toʻlgan kemada najot berdik.","Soʻngra qolganlarni gʻarq qildik.","Albatta, bunda oyat-belgi bor. Lekin koʻplari moʻmin boʻlmadilar.","Albatta, Robbing Oʻzi azizu mehribondir.","Od qavmi Paygʻambarlarni yolgʻonchi qildi.","Oʻshanda ularga birodarlari Hud dedi: «Qoʻrqmaysizlarmi?!","Albatta, men sizlarga ishonchli Paygʻambarman.","Bas, Allohdan qoʻrqinglar va menga itoat qilinglar.","Men sizlardan buning uchun haq-ajr soʻramasman. Mening ajrim faqatgina Robbul Olamiyn zimmasidadir.","Har tepalikka bir belgi boʻladigan bino qurib, behuda oʻyin qilaverasizmi?","Va xuddi mangu turajakdek «masnaʼlar» tutaverasizmi?. (Oyatdagi «masnaʼlar» soʻzi hozirgi arab tilida zavod-fabrikalar maʼnosida ishlatilmoqda. Od qavmi ulkan qasrlar qurish, togʻlarni oʻyib ishlash va boshqa faxr uchun koʻtaradigan binolarida foydalanadigan asbob-uskunalarni ishlab chiqaradigan ishxonalarga ega edi, «masoneʼlar»dan murod oʻshalar, oyatda qurilishlarga doir ochiq-oydin maʼno bor.)","Tutganingizda oʻta jabrchi boʻlib tutdingiz.","Bas, Allohdan qoʻrqing va menga itoat qiling.","Sizga oʻzingiz bilgan narsa ila madad bergan zotdan qoʻrqing.","U sizlarga chorva hayvonlari va farzandlar ila madad berdi.","Bogʻ-rogʻlar va buloqlar ila.","Men, albatta, sizga ulugʻ kunning azobi kelishidan qoʻruraman».","Ular: «Biz uchun vaʼz qilsang ham yoki vaʼz qilguvchilardan boʻlmasang ham, baribir.","Bu eskilarning odati, xolos.","Biz azoblanguvchi emasmiz», dedilar. (Yaʼni, bizga qancha gapirsang ham, baribir sen aytgan yoʻldan yurmaymiz. Bu qilmishimiz uchun, sen aytayotganingdek, azoblanmaymiz ham, dedilar.)","Ular u(Hud)ni yolgʻonchi qildilar. Bas, Biz ularni halok qildik. Albatta, bunda oyat-belgi bor. Lekin koʻplari moʻmin boʻlmadilar.","Albatta, Robbing Oʻzi azizu mehribondir.","Samud qavmi Paygʻambarlarni yolgʻonchi qildi.","Oʻshanda ularga birodarlari Solih dedi: «Qoʻrqmaysizlarmi?!","Albatta, men sizlarga ishonchli Paygʻambarman.","Bas, Allohdan qoʻrqinglar va menga itoat qilinglar.","Men sizlardan buning uchun haq-ajr soʻramasman. Mening ajrim faqatgina Robbul olamiyn zimmasidadir.","Siz bu joydagi narsalarda omon holda tark qilinasizmi?!","Bogʻ-rogʻlarda, buloqlarda?!","Ekinzorlaru mayin xurmozor ichlarida-ya?!","Va togʻlardan manmanlik-la uylar yoʻnaverasizmi?!","Bas, Allohdan qoʻrqinglar va menga itoat qilinglar.","Va yer yuzida isrofchilik qiladiganlarning ishiga itoat qilmanglar.","Buzgʻunchilik qiladigan, islohchilik etmaydiganlarning».","Ular: «Sen, albatta, sehrlanganlardandirsan.","Sen bizga oʻxshagan bashardan boshqa hech narsa emassan. Agar rostgoʻylardan boʻlsang, oyat-moʻjiza keltir», dedilar. (Samud qavmi ularga Allohning gapini yetkazgan Paygʻambarlari Solihga alayhissalom, algʻov-dalgʻov gapirmoqdasan, aniq sehrlangansan, deb tuhmat qildilar. Kofirlar nazdida, Allohning yoʻliga chaqiruvchilar doimo majnun yoki sehrlangan boʻlib koʻrinadi.)","U: «Mana bu tuya. Unga (bir kun) suv ichish va sizga maʼlum bir kun suv ichish.","Va unga yomonlik yetkazmanglar, unda sizni ulugʻ kunning azobi tutadir», dedi. (Boshqa oyatlarda bayon etilganidek, tuyaning toshdan chiqarilishining oʻzi moʻjiza boʻlgan edi. Endi oʻsha moʻjiza tuyaning Samud qavmi ichida turish sharti qoʻyildi.","Bas, u(tuya)ni soʻydilaru nadomat chekuvchiga aylandilar.","Bas, ularni azob tutdi. Albatta, bunda oyat-belgi bor. Lekin koʻplari moʻmin boʻlmadilar.","Albatta, Robbing Oʻzi azizu mehribondir.","Lut qavmi Paygʻambarlarni yolgʻonchi qildi.","Oʻshanda ularga birodarlari Lut dedi: «Qoʻrqmaysizlarmi?!","Albatta, men sizlarga ishonchli Paygʻambarman.","Bas, Allohdan qoʻrqinglar va menga itoat qilinglar.","Men sizlardan buning uchun haq-ajr soʻramasman. Mening ajrim faqatgina Robbul Olamiyn zimmasidadir.","Olamlar ichidan erkaklarga borasizmi?!","Va Robbingiz siz uchun yaratgan jufti halollaringizni tark qilasizmi?! Yoʻq!!! Siz haddan oshgan qavmsiz».","Ular: «Ey Lut, agar toʻxtamasang, albatta, haydab chiqarilganlardan boʻlursan!» dedilar.","U: «Albatta, men bu ishingizni oʻta yomon koʻrguvchilardanman.","Ey Robbim, menga va ahlimga qilayotgan narsalaridan najot bergin!» dedi.","Bas, unga va ahliga, hammalariga najot berdik.","Magar (azobda) qolguvchilardan boʻlgan bir kampirga (bermadik).","Soʻngra qolganlarini yer bilan yakson qildik.","Va ularning ustiga bir yomgʻir yogʻdirdikki, bas, ogohlantirilganlarning yomgʻiri qandoq ham yomon boʻldi. (Shuning uchun ham hanafiy mazhabidagi baʼzi faqihlar, Lut alayhissalom qavmi kirdikorini qilgan bachchavozlarni, toshboʻron qilib oʻldirish kerak, deydilar.)","Albatta, bunda oyat-belgi bor. Lekin koʻplari moʻmin boʻlmadilar.","Albatta, Robbing Oʻzi azizu mehribondir.","Qalin daraxtzor egalari Paygʻambarlarni yolgʻonchi qildilar. (Bu oyatda zikri kelayotgan «qalin daraxtzor» Madyan oʻlkasidir. Alloh taolo Shuaybni alayhissalom shu yerga Paygʻambar etib yubordi. Shuayb alayhissalom qissasini, Hijr surasida oʻrganganmiz.)","Oʻshanda ularga birodarlari Shuayb dedi: «Qoʻrqmaysizlarmi?!","Albatta, men sizlarga ishonchli Paygʻambarman.","Bas, Allohdan qoʻrqinglar va menga itoat qilinglar.","Men sizlardan buning uchun haq-ajr soʻramasman. Mening ajrim faqatgina Robbul Olamiyn zimmasidadir.","Bas, oʻlchovni toʻliq oʻlchanglar va kamaytirguvchilardan boʻlmanglar.","Va toʻgʻri tarozi ila tortinglar.","Odamlarning narsalarini kamaytirib bermang. Yer yuzida turli buzgʻunchiliklar qilmanglar.","Sizni va avvalgi nasllarni yaratgan zotdan qoʻrqing».","Ular: «Albatta, sen sehrlanganlardansan.","Va sen bizga oʻxshagan bashardan boshqa narsa emassan. Biz seni, albatta, yolgʻonchilardan, deb biuramiz.","Agar rostgoʻylardan boʻlsang ustimizdan osmonning bir boʻlagini tashlavor», dedilar.","U: «Robbim qilayotgan ishingizni oʻta yaxshi bilguvchidir», dedi.","Bas, ular u(Shuayb)ni yolgʻonchi qildilar. Bas, ularni «soyabon» kuni azobi tutdi. Albatta, u ulugʻ kunning azobi edi. ( Alloh taolo Ayka xalqini azobga duchor etishni iroda qilganida havoni oʻta isitib yubordi. Shunda pastlab kelayotgan bulut paydo boʻldi. Bulut ularga soyabon boʻlib koʻrindi. Hammalari oʻzlarini bulut soyasiga urdilar. Jinoyatchi qavmning hammasi bulut soyasiga kirib boʻlgandan soʻng, birdan chaqmoq chaqib, bulutdan oʻt-olov chiqib ularni halok etdi.)","Albatta, bunda oyat-belgi bor. Lekin koʻplari moʻmin boʻlmadilar.","Albatta, Robbing Oʻzi azizu mehribondir.","Albatta, u (Qurʼon) Robbul Olamiynning tushirganidir.","Uni Ruhul amiyn olib tushdi.","Sening qalbingga, ogohlantirguvchilardan boʻlishing uchun.","Ochiq-oydin arab tilida. («Ruhul Amiyn»dan murod Jabroil farishta alayhissalom; «ogohlantirguvchilardan» degani Paygʻambarlardan degan maʼnoni bildiradi. Yaʼni, Qurʼonni Jabroil sening qalbingda Paygʻambarlardan boʻlishing uchun ravshan arab tilida olib tushdi.)","Albatta, u (Qurʼon) avvalgilarining kitoblarida ham bordir. ( Qurʼonning zikri, avvalgi ummatlarning ilohiy kitoblarida ham bordir.)","Uni Bani Isroil ulamolarining bilishlari, ular uchun oyat-dalil emasmi?!","Agar Biz uni baʼzi ajamiylarga nozil qilsak.","Bas, u ularga uni oʻqib bersa ham, moʻmin boʻlmas edilar.","Biz u(Qurʼon)ni jinoyatchilar qalblariga ana shunday yoʻlladik. (Ular uni eshitadilar, maʼnolarini tushunadilar, ammo iymon keltirmaydilar.)","Ular unga to alamli azobni koʻrmagunlaricha iymon keltirmaslar.","Bas, ularga u(azob) toʻsatdan kelur. Ular sezmay qolurlar.","Shunda ular: «Bizga muhlat berilarmikan?!» derlar.","Bizning azobimizning tezroq kelishini istaydilarmi-ya?!","Aytgin-chi, agar Biz ularni yillarcha huzurlantirsak-da.","soʻngra ularga vaʼda qilingan narsa kelsa.","Oʻsha huzurlanib yurgan narsalari nimaga asqotur?!","Biz biron shahar-qishloqni halok qilgan boʻlsak, albatta, uning ogohlantirguvchilari boʻlgan.","Eslatma boʻlishi uchundir. Biz zulm qilguvchi boʻlmasdik.","U(Qurʼon)ni shaytonlar olib tushganlari yoʻq. (Mushriklar daʼvo qilayotganlaridek, Qurʼonni shaytonlar olib tushganlari yoʻq. Ularning bu gaplari boʻhtondan iborat.)","Bunga ularning imkonlari yoʻq va unga qodir ham emaslar.","Albatta, ular eshitishdan chetlatilgandirlar.","Alloh bilan birga boshqa ilohga iltijo qilma. Yoʻqsa, azoblanganlardan boʻlursan. (Paygʻambarning (s. a. v.) Allohga shirk keltirishlari mutlaqo mumkin emas. Ammo bu oyatda shirkning naqadar ulkan gunoh ekanligini anglatish uchun farazan shu maʼno keltirilgan. Paygʻambardek (s. a. v.) zot shirk keltirib, azobdan qutula bilmasa, boshqalarning holi nima boʻlishini bilib olish qiyin emas.)","Va yaqin qarindoshlaringni ogohlantir.","Va senga ergashgan moʻminlarga qanotingni pastlat.","Bas, agar ular senga isyon qilsalar: «Men siz qilayotgan amallardan bezorman», degin.","Va aziz va mehribon zotga tavakkal qil;","Seni qoim boʻlganingda koʻradigan.","Va sajda qilguvchilar ichida harakatlanishingni (koʻradigan) zotga. (Yaʼni, yolgʻizligingni ham, namozda qoim boʻlganingni, shuningdek, moʻminlar ichida turli ishlarga bosh boʻlib yurganingni ham koʻrib turadigan zotga–Allohga tavakkal qil.)","Albatta, Uning Oʻzi oʻta eshitguvchi va oʻta bilguvchi zotdir.","Sizlarga shaytonlar kimga tushishini aytib beraymi?","Ular oʻta uydirmachi va oʻta gunohkorlarga tushurlar.","Ular (shaytonlarga) quloq osarlar. Va ularning koʻplari yolgʻonchilardir.","Va shoirlarga gumrohlar ergashur.","Ularning har vodiyda daydishini.","Va oʻzlari qilmaydigan ishlarni aytishini koʻrmadingmi?","Magar iymon keltirib, solih amallar qilganlar, Allohni koʻp zikr etganlar va mazlum boʻlganlaridan keyin nusrat qozonganlar (unday emaslar). Zulm qilganlar esa, tezda qaysi agʻdarilish joyiga agʻdarilishlarini bilurlar. (Hamma shoir ham har vodiyda daydiydigan, beamal gapiradigan boʻlavermas ekan. Agar shoir iymonli, yaxshi amalli, Allohni koʻp esga oladigan, oʻzini xor qilmay, haqqini tanigan, zolimlar ustidan gʻolib keladigan boʻlsa, Allohning roziligini topgan shoir boʻlishi mumkin.)"]};
